def _апгрейды_из(st: dict, ключ: str) -> set[str]:
    """Имена апгрейдов из поля состояния. ТОЛЬКО СВОИ: чужих человек не видит,
    и блок их не пишет (правило игрока, 16.09)."""
    return {у.strip() for у in str(st.get(ключ, "") or "").split(",") if у.strip()}


def взятые_апгрейды(st: dict) -> set[str]:
    return _апгрейды_из(st, "upg_done")


def идущие_апгрейды(st: dict) -> set[str]:
    return _апгрейды_из(st, "upg_doing")


def уже_проверено(путь: str = "") -> str:
    """Итоги отыгранных идей — одной строкой каждая, для критика.

    Критику дают дневник ТЕКУЩЕЙ партии и больше ничего: ни world.md, ни
    прошлых серий. Поэтому 16.09 он предложил ставить шахту золота раньше
    казармы — ровно ту идею, что серия gold_first2 отыграла 15.09 и
    опровергла: механика сработала (шахта на 188-й секунде против 358-й), а
    цель стала 0 из 9 против 2 из 9. Гипотеза стоит серии, и тратить её на уже
    отвеченный вопрос — потеря дня.

    Берём поле «итог» из experiments.ini: там результаты и так записаны.
    """
    путь = путь or os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "docker", "experiments.ini")
    if not os.path.exists(путь):
        return ""
    cfg = configparser.ConfigParser()
    try:
        cfg.read(путь, encoding="utf-8")
    except configparser.Error:
        return ""
    строки = []
    for имя in cfg.sections():
        итог = " ".join((cfg[имя].get("итог", "") or "").split())
        if итог:
            строки.append(f"  {имя}: {итог[:220]}")
    if not строки:
        return ""
    return ("\n\nУЖЕ ОТЫГРАНО СЕРИЯМИ — не предлагай это снова как новое:\n"
            + "\n".join(строки[:12]))


def карта_открыта(st: dict) -> bool:
    """Открыта ли карта (монгольфьер выдан всем, --balloon 2).

    Одна функция на весь мост: замок на числа врага стоит в нескольких местах,
    и две копии одного условия однажды разойдутся.
    """
    return str(st.get("map_open", "")).lower() in ("1", "true", "да", "yes")


def поле_врага(st: dict, mp: dict, поле: str):
    """Число врага по имени поля: p<номер>_<поле>. None, если его нет.

    Замок на открытую карту тут НЕ ставится: его ставит тот, кто зовёт, — и
    ставит один раз на весь блок. Две проверки в двух местах однажды разойдутся.
    """
    зн = None
    for п in range(8):
        ист = mp if f"p{п}_{поле}" in mp else st
        if st.get(f"p{п}_enemy") and f"p{п}_{поле}" in ист:
            зн = ист[f"p{п}_{поле}"]
    return зн


def цена_армии(st: dict) -> dict:
    """Во что обошлась армия, по ценам найма из состояния.

    Слагаемое «армейская стоимость» из формулы готовности, которую назвал игрок.
    Считается ПРИБЛИЖЁННО и честно об этом говорит: состояние знает три класса
    (пехота, стрелки, конница), а цена есть у конкретных ролей, поэтому класс
    считается по цене первой роли своего вида из строки найма. Точнее нельзя:
    в mil_inf сложены все пехотинцы, какими бы они ни были.
    """
    цены: dict[str, dict[str, int]] = {}
    for кусок in str(st.get("fighters", "") or "").split():
        роль, _, хвост = кусок.partition("=")
        части = хвост.split(",")
        цены[роль] = {}
        for ч in части[1:]:
            м = re.fullmatch(r"([a-z]+)(-?\d+)", ч)
            if м and м.group(1) in РЕСУРС_РУС:
                цены[роль][м.group(1)] = int(м.group(2))
    класс_роль = (("mil_inf", ("infantry17", "uniq_inf17")),
                  ("mil_shooters", ("musk17",)),
                  ("mil_cav", ("dragoon17",)))
    итог: dict[str, int] = {}
    for поле, роли in класс_роль:
        сколько = _чис(st.get(поле))
        if not сколько:
            continue
        цена = next((цены[р] for р in роли if цены.get(р)), {})
        for рес, за_штуку in цена.items():
            итог[рес] = итог.get(рес, 0) + за_штуку * сколько
    return {к: v for к, v in итог.items() if v}


def отобрать_апгрейды(спис: list[str], st: dict) -> tuple[list[str], int, str]:
    """Какие апгрейды показать модели: (видно, сколько скрыто, чем резали).

    До 15.09 резалось по порядку — первые сорок из двухсот двадцати. В этих
    сорока у Нидерландов оказались `l, cen.1, mil.1, mil.2` и `aca.1…aca.36`,
    то есть ТРИДЦАТЬ ШЕСТЬ апгрейдов академии, которую боту запрещено строить
    (`--ban market,academi`), и НИ ОДНОГО военного: `bar.pikeman.2.1` стоит в
    списке сто первым. Серия `upgrades` 15.09 из-за этого проверила не идею, а
    обрезку: 21 команда из 30, отданных с намерением «взять защиту пикинёра»,
    ушла именем мельницы `mil.1`.

    Отбираем то же, что видит человек: апгрейды ЗДАНИЙ, КОТОРЫЕ У НЕГО СТОЯТ.
    Он открывает казарму и видит там линейки атаки и защиты своей пехоты; он не
    видит апгрейдов академии, пока академии нет. Это сужение, а не фора.
    """
    бойцы = _мои_бойцы(st)
    стоят = {место for место, ключ in МЕСТО_АПГРЕЙДА.items()
             if _чис(st.get(ключ)) > 0}
    # ВЗЯТОЕ И ОПЛАЧИВАЕМОЕ из списка убираем. Человек в казарме видит уже
    # купленную линейку закрытой и второй раз её не покупает, а модель до
    # 16.09 не знала о своих апгрейдах ничего и могла заказывать одно и то же.
    _мимо = взятые_апгрейды(st) | идущие_апгрейды(st)
    спис = [у for у in спис if у not in _мимо]
    военные: list[str] = []
    здания: list[str] = []
    for у in спис:
        части = у.split(".")
        if len(части) == 4 and части[0] in стоят and части[1] in бойцы:
            военные.append(у)
        elif len(части) == 2 and части[0] in стоят:
            здания.append(у)
    # Порядок бойцов — как в списке найма: первым идёт то, кем воюют. Внутри
    # одного бойца имена уже отсортированы игрой: вид, потом уровень.
    военные.sort(key=lambda у: (бойцы.index(у.split(".")[1]), у))
    отобрано = военные + здания
    if not отобрано:
        # Ни одного подходящего — старый мост без `fighters`, либо у нас ещё
        # ничего не построено. Возвращаемся к прежнему поведению, чтобы правка
        # не могла сделать хуже, чем было.
        видно = спис[:СПИСОК_АПГРЕЙДОВ]
        return видно, len(спис) - len(видно), ""
    видно = отобрано[:СПИСОК_АПГРЕЙДОВ]
    чем = ("показаны апгрейды зданий, которые у тебя СТОЯТ, и только для тех "
           "бойцов, кого ты можешь нанять")
    return видно, len(спис) - len(видно), чем

ИСХОД_СЛОВОМ = {"win": "ПОБЕДА", "lose": "ПОРАЖЕНИЕ"}


def _число(v):
    """Строка игры -> int, если это число. Иначе как есть."""
    try:
        return int(str(v).strip())
    except (TypeError, ValueError):
        return v


def конец_партии(a, br, исход: str, gt: int) -> str:
    """Партия кончилась, и мы знаем чем. Сказать вслух и дописать в трассу.

    До 13.09 мост этого не умел вовсе: движок ставит victorystate и тут же
    паузу симуляции, блок состояния замирает вместе с ней, а политика видела
    только «состояние не обновлялось 30 с» и печатала три догадки. Исход при
    этом лежал в двух файлах, которые никто не читал.
    """
    mm, ss = divmod(int(gt), 60)
    слово = ИСХОД_СЛОВОМ.get(исход, исход)
    print(f"\n{'=' * 60}\n{слово} на {mm}:{ss:02d} игрового времени\n{'=' * 60}")
    if исход == "lose":
        print("Базы и населения не осталось: движок засчитывает поражение, когда\n"
              "у игрока нет ни занятых жилых мест, ни ратуши (progress.inc).")
    if a.botlog:
        try:
            with open(a.botlog, "a", encoding="utf-8") as f:
                f.write(json.dumps({
                    "gt": int(gt), "finish": исход,
                    # br.raw — это СТРОКИ, как их пишет игра. В записях тактов
                    # снимок уже приведён к числам, и разнотипица в одной трассе
                    # молча ломает счёт: '0' + '0' даёт '00', а не 0.
                    "state": {k: _число(br.raw.get(k)) for k in (
                        "gametime", "peasants", "mil_inf", "mil_shooters",
                        "food", "wood", "stone", "gold", "iron", "my_farmused")
                        if br.raw.get(k) is not None},
                }, ensure_ascii=False) + "\n")
        except OSError:
            pass                            # трасса не должна ронять партию
    return "победа" if исход == "win" else "поражение"


def отметить_конец(a, st: dict, gt: int, исход: str) -> None:
    """Запись `finish` в трассу. Без неё отчёт не знает, чем кончилась партия.

    14.09: цель и горизонт возвращались из цикла простым return, запись делал
    только конец_партии (победа/поражение от игры). В трассе отметки не было, а
    run_report ищет именно её — и пятнадцать партий, среди которых была ВЗЯТАЯ
    ЦЕЛЬ на 12:07, вышли в отчёте как «не кончилась, цель не взята». Ошибка
    измерения, вторая в проекте после счёта крестьян врага от старта.
    """
    if not a.botlog:
        return
    try:
        with open(a.botlog, "a", encoding="utf-8") as f:
            f.write(json.dumps({
                "gt": int(gt), "finish": исход,
                # my_farm, centers и ba17 тут не для красоты: без них разбор
                # видит «занято 127 из 0» и делает ложный вывод про лимит
                # населения — 14.09 критик так и сделал, а запас мест ни разу не
                # падал ниже 69.
                "state": {k: _чис(st.get(k)) for k in (
                    "gametime", "peasants", "mil_inf", "mil_shooters",
                    "food", "wood", "stone", "gold", "iron",
                    "my_farmused", "my_farm", "centers", "ba17", "mills",
                    "mines_iron", "mines_gold")
                    if st.get(k) is not None},
            }, ensure_ascii=False) + "\n")
    except OSError:
        pass                                # трасса не должна ронять партию


def снять_чужую_волну(st: dict | None, волны: list, сказано: list) -> int:
    """Убирает из состояния волну ПРОШЛОЙ партии.

    `wave_sent` мост кладёт в именованный парсер `br_hwave`, а тот живёт в игре
    и переживает КОНЕЦ ПАРТИИ: новая партия начинается с числом старой. 16.09
    по 27 партиям: в 15 (все вторые и третьи эпизоды) модель с пятой секунды
    читала «в походе 8-50 бойцов», которых на карте не было, и держалось это до
    конца партии. Ни одна её жалоба на «волна не доходит» в таких партиях не
    значила ничего.

    Правило 1 проекта: молчаливый отброс неотличим от бездействия — поэтому
    первый раз за партию мост говорит, что именно он снял и почему.

    Возвращает снятое число (0, если снимать было нечего).
    """
    if not st or волны:          # своя волна ушла — поле снова честное
        return 0
    try:
        было = int(float(st.get("wave_sent") or 0))
    except (TypeError, ValueError):
        было = 0
    if было:
        st["wave_sent"] = 0
        if not сказано:
            сказано.append(True)
            print(f"        wave_sent={было} — это волна ПРОШЛОЙ партии "
                  f"(парсер br_hwave переживает конец партии). Снято: в этой "
                  f"партии ATTACK ещё не было.")
    return было


def stalled(d: str, plind: int, no_mode: bool) -> None:
    """Состояние встало. Причин три, и они различимы."""
    path = os.path.join(d, f"coss3_eco_P{plind}.dat")
    try:
        age = time.time() - os.path.getmtime(path)
    except OSError:
        print(f"файл состояния {path} исчез — игра закрыта?")
        return
    print(f"состояние не обновлялось {age:.0f} с (игра пишет его каждые 2–5 с)")
    print("  1. Игра свёрнута или на паузе? Симуляция встаёт вместе с окном —\n"
          "     оставьте окно игры активным, скрипт работает в фоне.")
    print("  2. Партия кончилась (победа или поражение)? При поражении движок\n"
          "     ставит паузу симуляции, и блок замирает вместе с ней.")
    if not no_mode:
        print("  3. Виноват MODE 1? Проверяется одной командой — если с ней\n"
              "     состояние идёт, дело в нём:\n"
              "       python llm_policy.py --no-mode --every 30")
    print("  Посмотреть, что игра пишет на самом деле:\n"
          "    powershell -ExecutionPolicy Bypass -File .\\watch.ps1")


TRANSIENT = ("500", "502", "503", "504", "timed out", "timeout",
            "connection", "overloaded", "too many requests", "429")


def think_worker(box: dict, client, model: str, prompt: str, think: bool,
                 tries: int = 3, spare: str = "") -> None:
    """Зовёт модель в фоне. Цикл тем временем живёт своей жизнью.

    500-е и таймаумы у бесплатного тира — обычное дело. Раз вызов не держит
    цикл, повтор бесплатен: пробуем несколько раз с паузой, и такт пропадает
    только если провайдер лежит целиком.
    """
    box["log"] = []
    очередь = [model] + ([spare] if spare else [])
    попытка = 0
    for кто in очередь:
        for n in range(tries):
            попытка += 1
            t = time.time()
            try:
                box["data"] = ask(client, кто, prompt, think)
                box["ready"] = time.time()   # когда ОТВЕТ готов, а не когда его забрали
                # Кто обслужил и сколько написал: у OpenRouter один и тот же id
                # уходит к разным провайдерам, и медленный вызов — обычно не
                # «модель думала», а «попали не к тому». Глобальные LAST_* к
                # моменту печати успевает затереть следующий вызов, поэтому
                # снимаем их здесь.
                box["provider"], box["tokens"] = LAST_PROVIDER, LAST_TOKENS
                box["tries"] = попытка
                box["model"] = кто
                return
            except Exception as e:
                msg = str(e).lower()
                box["err"] = e
                box["tries"] = попытка
                врем = any(w in msg for w in TRANSIENT)
                лимит = "429" in msg or "rate-limit" in msg
                box["log"].append(
                    f"{попытка}) {кто.split('/')[-1]}, {time.time() - t:.0f} с, "
                    f"{'лимит' if лимит else 'временная' if врем else 'НЕ временная'}: "
                    f"{str(e)[:160]}")
                if not врем:
                    return                  # не наша беда, ни повтор, ни замена не спасут
                if n + 1 >= tries:
                    break                   # эта модель не отвечает — пробуем запасную
                # Лимит провайдера полутора секундами не пересидеть: он общий
                # на всех и держится десятками секунд. Вызов в фоне, ждать дёшево.
                time.sleep((6.0 if лимит else 1.5) * (n + 1))


class Tee:
    """Пишем и в консоль, и в файл — overlay.ps1 показывает хвост этого файла.

    Строка уходит в файл сразу (buffering=1): окно поверх игры должно видеть
    решение в тот же миг, что и консоль, иначе смысла в нём нет.
    """

    def __init__(self, поток, path: str):
        self.поток = поток
        # Прежний лог не затираем, а отодвигаем в сторону. 11.09.2026 один
        # `--check` во время боя стёр лог партии целиком: файл открывался на
        # "w", а лог — единственная запись того, что делала модель.
        try:
            if os.path.getsize(path) > 0:
                метка = time.strftime("%m-%d_%H%M", time.localtime(os.path.getmtime(path)))
                корень, хвост = os.path.splitext(path)
                os.replace(path, f"{корень}.{метка}{хвост}")
        except OSError:
            pass                            # нет файла или не переименовать — не беда
        self.файл = open(path, "w", encoding="utf-8", buffering=1)

    def write(self, s: str) -> int:
        self.поток.write(s)
        try:
            self.файл.write(s)
        except Exception:
            pass                            # лог не должен ронять партию
        return len(s)

    def flush(self) -> None:
        self.поток.flush()
        try:
            self.файл.flush()
        except Exception:
            pass

    def isatty(self) -> bool:
        return False


def раскодировать(сырое: bytes) -> str:
    """Байты подсказок -> текст, какой бы редактор их ни сохранил.

    Файл правят и на маке, и на Windows: PowerShell при `>` пишет UTF-16LE,
    старые редакторы — CP1251, «Блокнот» умеет добавить BOM. Несовпадение
    кодировки не должно ронять партию, поэтому перебираем по очереди, а в
    самом конце декодируем с заменой — пусть лучше кракозябры, чем падение.
    """
    for bom, кодировка in ((b"\xef\xbb\xbf", "utf-8-sig"),
                           (b"\xff\xfe", "utf-16"),
                           (b"\xfe\xff", "utf-16")):
        if сырое.startswith(bom):
            try:
                return сырое.decode(кодировка).strip()
            except UnicodeDecodeError:
                break
    for кодировка in ("utf-8", "cp1251"):
        try:
            return сырое.decode(кодировка).strip()
        except UnicodeDecodeError:
            continue
    return сырое.decode("utf-8", "replace").strip()


_ПОДСКАЗКИ = {"текст": "", "когда": 0.0, "откуда": ""}


# Строки, дописанные ключом --hint-add. Живут глобально, потому что подсказки
# перечитываются из файла на каждом такте, а дописка должна переживать это.
ДОПИСКИ: list[str] = []


def _подсказки_из_файла(path: str, max_age: float = 10.0) -> str:
    """Подсказки из файла или по ссылке.

    Ссылка нужна, чтобы править их с другой машины: игра идёт на Windows, а
    редактировать удобнее с макбука. Сеть тут на горячем пути — промпт
    собирается в главном цикле, — поэтому таймаут короткий, ответ кешируется
    на max_age секунд, а при любой беде берётся последний удачный текст.
    Партия важнее свежести подсказок.
    """
    if path.startswith(("http://", "https://")):
        now = time.time()
        if _ПОДСКАЗКИ["откуда"] == path and now - _ПОДСКАЗКИ["когда"] < max_age:
            return _ПОДСКАЗКИ["текст"]
        try:
            import urllib.request
            with urllib.request.urlopen(path, timeout=3) as r:
                текст = раскодировать(r.read())
            _ПОДСКАЗКИ.update(текст=текст, когда=now, откуда=path)
            return текст
        except Exception:
            _ПОДСКАЗКИ["когда"] = now      # не долбить сеть каждый такт
            return _ПОДСКАЗКИ["текст"]
    try:
        сырое = open(path, "rb").read()
    except OSError:
        return ""
    return раскодировать(сырое)



def load_hints(path: str, max_age: float = 10.0) -> str:
    """Подсказки из файла плюс дописки ключа --hint-add.

    Дописка — это способ проверить идею КАК ЗНАНИЕ: модель узнаёт о
    возможности и решает сама, вместо того чтобы мост подменял её команду.
    13.09 игрок указал, что подмена нечестна — модель отдала BUILDERS 3,
    увидела мир, где ратуша встала втрое быстрее, и рассуждала дальше о том,
    чего не делала.
    """
    текст = _подсказки_из_файла(path, max_age)
    if ДОПИСКИ:
        текст = текст.rstrip("\n") + "\n" + "\n".join(ДОПИСКИ) + "\n"
    return текст

def _мастер_мира() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "world.md")


def _прочесть(path: str) -> str:
    try:
        return раскодировать(open(path, "rb").read())
    except OSError:
        return ""


def load_world(path: str) -> str:
    """Файл мира -> готовый раздел промпта. Нет файла — пустая строка.

    Читается ДВА файла и склеивается: мастер рядом со скриптом (он приезжает из
    git и держит знания) и рабочий в /io (в нём копятся вопросы этой серии).
    Иначе получается то, что вышло 13.09 дважды подряд: рабочий файл от прошлого
    прогона уже лежал в томе, посев не делался — и знания из git не доезжали
    вовсе, а в логе стояло безобидное «0 строк знания».

    Читается перед каждым решением, как и подсказки: отвечать на вопрос модели
    удобно, не останавливая партию. Только локальные файлы, без ссылок.
    """
    if not path:
        return ""
    текст = _прочесть(path)
    мастер = _мастер_мира()
    if os.path.abspath(мастер) != os.path.abspath(path):
        текст = _прочесть(мастер) + "\n" + текст
    return мир_для_промпта(текст)


def подготовить_мир(path: str) -> None:
    """Посев файла мира из мастера рядом со скриптом.

    В контейнере клон моста одноразовый: что модель туда запишет, сгинет вместе
    с контейнером. Поэтому играть надо на файле в /io — он уезжает в результаты
    вместе с трассой. Но начальное знание лежит в git, рядом со скриптом, и
    копировать его руками в entrypoint нельзя: скрипты контейнера запечены в
    образ и из git не обновляются. Значит сеем отсюда.
    """
    if not path or os.path.exists(path):
        return
    мастер = os.path.join(os.path.dirname(os.path.abspath(__file__)), "world.md")
    if os.path.abspath(мастер) == os.path.abspath(path):
        return
    if not os.path.exists(мастер):
        # 13.09 это стоило целой серии: в контейнер копировались только
        # *.py/*.inc/*.txt, world.md не доезжал, посев молча не делался, и все
        # четыре копии играли с ПУСТЫМ описанием мира. В логе не было ни слова.
        print(f"МАСТЕР МИРА НЕ НАЙДЕН: {мастер}. Модель начнёт с пустого "
              f"описания мира — знания в промпт не пойдут, только канал вопросов")
        return
    try:
        os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
        with open(мастер, "rb") as и, open(path, "wb") as к:
            к.write(и.read())
        print(f"мир посеян: {мастер} -> {path}")
    except OSError as e:
        print(f"мир не посеян ({e}) — модель начнёт с пустого")


def find_ai_plind(d: str, fresh: float = 30, human: bool = False) -> int | None:
    """Чей слот вести. На компьютерном ищем bai, на человеческом — human:
    правила хакатона требуют играть за человека, а там флага bai нет вовсе."""
    best, best_mtime = None, -1.0
    try:
        names = os.listdir(d)
    except OSError:                          # каталога нет — разбираться будет diagnose
        return None
    for name in names:
        m = re.fullmatch(r"coss3_eco_P(\d+)\.dat", name)
        if not m:
            continue
        n = int(m.group(1))
        mtime = os.path.getmtime(os.path.join(d, name))
        if fresh and time.time() - mtime > fresh:
            continue
        try:
            st = Bridge(d, n).read_state() or {}
        except Exception:
            continue
        свой = st.get("human") if human else st.get("bai")
        if свой and mtime > best_mtime:
            best, best_mtime = n, mtime
    return best


# Роль в заказе -> счётчик в состоянии, по которому видно исполнение.
# Роль в заказе -> ключ в состоянии. Имена НЕ совпадают: роль minegold, ключ
# mines_gold; роль market, ключ markets. Проверял по списку ключей из
# block_state.inc, а не по догадке — на этом уже ошибался.
СЧЁТЧИК = {
    "center": "centers", "mill": "mills", "smith": "smiths",
    "ba17": "ba17", "ba18": "ba18", "store": "my_stores", "house": "houses",
    "tower": "my_towers", "market": "markets", "stable": "stables",
    "academi": "academies",
    "minegold": "mines_gold", "mineiron": "mines_iron", "minecoal": "mines_coal",
    "peasant": "peasants", "infantry17": "mil_inf", "musk17": "mil_shooters",
}


# Что чем требуется (lib/country.script, около 2926) и по какому ключу
# состояния это проверить. Игра при невыполненном требовании молчит — грабля
# №4, — поэтому называем требование сами.
ТРЕБУЕТ = {
    "smith":      [("centers", "ратуши")],
    "store":      [("centers", "ратуши")],
    "house":      [("centers", "ратуши")],
    "peasant":    [("centers", "ратуши")],
    "ba17":       [("smiths", "кузницы")],
    "ba18":       [("smiths", "кузницы")],
    "stable":     [("smiths", "кузницы")],
    "academi":    [("ba17", "казармы")],
    "tower":      [("my_stores", "склада")],
    "market":     [("mills", "мельницы"), ("my_stores", "склада")],
    "infantry17": [("ba17", "казармы")],
    "musk17":     [("ba17", "казармы")],
}


РЕСУРС_РУС = {"food": "еды", "wood": "дерева", "stone": "камня",
               "gold": "золота", "iron": "железа", "coal": "угля"}


def не_по_карману(role: str, st: dict) -> list[str]:
    """Каких ресурсов не хватает на ОДНОГО бойца — по цене из поля fighters.

    14.09 модель шесть раз за серию записала «дело не в еде» и не нашла причину:
    у бесконечного заказа мост отвечал «смотри, какой ресурс на нуле», а сам
    цену знал — она приходит в состоянии вместе со списком бойцов. Сравнить
    цену с запасом мы можем и в python, не трогая блок.

    Честно: цену и запас человек видит на экране, в казарме и в панели ресурсов.
    """
    for кусок in str(st.get("fighters") or "").split():
        имя, _, хвост = кусок.partition("=")
        if имя != role:
            continue
        мало = []
        for поле in хвост.split(",")[1:]:
            м = re.fullmatch(r"([a-z]+)(\d+)", поле)
            # ТОЛЬКО настоящие ресурсы. Раньше здесь пропускался один `hp`, а
            # всё остальное считалось ценой — и 16.09 это обернулось ложью:
            # в строку найма добавили боевые свойства, и мост стал печатать
            # «НЕ ХВАТАЕТ РЕСУРСОВ: atk 0 при цене 8, dpike 0 при цене 6».
            # Такого ресурса нет, запас его всегда ноль, значит заказ выглядел
            # невыполнимым ВСЕГДА. Модель поверила и пошла покупать апгрейды:
            # 13 тактов в 5 партиях из 15 (серия base9). Белый список вместо
            # чёрного — тогда новое поле в строке найма ломает не молча.
            if not м or м.group(1) not in РЕСУРС_РУС:
                continue
            рес, цена = м.group(1), int(м.group(2))
            if цена <= 0:
                continue
            try:
                есть = int(float(st.get(рес, 0) or 0))
            except (TypeError, ValueError):
                continue
            if есть < цена:
                мало.append(f"{РЕСУРС_РУС.get(рес, рес)} {есть} при цене {цена}")
        return мало
    return []


def чего_не_хватает(role: str, st: dict) -> list[str]:
    """Невыполненные требования для этой роли, человеческими словами."""
    нет = []
    for ключ, имя in ТРЕБУЕТ.get(role, []):
        try:
            если = int(float(st.get(ключ, 0) or 0))
        except (TypeError, ValueError):
            если = 0
        if если < 1:
            нет.append(имя)
    return нет


КОМАНДЫ_СЛОВА = ("BALANCE", "TRAIN", "BUILD", "ATTACK", "UPGRADE")


# Слово BALANCE в логе 11.09 встретилось в тексте всего дважды, а намерение
# перераспределить крестьян — почти в каждом такте. Ловим и его: «написал про
# перераспределение, команды нет» — то же самое расхождение.
НАМЕРЕНИЕ = {
    "BALANCE": re.compile(r"перераспредел|долю\s+крестьян|"
                          r"(перекин|перебро|переставь|переставить)\w*\s+крестьян|"
                          r"крестьян\w*\s+на\s+камень", re.I),
}


def названо_но_не_отдано(текст: str, отдано: set[str]) -> list[str]:
    """Команды, названные ЛАТИНИЦЕЙ в объяснениях модели, но не отданные.

    Ровно так пропала добыча камня в прогоне 11.09.2026: в cause такт за тактом
    стояло «перераспределить крестьян на камень через BALANCE», а команды
    BALANCE не было ни одной за эпизод. Модель ничего об этом не узнавала:
    в «Итоге прошлого решения» отражаются только ОТДАННЫЕ команды.
    Считаем по отправленным в игру, а не по JSON: команда с негодной ролью
    отбрасывается в to_commands молча, и это тоже надо показать.
    """
    if not текст:
        return []
    названо = {с for с in КОМАНДЫ_СЛОВА
               if re.search(rf"\b{с}\b", текст)}
    названо |= {с for с, рег in НАМЕРЕНИЕ.items() if рег.search(текст)}
    return sorted(названо - set(отдано))


# Что модель может приписать себе в уроке, не отдав команды. Проверяем только
# такие притязания: урок вида «заказал шахту при камне=20 — не началось» честен
# и должен проходить, если BUILD в том же ответе был.
ПРИТЯЗАНИЯ = (
    # «распредел» без приставки нарочно не берём: «при текущем распределении»
    # — это описание обстановки, а не притязание на сделанное.
    # Только СОВЕРШЁННЫЕ формы. «нужно перераспределить крестьян» — это план,
    # он честен и в журнал попасть должен; «Переставил крестьян 50/50» при нуле
    # команд BALANCE — притязание на несделанное. Разбор лога 11.09 поймал эту
    # разницу на уроке 2:07, который первая редакция фильтра забраковала зря.
    ("BALANCE", re.compile(r"переведен|переведён|перевёл|перевел|переставил|"
                           r"перераспределил|перераспределен|перераспределён|"
                           r"перекинул|перебросил|поставил\s+\d+\s*%", re.I)),
    ("TRAIN", re.compile(r"наня[лв]|нанимал", re.I)),
    ("BUILD", re.compile(r"постро(ил|или)\b|заложил", re.I)),
    ("ATTACK", re.compile(r"отправил\s+волн|послал\s+в\s+атаку", re.I)),
)


def притязание_без_команды(урок: str, отдано: set[str]) -> tuple[str, str] | None:
    """Урок заявляет действие, команды на которое в этом ответе не было.

    11.09.2026 модель дважды записала в lessons.txt «Переведено 60% на камень
    вместо 0%» и «Переставил крестьян 50/50», не отдав ни одной BALANCE.
    Такой урок — не материал для проверки гипотез, а ложь в журнале, и дальше
    она читается как факт.
    """
    if not урок:
        return None
    for имя, рег in ПРИТЯЗАНИЯ:
        if имя in отдано:
            continue
        м = рег.search(урок)
        if м:
            return м.group(0), имя
    return None


def _раздел(запрос: str, заголовок: str) -> list:
    """Строки одного раздела запроса. Нужен трассе: в ней должен лежать тот же
    итог прошлого хода, который видела модель, иначе по записи не понять, на
    что она отвечала."""
    если = []
    внутри = False
    for л in (запрос or "").split("\n"):
        if л.strip() == заголовок:
            внутри = True
            continue
        if внутри:
            if л.startswith("## "):
                break
            if л.strip():
                если.append(л.strip())
    return если

def разобрать_wip(st: dict) -> dict:
    """`wip` из блока состояния: что в закладке, сколько строителей влезает,
    сколько их там СЕЙЧАС и насколько готово.

    Формат с 15.09 — `center/12/5/40`: роль, предел по геометрии, реально
    строят, процент готовности. Старый мост отдавал две части (`center/12`), и
    они по-прежнему понимаются: недостающее становится None, а не нулём, —
    ноль значил бы «никто не строит», а это разные вещи.

    Роль -> (предел, строителей, процент).
    """
    из = {}
    for кусок in str(st.get("wip", "") or "").split(","):
        кусок = кусок.strip()
        if not кусок:
            continue
        части = кусок.split("/")
        имя = части[0]
        def ч(i):
            try:
                return int(части[i])
            except (IndexError, ValueError):
                return None
        из[имя] = (ч(1) or 0, ч(2), ч(3))
    return из

def итог_прошлого(было: dict, стало: dict, заказ: list,
                  повторы: dict | None = None) -> list[str]:
    """Что вышло из прошлого решения. Без этого модель не знает, приняла ли
    игра её заказ, и переспрашивает одно и то же такт за тактом."""
    if not заказ:
        return []
    строки = ["", "## Итог прошлого решения"]
    занято = int(стало.get("build_slots_used", 0) or 0)
    строится_сейчас = разобрать_wip(стало)
    если_повторы = {} if повторы is None else повторы

    def впустую(ключ: tuple, строка: str) -> str:
        """Счётчик подряд идущих безрезультатных заказов одного и того же.
        В прогоне 11.09 одна и та же BUILD mineiron ушла восемь тактов подряд
        и ни разу не началась — по одиночной строке отказа это не видно."""
        n = если_повторы.get(ключ, 0) + 1
        если_повторы[ключ] = n
        if n >= 2:
            строка += (f" ЭТО {n}-Й РАЗ ПОДРЯД с тем же исходом — заказ не"
                       f" проходит, перестань его повторять и убери причину.")
        return строка
    КРЕСТЬЯНЕ = {"food": "on_food", "wood": "on_wood", "stone": "on_stone"}
    for c, role, total in заказ:
        if c == "UPGRADE":
            # Единственная команда, о которой мост молчал совсем. 15.09 серия
            # `upgrades` отдала 38 заказов за пятнадцать партий и не получила
            # ни одной строки итога: молчание неотличимо от бездействия
            # (правило 1), и модель заказывала одно и то же по шесть раз за
            # партию, каждый раз объясняя в 'why', зачем берёт защиту.
            #
            # Отказ игра называет сама: блок кладёт причину в `last_fail`
            # ('UPGRADE mil.1: not enough resources'). Успех не виден ничем —
            # движок пишет 'started' только в свой лог, а поля о ВЗЯТЫХ
            # апгрейдах в состоянии нет. Поэтому про успех говорим ровно то,
            # что знаем, и не выдаём «принят» за «готов».
            сбой = " ".join(str(стало.get("last_fail") or "").split())
            # Блок пишет причину всегда в одной форме: 'UPGRADE <имя>: <текст>'.
            свой = bool(role) and сбой.upper().startswith(
                f"UPGRADE {role}:".upper())
            if свой:
                причина = сбой.split(":", 1)[1].strip() if ":" in сбой else сбой
                строки.append(впустую(
                    ("UPGRADE", role),
                    f"  UPGRADE {role}: НЕ ПРОШЁЛ — {причина}"))
            else:
                # НЕ говорим «принят»: состояние отстаёт на такт, и отказ может
                # прийти следующим. Проверено на моке 15.09 — первый заказ
                # прошёл, второй игра отвергла, а в том же такте `last_fail`
                # был ещё пуст. Сказать «принят» значило бы соврать ровно там,
                # где модель ждёт правды. Сам отказ, когда он дойдёт, модель
                # увидит строкой «ПОСЛЕДНИЙ ОТКАЗ» в обстановке.
                строки.append(
                    f"  UPGRADE {role}: отказа пока нет, но он может прийти "
                    f"следующим тактом. Взят ли апгрейд, мост НЕ ВИДИТ: поля о "
                    f"взятых апгрейдах в состоянии нет. Вслепую то же самое не "
                    f"повторяй — сначала дождись такта")
            continue
        if c == "BALANCE":
            key = КРЕСТЬЯНЕ.get(role)
            if key is None:                 # шахтные ресурсы в состоянии не видны
                строки.append(f"  BALANCE {role} {total}: отправлено, "
                              f"проверить нечем")
                continue
            b, st_ = int(было.get(key, 0) or 0), int(стало.get(key, 0) or 0)
            если = "не изменилось" if b == st_ else f"{b}->{st_}"
            if role == "food" and not int(стало.get("mills", 0) or 0):
                # Без мельницы движок никого на еду не шлёт (см. комментарий к
                # SYSTEM). Партия 11.09.2026 умерла от голода именно так:
                # BALANCE food 16 уходил девятнадцать раз и не делал ничего.
                строки.append(f"  BALANCE food {total}: НЕ СРАБОТАЛО И НЕ "
                              f"СРАБОТАЕТ — У ТЕБЯ НЕТ МЕЛЬНИЦЫ. Крестьяне идут "
                              f"на еду только вокруг неё. Сначала BUILD mill")
                continue
            строки.append(f"  BALANCE {role} {total}: крестьян на {role} {если}"
                          + ("" if b != st_ else
                             " — перестановка идёт через СВОБОДНЫХ крестьян,"
                             " занятые сразу не уходят"))
            continue
        if c == "ATTACK":
            аг_б = int(было.get("my_agressors", 0) or 0)
            аг_с = int(стало.get("my_agressors", 0) or 0)
            св_б = int(было.get("my_freewar", 0) or 0)
            св_с = int(стало.get("my_freewar", 0) or 0)
            # Судим по СУММЕ «свободные + пул»: волна набирается сначала из
            # свободных, а если их мало — из пула, и тогда свободные не меняются
            # вовсе. Прежняя проверка по одним свободным объявляла ушедшую волну
            # неудачей, модель верила и семь раз подряд «снижала запрос» — так был
            # потерян почти весь эпизод 3 от 11.09.2026.
            if (св_с + аг_с) < (св_б + аг_б):
                если_повторы.pop(("ATTACK", ""), None)
                строки.append(f"  ATTACK {total}: ВОЛНА УШЛА — бойцов у базы "
                              f"{св_б + аг_б}->{св_с + аг_с} "
                              f"(свободных {св_б}->{св_с}, пул {аг_б}->{аг_с})")
            else:
                # Причина на слотах РАЗНАЯ, и назвать чужую — соврать.
                причина = ("Запрошено {n}; волна набирается из бойцов без "
                           "приказа, и если не пошёл никто — брать было "
                           "некого: проверь строку «можно послать сейчас»."
                           ).format(n=total) if ЧЕЛОВЕК else (
                          "Запрошено {n}; приказ отвергается ЦЕЛИКОМ, если "
                          "бойцов меньше запрошенного.").format(n=total)
                строки.append(впустую(
                    ("ATTACK", ""),
                    f"  ATTACK {total}: НИКТО НЕ ПОШЁЛ — бойцов у базы как было "
                    f"{св_б + аг_б}, так и осталось {св_с + аг_с} "
                    f"(свободных {св_с}, пул {аг_с}). " + причина))
            continue
        key = СЧЁТЧИК.get(role)
        if key is None:
            строки.append(f"  {c} {role} {total}: проверить нечем")
            continue
        b, st = int(было.get(key, 0) or 0), int(стало.get(key, 0) or 0)
        if total < 0:                       # бесконечный заказ: смотрим только рост
            _т = f"  {c} {role} без счёта: {key} {b}->{st}"
            if st > b:
                если_повторы.pop((c, role), None)
                строки.append(_т)
            else:
                # С числами, а не «смотри ресурсы»: 11.09.2026 найм крестьян встал
                # при 2114 еды, и по одной этой фразе причину было не найти —
                # ни в логе, ни модели. Цены юнитов лежат в бинарнике игры, так
                # что единственный способ увидеть узкое место — снимок на миг
                # отказа, как это уже сделано для BUILD.
                рес = " ".join(f"{имя}={стало.get(ключ, '?')}" for имя, ключ in
                               (("еда", "food"), ("дерево", "wood"),
                                ("камень", "stone"), ("золото", "gold"),
                                ("железо", "iron"), ("уголь", "coal")))
                места = ""
                _з = _запас_мест(стало)
                if _з is not None:
                    места = (f", жилых мест {стало.get('my_farmused')}/"
                             f"{стало.get('my_farm')}")
                # Требования проверяем ПЕРВЫМИ. 14.09: в трёх партиях казармы не
                # было вовсе (золота 355 при цене 500), модель заказывала
                # мушкетёров и шесть раз писала «дело не в еде» — а мост в той же
                # строке состояния держал ba17 в cant_now. Ветка требований
                # существовала, но у бесконечного заказа своя дорога, и до неё
                # не доходило.
                нет = чего_не_хватает(role, стало)
                if нет:
                    строки.append(впустую(
                        (c, role),
                        _т + f" — НЕ РАСТЁТ, и причина известна: НЕТ "
                             f"{' и '.join(нет).upper()}. Пока этого нет, заказ "
                             f"не сделает НИЧЕГО, сколько ни повторяй."))
                    continue
                # Цена бойца приходит в состоянии (поле fighters) — значит
                # сравнить её с запасом можно здесь, а не гадать «какой ресурс
                # ближе к нулю». can_pea/can_inf ниже — поля КОМПЬЮТЕРНОГО слота,
                # человеческий блок их не пишет, и та ветка не срабатывала ни разу.
                мало = не_по_карману(role, стало)
                if мало:
                    строки.append(впустую(
                        (c, role),
                        _т + f" — НЕ ХВАТАЕТ РЕСУРСОВ на одного: "
                             f"{', '.join(мало)}. Заказ не пройдёт, пока этого нет."))
                    continue
                _можно = стало.get("can_pea" if role == "peasant" else "can_inf")
                if str(_можно).lower() in ("0", "false", "нет"):
                    строки.append(
                        _т + f" — ДВИЖОК ГОВОРИТ: РЕСУРСОВ НА ОДНОГО НЕ ХВАТАЕТ. "
                             f"Заказ даже не принят. Было: {рес}{места}. Цены "
                             f"юнитов в данных игры не лежат — смотри, какой "
                             f"ресурс ближе всех к нулю.")
                    continue
                вработе = стало.get("inprod_pea" if role == "peasant" else "inprod_inf")
                if вработе:
                    если_повторы.pop((c, role), None)
                    строки.append(_т + f" — но {вработе} уже В ПРОИЗВОДСТВЕ: "
                                       f"заказ принят, юнит просто ещё не вышел. "
                                       f"Не повторяй и не ищи причину.")
                else:
                    строки.append(впустую(
                        (c, role),
                        _т + f" — НЕ РАСТЁТ, и в производстве НИКОГО. Было в этот "
                             f"миг: {рес}{места}. Смотри, какой ресурс на нуле."))
            continue
        if st >= total:
            если_повторы.pop((c, role), None)
            строки.append(f"  {c} {role} {total}: ГОТОВО ({key}={st})")
        elif st > b:
            если_повторы.pop((c, role), None)
            строки.append(f"  {c} {role} {total}: идёт ({key} {b}->{st})")
        elif c == "BUILD" and (role in строится_сейчас or занято > 0):
            # Ветка раньше смотрела только на build_slots_used — поле
            # КОМПЬЮТЕРНОГО слота, которого человеческий блок не пишет. Поэтому
            # она не срабатывала никогда, и заложенная стройка отчитывалась как
            # «НЕ НАЧАЛОСЬ»: модель выдумывала причину и повторяла заказ такт за
            # тактом. Теперь смотрим на wip — список того, что реально строится.
            если_повторы.pop((c, role), None)
            предел, строят, готово = строится_сейчас.get(role, (0, None, None))
            сколько = (f", строителей влезает {предел}" if предел
                       else ", предел строителей движок ещё не посчитал")
            if строят is not None:
                сколько += f", строят сейчас {строят}"
            if готово is not None:
                сколько += f", готово {готово}%"
            строки.append(f"  {c} {role} {total}: УЖЕ ЗАЛОЖЕНО и строится"
                          f"{сколько}. Не повторяй — дождись, заказ принят")
        else:
            # Стоимости зданий в читаемых данных игры нет, поэтому показываем
            # ресурсы на миг отказа: за несколько попыток порог виден из опыта.
            рес = " ".join(f"{имя}={стало.get(ключ, '?')}" for имя, ключ in
                           (("дерево", "wood"), ("камень", "stone"),
                            ("еда", "food"), ("золото", "gold"),
                            ("железо", "iron"), ("уголь", "coal")))
            нет = чего_не_хватает(role, стало)
            if нет:
                строки.append(впустую(
                    (c, role),
                    f"  {c} {role} {total}: НЕ НАЧАЛОСЬ, и причина "
                    f"известна — НЕТ {' и '.join(нет).upper()}. "
                    f"Сначала это, иначе заказ будет пропадать молча."))
            else:
                уже = int(стало.get(СЧЁТЧИК.get(role, ""), 0) or 0)
                дороже = (f" У тебя уже {уже} таких, а каждое следующее дороже "
                          f"предыдущего." if уже >= 1 and c == "BUILD" else "")
                строки.append(впустую(
                    (c, role),
                    f"  {c} {role} {total}: НЕ НАЧАЛОСЬ. Требования "
                    f"выполнены, значит дело в ресурсах. Было в этот "
                    f"миг: {рес}.{дороже} Повторять с тем же запасом "
                    f"бесполезно."))
    return строки


ЗВЕНЬЯ = ("экономика", "кузница", "казарма", "армия", "волна")

