ЧЕЛОВЕК = False
КАНАЛ_ВОПРОСОВ = False     # --world: включён ли канал вопросов
# --fair: не давать модели того, чего не видит человек за тем же экраном.
# Правило игрока от 13.09: «главное не предоставить больше, чем есть у
