ОТРЕЗОК = 0
ПОСЛЕДНИЙ_ДНЕВНИК = None   # дневник только что сыгранной партии — для --critic
# Трасса и уроки той же партии. 15.09 разбор критика оказался наполовину
# выдумкой: он предлагал строить лесопилку и каменоломню, которых в игре нет,
