# состава армии. Чего в данных нет, то достраивается воображением.
_ПОЛЕ_ВРАГА = __import__("re").compile(r"^p\d_")   # p0_peasants, p1_ba17 и прочие чужие слоты
# Гипотеза критика с ПРОШЛОЙ партии и то, чем он предложил её проверить.
# Игрок 17.09: «если предлагаешь — почему не пробуешь?». До сих пор разбор
# уходил в файл, который читает только человек: за 16 партий base14 критик
