# партию — но только по флагу --critic-forward: это поведенческая правка, и
# базы сравнимости она лишать не должна.
ГИПОТЕЗА_КРИТИКА: dict = {}
КРИТИК_ВПЕРЁД = False
# Веха «волна дошла и убила крестьянина»: одно число на партию — когда это
# случилось впервые. С 17.09 это уже не конец партии, а признак, что армия
# доезжает и работает.
ВЕХА_УБИЙСТВО: list[int] = []
ТРАССА_ПАРТИИ: list[str] = []
УРОКИ_ПАРТИИ: list[str] = []
# Задан ли вопрос в этой партии. Нужно в обстановке КАЖДЫЙ такт: замер по
# четырём партиям 13.09 показал, что необязательные поля (lesson, idea) модель
# заполняет в 1-11% тактов. На пятиминутке это 0,15-1,6 вопроса — то есть при
# одном лишь описании в SYSTEM партия чаще всего проходит молча.
ВОПРОС_ЗАДАН = ""

# Какие метки отбросил последний вызов фильтра. Нужен, чтобы сказать человеку,
# что его подсказка в промпт не пошла: молчаливый отброс неотличим от «не
# помогло», и на этом 12.09 потеряли прогон.
отброшенные_метки: set = set()


def неизвестные_метки(текст: str) -> list[str]:
    """Метки, которых нет среди звеньев. Такая строка видна ВСЕГДА, а автор
    рассчитывал, что она исчезнет — молчать об этом нельзя."""
    плохие = []
    for строка in текст.splitlines():
        s = строка.strip()
        if not s or s.startswith("#"):
            continue
        m = re.match(r"^\[([^\]]+)\]", s)
        if m and m.group(1).strip().lower() not in ЗВЕНЬЯ:
            плохие.append(m.group(1).strip())
    return плохие


def отобрать_подсказки(текст: str, st: dict) -> str:
    """Оставляем только то, что относится к ещё не пройденным звеньям.

    Подсказки уходят в КАЖДЫЙ вызов, так что файл нельзя растить бесконечно:
    это и деньги, и задержка, и потеря внимания модели к середине списка.
    Строка может начинаться с метки звена — [кузница], [казарма], [армия],
    [волна], [экономика]. Такая строка исчезает из промпта, как только звено
    пройдено: советы про постройку кузницы бессмысленны, когда она стоит.
    Строки без метки видны всегда. Строки с # — пояснения для человека, в
    промпт не попадают: документация не должна стоить денег в каждом вызове.
    """
    закрыто = {имя.lower() for имя, ok, _ in stages(st) if ok}
    # Что именно отброшено — наружу, а не молча. 12.09 подсказка с меткой
    # [экономика] не дошла до модели НИ РАЗУ: звено считается пройденным при
    # peasants>=15, а партия начинается с 18. Человек об этом не знал.
    отброшенные_метки.clear()
    оставили = []
    # Подсказка может не влезть в строку. Метка стоит только в первой, и раньше
    # продолжение жило своей жизнью: первую строку отбрасывало по звену, а
    # «хвост» оставался в промпте обрывком. Продолжение — строка с отступом.
    прошлая_отброшена = False
    for строка in текст.splitlines():
        s = строка.strip()
        if not s or s.startswith("#"):
            continue                        # # — пояснение для человека, не для модели
        продолжение = строка[:1].isspace()
        if продолжение and прошлая_отброшена:
            continue                        # хвост уходит вслед за своей головой
        m = re.match(r"^\[([^\]]+)\]\s*(.*)$", s)
        if not m:
            if not продолжение:
                прошлая_отброшена = False
            оставили.append(s)
            continue
        метка, тело = m.group(1).strip().lower(), m.group(2).strip()
        прошлая_отброшена = метка in закрыто
        if прошлая_отброшена:
            отброшенные_метки.add(метка)
            continue                        # звено пройдено — подсказка не нужна
        оставили.append(тело or s)
    return "\n".join(оставили)


ПОРОГ_ЕДЫ = 500            # doprogressorders.inc:199, см. _ресурсы_изменение


def _ресурсы_изменение(было: dict | None, стало: dict) -> list[str]:
    """Насколько ресурсы изменились с прошлого решения, плюс тревоги.

    Уровень ресурса модель видела и раньше, а вот ПАДЕНИЕ — нет. Из «еда=905»
    не понять, что через три такта её не будет: армия и крестьяне едят, и найм
    встанет молча.
    """
    if not было:
        return []
    def ц(d: dict, k: str) -> int:
        try:
            return int(float(d.get(k, 0) or 0))
        except (TypeError, ValueError):
            return 0
    части, тревоги = [], []
    for имя, ключ in (("еда", "food"), ("дерево", "wood"), ("камень", "stone"),
                      ("золото", "gold"), ("железо", "iron"), ("уголь", "coal")):
        д = ц(стало, ключ) - ц(было, ключ)
        части.append(f"{имя} {д:+d}")
        сейчас = ц(стало, ключ)
        if д < 0 and сейчас > 0:
            тактов = сейчас // max(1, -д)
            if тактов <= 5:
                тревоги.append(f"{имя} падает на {-д} за такт, при таком расходе "
                               f"кончится через ~{тактов} тактов")
        elif сейчас == 0 and д <= 0:
            if ключ in ("food", "wood", "stone"):
                тревоги.append(f"{имя} на нуле и не растёт — на этом ресурсе нет "
                               f"крестьян, менять долю через BALANCE")
            else:
                шахта = {"gold": "minegold", "iron": "mineiron",
                         "coal": "minecoal"}[ключ]
                тревоги.append(f"{имя} на нуле — этот ресурс даёт только шахта "
                               f"({шахта}), крестьяне его не собирают")
    # Порог 500 еды. Найден 13.09 по вопросу самой модели, подтверждён кодом:
    # units/building.inc/doprogressorders.inc:199 —
    #   if (not res[food] < 500) and (price[food] > 0) then bEnoughResInfinite := False
    # То есть при еде меньше 500 движок останавливает БЕСКОНЕЧНОЕ производство
    # любого юнита, который стоит еду. Не «нет ресурсов», а отдельная страховка
    # от голода. Заказ на конкретное число под это условие не попадает
    # (строка 184 проверяет amount = gc_obj_order_produce_infinite).
    #
    # Без этой строки мост врал: писал «НЕ РАСТЁТ, смотри какой ресурс на нуле»,
    # а на нуле не было ничего — еда просто была ниже порога. Модель четырежды
    # спрашивала об этом в серии questions5 и не могла догадаться.
    еда = ц(стало, "food")
    if еда < ПОРОГ_ЕДЫ:
        тревоги.append(
            f"еды {еда}, это НИЖЕ {ПОРОГ_ЕДЫ}: движок останавливает производство "
            f"без счёта (TRAIN ... -1) у всего, что стоит еду. Найм пойдёт, "
            f"когда еды станет больше {ПОРОГ_ЕДЫ}; заказ на ТОЧНОЕ число под "
            f"этот порог не попадает")
    строки = ["  изменение с прошлого решения: " + " ".join(части)]
    for т in тревоги:
        строки.append(f"  ВНИМАНИЕ: {т}")
    return строки


def _шахты_строкой(st) -> str:
    """Шахты по отдельности: сколько работает и сколько в них мест.

    До 15.09 состояние отдавало одно число on_mine на золото, железо и уголь
    вместе, и ни модель, ни мост не знали, где именно сидят крестьяне. Человек
    видит каждую шахту и её места, поэтому числа тут честные. Старый мост этих
    полей не отдаёт — тогда печатаем как раньше, без выдумок.
    """
    def ч(k):
        v = st.get(k)
        return None if v in (None, "", -1, "-1") else int(v)
    куски = []
    пустых = 0
    for имя, шахт, внутри, мест, рабочих in (
            ("золото", "mines_gold", "on_gold", "cap_gold", "work_gold"),
            ("железо", "mines_iron", "on_iron", "cap_iron", "work_iron"),
            ("уголь",  "mines_coal", "on_coal", "cap_coal", "work_coal")):
        n = ч(шахт) or 0
        кусок = f"{имя}={n}"
        в, м, раб = ч(внутри), ч(мест), ч(рабочих)
        # Шахта, поставленная не на залежь, мест не даёт вовсе. Раньше состояние
        # показывало только сумму мест, и «золото=3 (работает 5 из 5 мест)»
        # читалось как «всё занято, строй ещё», хотя две шахты из трёх были
        # пустым камнем. Замер 17.09 по 15 партиям parallel_start.
        if n and раб is not None and раб < n:
            кусок += f" (ИЗ НИХ РАБОЧИХ {раб}: остальные поставлены не на залежь и мест не дают)"
            пустых += int(n - раб)
        if n and в is not None and м:
            кусок += f" (работает {в} из {м} мест)"
        elif n and в is not None:
            кусок += f" (работает {в})"
        куски.append(кусок)
    хвост = ("" if not пустых else
             ". ПУСТЫЕ ШАХТЫ НЕ ДАЮТ НИЧЕГО: новая шахта поможет, только если встанет НА ЗАЛЕЖЬ — смотри строку про руду рядом")
    return "  шахты: " + " ".join(куски) + хвост


def _свободных(st: dict) -> int:
    """Крестьяне, не занятые добычей. От них зависит, подействует ли BALANCE:
    игра перераспределяет только свободных (_ai_GainResourcesByPeasants)."""
    def ц(k: str) -> int:
        try:
            return int(float(st.get(k, 0) or 0))
        except (TypeError, ValueError):
            return 0
    return max(0, ц("peasants") - ц("on_food") - ц("on_wood") - ц("on_stone"))


def _запас_мест(st: dict) -> int | None:
    """Сколько жилых мест ещё свободно. None, если поля нет — старый мост."""
    try:
        return int(st["my_farm"]) - int(st["my_farmused"])
    except (KeyError, TypeError, ValueError):
        return None


def _чис(v) -> int:
    """Число из состояния. Поля приходят и числом, и строкой."""
    try:
        return int(float(str(v).strip()))
    except (TypeError, ValueError):
        return 0


# --- Дневник партии ---------------------------------------------------------
#
# Человек помнит не протокол своих кликов, а структуру: что уже стоит, что не
# получилось и почему, чем кончились бои. Замер 13.09 показал, что протокол ей
# вредит: с полной историей партии первая волна ушла на 10:01 против 5:49-7:58
# у базы, волн вчетверо меньше. А пять строк «why» — это намерения, а не
# результаты, и они помнят только последние сто игровых секунд.
#
# Дневник собирается из того, что и так приходит каждый такт, и НЕ РАСТЁТ со
# временем: вехи по одной на здание, неудачи без повторов, исходы волн.

ЗДАНИЯ_ВЕХИ = (("centers", "ратуша"), ("mills", "мельница"), ("smiths", "кузница"),
               ("ba17", "казарма"), ("ba18", "казарма18"), ("my_stores", "склад"),
               ("houses", "дом"), ("stable", "конюшня"), ("academi", "академия"),
               ("market", "рынок"), ("towers", "башня"),
               ("mines_gold", "шахта золота"), ("mines_iron", "шахта железа"),
               ("mines_coal", "шахта угля"))


def _мс(gt) -> str:
    м, с = divmod(max(0, int(gt or 0)), 60)
    return f"{м}:{с:02d}"


class Дневник:
    """Память о партии: вехи, неудачи, исходы волн. Живёт одну партию."""

    ВОЛНА_ИТОГ = 60          # через сколько игровых секунд подводить итог волны

    def __init__(self) -> None:
        self.вехи: list[str] = []
        self.неудачи: dict[str, list] = {}     # суть -> [время, текст, сколько раз]
        self.волны: list[dict] = []
        self._прежние: dict[str, int] = {}
        self._прошлый_сбой = ""      # last_fail держится в состоянии тактами
        self.карта_открыта = False   # map_open: на открытой карте врага видно

    @staticmethod
    def _ч(v) -> int:
        try:
            return int(float(str(v).strip()))
        except (TypeError, ValueError):
            return 0

    def такт(self, st: dict, брак: list[str] | None = None) -> None:
        gt = self._ч(st.get("gametime"))
        self.карта_открыта = str(st.get("map_open", "")).lower() in (
            "1", "true", "да", "yes")
        for ключ, имя in ЗДАНИЯ_ВЕХИ:
            if ключ not in st:
                continue
            было = self._прежние.get(ключ)
            стало = self._ч(st.get(ключ))
            if было is not None and стало > было:
                self.вехи.append(f"{_мс(gt)} {имя}"
                                 + (f" ×{стало}" if стало > 1 else ""))
            self._прежние[ключ] = стало
        # Неудачи: та же беда с другими числами — это одна беда, а не две.
        сбой = " ".join(str(st.get("last_fail") or "").split())[:120]
        новые = list(брак or [])
        if сбой and сбой != self._прошлый_сбой:
            новые.append(сбой)          # тот же текст подряд — та же попытка
        self._прошлый_сбой = сбой
        for текст in новые:
            текст = " ".join(текст.split())[:120]
            if not текст:
                continue
            суть = re.sub(r"\d+", "#", текст.lower())
            if суть in self.неудачи:
                self.неудачи[суть][2] += 1
            else:
                self.неудачи[суть] = [gt, текст, 1]
        # Итоги волн: что стало с ушедшими и с крестьянами врага.
        for в in self.волны:
            if в.get("итог") is None and gt - в["gt"] >= self.ВОЛНА_ИТОГ:
                в["итог"] = (self._наших(st), self._врага(st))

    @classmethod
    def _наших(cls, st: dict) -> int:
        return sum(cls._ч(st.get(k)) for k in ("mil_inf", "mil_shooters", "mil_cav"))

    @classmethod
    def _врага(cls, st: dict) -> int:
        for k, v in st.items():
            if k.endswith("_peasants"):
                return cls._ч(v)
        return 0

    def волна(self, gt: int, сколько: int, цель: str, st: dict) -> None:
        self.волны.append({"gt": gt, "сколько": сколько, "цель": цель,
                           "было": (self._наших(st), self._врага(st)),
                           "итог": None})

    def строки(self) -> list[str]:
        if not (self.вехи or self.неудачи or self.волны):
            return []
        out = ["", "## Что уже случилось в этой партии"]
        if self.вехи:
            out.append("  построено: " + "   ".join(self.вехи[-12:]))
        for время, текст, раз in sorted(self.неудачи.values())[-5:]:
            out.append(f"  {_мс(время)} НЕ ВЫШЛО: {текст}"
                       + (f" (и ещё {раз - 1} раз)" if раз > 1 else ""))
        for в in self.волны[-5:]:
            строка = f"  {_мс(в['gt'])} волна {в['сколько']} на {в['цель']}"
            if в["итог"]:
                (нб, вб), (нс, вс) = в["было"], в["итог"]
                строка += f": наших бойцов {нб} -> {нс}"
                # Что стало с крестьянами врага — честно только при контакте:
                # если наши дошли и дрались, человек это на экране видит. Если
                # волна ушла и никого не потеряла, знать про чужих крестьян
                # неоткуда, и подсказывать нельзя (правило игрока 13.09).
                if (not ЧЕСТНО) or self.карта_открыта or нс < нб:
                    строка += f", крестьян врага {вб} -> {вс}"
                    if вб == вс:
                        строка += " — НИ ОДНОГО НЕ УБИЛИ"
                elif ЧЕСТНО:
                    строка += " (до врага не дошли — что там, не видно)"
            else:
                строка += ": итог ещё не подведён"
            out.append(строка)
        return out


ПОРОГ_ЕДЫ = 500          # ниже него движок гасит ВЕСЬ блок производства


def цена_бойца(role: str, st: dict) -> dict:
    """Цена одного бойца по полю fighters. Белый список ресурсов — иначе
    боевые свойства (atk, dpike) уедут в цену, как это было в base9."""
    for кусок in str(st.get("fighters") or "").split():
        имя, _, хвост = кусок.partition("=")
        if имя != role:
            continue
        цена = {}
        for поле in хвост.split(",")[1:]:
            м = re.fullmatch(r"([a-z]+)(\d+)", поле)
            if м and м.group(1) in РЕСУРС_РУС and int(м.group(2)) > 0:
                цена[м.group(1)] = int(м.group(2))
        return цена
    return {}


ПОСТРОЙКИ_РУС = {"center": "ратуша", "mill": "мельница", "smith": "кузница",
                 "ba17": "казарма", "store": "склад", "house": "дом",
                 "minegold": "золотая шахта", "mineiron": "железная шахта",
                 "minecoal": "угольная шахта"}


def цена_построек(st: dict) -> dict:
    """{роль: {ресурс: цена}} из поля build_cost. Цена — за СЛЕДУЮЩУЮ такую же:
    движок считает её для этого игрока с его нынешним числом зданий, а
    costpercent=500 (unit.script:2472) делает каждую следующую впятеро дороже."""
    из_блока = {}
    for кусок in str(st.get("build_cost") or "").split():
        роль, _, хвост = кусок.partition("=")
        цена = {}
        for поле in хвост.split(","):
            м = re.fullmatch(r"([a-z]+)(\d+)", поле)
            if м and м.group(1) in РЕСУРС_РУС and int(м.group(2)) > 0:
                цена[м.group(1)] = int(м.group(2))
        if цена:
            из_блока[роль] = цена
    return из_блока


def постройки(st: dict, было: dict | None) -> list[str]:
    """Что стоит следующая постройка и через сколько на неё хватит.

    Появилось 17.09: до этого мост говорил только «можно сейчас» списком, и
    модель не знала ЦЕНЫ. Из-за этого вторая казарма за 2500 золота выглядела
    такой же покупкой, как первая за 500, а критик объяснял пустую казну
    добычей золота, хотя дело было в расходе.
    """
    цены = цена_построек(st)
    if not цены:
        return []
    можно = set(str(st.get("can_now") or "").split())
    порядок = [р for р in ("mill", "smith", "ba17", "minegold", "mineiron",
                           "minecoal", "center", "store", "house") if р in цены]
    показ = []
    for р in порядок:
        текст = ", ".join(f"{ц} {РЕСУРС_РУС.get(к, к)}" for к, ц in цены[р].items())
        показ.append(f"{ПОСТРОЙКИ_РУС.get(р, р)} ({р}) — {текст}")
    стр = ["## Цена СЛЕДУЮЩЕЙ постройки",
           "  " + "; ".join(показ),
           "  Каждое следующее здание того же вида ВПЯТЕРО дороже предыдущего —"
           " цены выше уже с этим учётом."]
    # Через сколько хватит на то, чего сейчас купить нельзя.
    if было:
        try:
            dt = float(st.get("gametime") or 0) - float(было.get("gametime") or 0)
        except (TypeError, ValueError):
            dt = 0
        if dt > 0:
            for р in порядок:
                if р in можно:
                    continue
                сроки = []
                for к, ц in цены[р].items():
                    try:
                        есть = float(st.get(к, 0) or 0)
                        рост = (есть - float(было.get(к, 0) or 0)) / dt
                    except (TypeError, ValueError):
                        continue
                    if есть >= ц:
                        continue
                    if рост > 0.05:
                        сроки.append(f"{РЕСУРС_РУС.get(к, к)} хватит через ~{int((ц - есть) / рост)} с")
                    else:
                        сроки.append(f"{РЕСУРС_РУС.get(к, к)} не растёт — пока так, не накопится")
                if сроки:
                    стр.append(f"  {ПОСТРОЙКИ_РУС.get(р, р)}: " + ", ".join(сроки))
    return стр


УДАР: dict = {}                 # состояние текущего удара, чистится между партиями
ДОШЛА_ДО_БАЗЫ = 180            # mil_far, при котором волна считается дошедшей
ОТПРАВКА: dict = {}             # армия в миг последней ATTACK: по ней видно, жива ли волна


def удар(st: dict) -> list[str]:
    """Что происходит с волной, которая ДОШЛА до базы врага.

    ЦЕЛЬ ПАРТИИ — ПОБЕДА: у противника ноль крестьян (17.09, решение игрока).
    Убить одного стало вехой, партия на ней не обрывается. Поэтому блок считает
    не «убил или нет», а ГОНКУ: он прибавляет крестьян примерно по одному в
    двадцать секунд, и до нуля можно дойти, только убивая быстрее — а крестьян
    прикрывает армия, которой у него к концу партии 159-252 против наших 43-88.

    Что показал разбор 39 дошедших волн (`combat_report.py`): волна из 24 бойцов
    стоит у базы 21 такт, крестьян у врага за это время становится 51 -> 94, а
    своих в поле 24 -> 21 и ниже. Ни в одной партии армия врага не уменьшилась.
    Мост про это молчал — модель видела снимок и не видела, что проигрывает
    гонку.

    Честно: это те же числа, что игрок читает с экрана, посчитанные от подхода.
    """
    try:
        далеко = float(st.get("mil_far", 0) or 0)
        в_поле = float(st.get("mil_away", 0) or 0)
        сейчас = float(st.get("gametime", 0) or 0)
    except (TypeError, ValueError):
        return []
    if далеко < ДОШЛА_ДО_БАЗЫ or в_поле <= 0:
        УДАР.clear()
        return []
    крестьян = _чис_или(st.get("p1_peasants"))
    армия = _чис_или(st.get("p1_army"))
    if not УДАР:
        УДАР.update(тактов=0, крестьян=крестьян, армия=армия, волна=в_поле,
                    время=int(сейчас))
    УДАР["тактов"] += 1
    прошло = max(1.0, сейчас - УДАР["время"])
    мм, сс = divmod(УДАР["время"], 60)
    стр = ["## Удар идёт",
           f"  волна у базы врага {УДАР['тактов']} такт(ов), подошла на {мм}:{сс:02d}"]
    хвост = []
    if крестьян is not None and УДАР["крестьян"] is not None:
        хвост.append(f"крестьян у врага {int(УДАР['крестьян'])} -> {int(крестьян)}")
    if армия is not None and УДАР["армия"] is not None:
        хвост.append(f"его бойцов {int(УДАР['армия'])} -> {int(армия)}")
    хвост.append(f"твоих в поле {int(УДАР['волна'])} -> {int(в_поле)}")
    стр.append("  за это время: " + ", ".join(хвост))
    if крестьян is not None and УДАР["крестьян"] is not None and УДАР["тактов"] >= 2:
        темп = (крестьян - УДАР["крестьян"]) * 60.0 / прошло
        осталось = max(0.0, 900.0 - сейчас)
        if темп >= -0.1:
            стр.append(f"  ГОНКУ ТЫ ПРОИГРЫВАЕШЬ: у него {int(крестьян)} крестьян, и их"
                       f" становится БОЛЬШЕ на {темп:.0f} в минуту. Победа — это ноль."
                       f" Такой волной до нуля не дойти: их прикрывает"
                       f" {int(армия) if армия is not None else '?'} бойцов, и пока ты не"
                       f" разобьёшь эту армию, убивать крестьян тебе не дадут.")
        else:
            до_нуля = крестьян / max(0.1, -темп)
            стр.append(f"  ты убавляешь их на {-темп:.0f} в минуту: до нуля при таком"
                       f" темпе {до_нуля:.0f} мин, партии осталось"
                       f" {осталось / 60:.0f} мин.")
    return стр


def _чис_или(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def набег(st: dict, было: dict | None) -> list[str]:
    """Враг у НАШЕЙ базы — сказать вслух и дать команду, которой отбиваются.

    Живая партия 17.09 23:05 (лучшая из живых): враг приходил к нашей базе
    дважды. В 11:31 — при пикинёрах дома: минус 36 крестьян из 60 и 38 пикинёров
    из 42, его потери около 20. В 14:37 — при 58 мушкетёрах: минус 5 у нас,
    минус 15 у него за один такт. Мост оба раза молчал: поля «враг у базы» в
    состоянии нет, а en_near_dist всю партию стоял на 133 — это расстояние до
    ЗДАНИЙ врага, не до бойцов. Модель написала «23 крестьянина» и не спросила,
    куда делись 37; урок вынесла про еду.

    Игрок с экрана: армия стоит кто где вышел из казармы, врозь, и в отряд для
    отпора её никто не собирает. Строя (FORMATION) у нас не будет — правило
    хакатона, — а собрать кулак в одну клетку можно: ATTACK target=cell берёт
    всех свободных и ведёт их вместе, с поиском врага по дороге.

    Честно: чужие бойцы берутся с той же сетки frow, что человек читает на
    мини-карте (и только при открытой карте), а убыль своих крестьян и бойцов
    человек видит в своём интерфейсе всегда. Правка python, не .inc: данные в
    состоянии уже есть, а блок .inc стоит двух минут живой игры на попытку.
    """
    стр: list[str] = []
    сетка: dict = {}
    if not (ЧЕСТНО and not карта_открыта(st)):
        сетка = coss3_map.у_базы(st)
    крестьян = _чис(st.get("peasants"))
    армия = _чис(st.get("mil_inf")) + _чис(st.get("mil_shooters"))
    крестьян_было = _чис(было.get("peasants")) if было else 0
    армия_была = (_чис(было.get("mil_inf")) + _чис(было.get("mil_shooters"))) if было else 0
    # Крестьяне в поход не ходят, захват запрещён настройками партии. Убыль на
    # два и больше за такт — их убивают дома; один мог уйти от голода.
    убыль_крестьян = (крестьян_было - крестьян) if было else 0
    if not (сетка.get("бойцов") or убыль_крестьян >= 2):
        return стр
    стр.append("## ВРАГ У ТВОЕЙ БАЗЫ")
    if сетка.get("бойцов"):
        клетки = ", ".join(f"({x},{y}) {n}" for n, x, y in сетка["клетки"][:4])
        _n, _x, _y = сетка["клетки"][0]
        ближе = max(abs(_x - _чис(st.get("my_cx"))), abs(_y - _чис(st.get("my_cy"))))
        где = ("прямо в клетке ратуши" if ближе == 0 else
               f"ближайшие в {ближе} клетк{'е' if ближе == 1 else 'ах'} от ратуши")
        стр.append(f"  {'не меньше ' if сетка['не_меньше'] else ''}{сетка['бойцов']} "
                   f"бойцов врага стоят у твоей базы, {сетка['сторона']}, {где}. "
                   f"Клетка (x,y) и сколько в ней: {клетки}")
    if убыль_крестьян >= 2:
        стр.append(f"  крестьян стало меньше: {крестьян_было} -> {крестьян} — их "
                   f"убивают у тебя дома, в поход крестьяне не ходят")
    if было and армия < армия_была:
        стр.append(f"  бойцов стало меньше: {армия_была} -> {армия}")
    свободных = _чис(st.get("my_freewar"))
    if _чис(st.get("my_army_n")):
        стр.append(f"  твои свободные: {_чис(st.get('my_army_n'))} стоят в клетке "
                   f"({_чис(st.get('my_army_cx'))},{_чис(st.get('my_army_cy'))}) — "
                   f"там, где вышли из казарм, кулаком их никто не собирал")
    if сетка.get("бойцов") and свободных:
        _n, _x, _y = сетка["клетки"][0]
        стр.append(f"  Отбить ОДНИМ кулаком, всеми свободными, в клетку врага: "
                   f'{{"cmd":"ATTACK","count":{свободных},"target":"cell",'
                   f'"cx":{_x},"cy":{_y}}}')
        стр.append("  Дома размен лучше, чем в походе (замер по 30 партиям: 0,67 "
                   "против 0,19 врага за одного своего): подкрепление выходит из "
                   "казарм рядом. Волну в поход сейчас не посылай — уйдёт мимо врага")
    elif сетка.get("бойцов"):
        стр.append("  свободных бойцов нет: все уже дерутся или ушли. Казармы льют "
                   "подкрепление прямо сюда — держи очередь полной")
    return стр


МАРШ: dict = {}            # идущий марш по контракту модели, чистится между партиями
МАРШ_СРОК = 120            # секунд на сбор, если модель не назвала expires


def _своих_у(st: dict, cx: int, cy: int, радиус: int = 1) -> int:
    """Свои бойцы в клетках не дальше радиуса от (cx,cy) по сетке arow.
    Цифра в клетке срезана на 9, поэтому это нижняя граница."""
    n = _чис(st.get("grid_n"))
    всего = 0
    for y in range(n):
        ряд = str(st.get(f"arow{y}", "") or "")
        for x, c in enumerate(ряд):
            if c.isdigit() and c != "0" and max(abs(x - cx), abs(y - cy)) <= радиус:
                всего += int(c)
    return всего


def _врага_у(st: dict, cx: int, cy: int, радиус: int = 2) -> int:
    """Чужие бойцы у клетки цели по сетке frow, та же нижняя граница."""
    n = _чис(st.get("grid_n"))
    всего = 0
    for y in range(n):
        ряд = str(st.get(f"frow{y}", "") or "")
        for x, c in enumerate(ряд):
            if c.isdigit() and c != "0" and max(abs(x - cx), abs(y - cy)) <= радиус:
                всего += int(c)
    return всего


def начать_марш(gt: int, послано: int, цель: str, клетка: tuple, контракт: dict,
                st: dict) -> None:
    """Модель отдала ATTACK с клеткой сбора. Бойцы уже посланы туда MOVE;
    дальше мост ведёт марш по её контракту, такт за тактом."""
    МАРШ.clear()
    МАРШ.update(фаза="сбор", t0=int(gt), послано=int(послано), цель=цель,
                клетка=tuple(клетка), via=tuple(контракт["via"]),
                hold=контракт.get("hold"),
                expires=int(контракт.get("expires") or МАРШ_СРОК),
                retreat=контракт.get("retreat"), тактов=0, отчёт=[],
                армия0=_чис(st.get("mil_inf")) + _чис(st.get("mil_shooters")))


def шаг_марша(st: dict, br, gt: int, волны: list, дневник=None) -> None:
    """Один такт марша. Зовётся при КАЖДОМ чтении состояния, до модели.

    Так ходит нативный ИИ (progresswarai.inc: _ai_GetNextZone и марш в режиме
    default, атака только при контакте), и так просил игрок 18.09: сначала
    собраться, потом бить. Решения здесь нет ни одного: клетку сбора, порог и
    срок назвала модель, мост лишь смотрит на сетку и исполняет.

    Собрались — когда никто из наших больше не идёт (wave_n = 0: блок пишет его
    только для бойцов С ПРИКАЗОМ) и у клетки сбора стоят свои. Первый такт
    после MOVE не считается: приказ ещё мог не дойти до игры.
    """
    if not МАРШ or МАРШ.get("фаза") != "сбор":
        return
    МАРШ["тактов"] += 1
    vx, vy = МАРШ["via"]
    прошло = int(gt) - МАРШ["t0"]
    в_пути = _чис(st.get("wave_n"))
    у_сбора = _своих_у(st, vx, vy)
    МАРШ.update(прошло=прошло, в_пути=в_пути, у_сбора=у_сбора)
    собрались = МАРШ["тактов"] >= 2 and в_пути == 0 and у_сбора > 0
    if not собрались:
        if прошло >= МАРШ["expires"]:
            МАРШ["фаза"] = "истёк"
            _с = (f"МАРШ ОТМЕНЁН: за {прошло} с не собрались в ({vx},{vy}) — "
                  f"в пути ещё {в_пути}, у сбора {у_сбора}. Срок expires={МАРШ['expires']} "
                  f"назвала ты. Бойцы стоят где стоят; новый ATTACK или MOVE — твой")
            МАРШ["отчёт"].append(_с)
            print("        " + _с)
        return
    цель, (cx, cy) = МАРШ["цель"], МАРШ["клетка"]
    if цель == "cell" and МАРШ.get("hold"):
        враг = _врага_у(st, cx, cy)
        своих = МАРШ["послано"]
        if враг > МАРШ["hold"] * своих:
            МАРШ["фаза"] = "стоим"
            МАРШ["враг_у_цели"] = враг
            _с = (f"УДАР ПО ({cx},{cy}) НЕ НАЧАТ: у цели не меньше {враг} врага против "
                  f"твоих {своих}, а порог hold_if_outnumbered={МАРШ['hold']} назвала ты. "
                  f"Группа стоит в клетке сбора ({vx},{vy}). Решай: ATTACK, MOVE home "
                  f"или ждать подкрепления")
            МАРШ["отчёт"].append(_с)
            print("        " + _с)
            return
    if not br.attack(МАРШ["послано"], цель, cx=cx, cy=cy):
        return                              # файл приказа ещё не забран — следующий такт
    МАРШ["фаза"] = "удар"
    МАРШ["t_удара"] = int(gt)
    волны.append((int(gt), МАРШ["послано"], цель))
    ОТПРАВКА.update(gt=int(gt), послано=МАРШ["послано"],
                    армия=_чис(st.get("mil_inf")) + _чис(st.get("mil_shooters")))
    if дневник is not None:
        try:
            дневник.волна(int(gt), МАРШ["послано"], цель, st)
        except Exception:
            pass
    _с = (f"СОБРАЛИСЬ в ({vx},{vy}) за {прошло} с ({у_сбора}+ у сбора): удар по "
          f"{цель}" + (f" ({cx},{cy})" if цель == "cell" else "") + " начат одним кулаком")
    МАРШ["отчёт"].append(_с)
    print(f"        волна {len(волны)}: {МАРШ['послано']} бойцов — {_с}")


def блок_марша(st: dict) -> list[str]:
    """Строки марша в запросе: что идёт и что мост сделал по контракту."""
    if not МАРШ:
        return []
    vx, vy = МАРШ["via"]
    cx, cy = МАРШ["клетка"]
    куда = МАРШ["цель"] + (f" ({cx},{cy})" if МАРШ["цель"] == "cell" else "")
    стр = ["## МАРШ (по твоему контракту)"]
    if МАРШ["фаза"] == "сбор":
        стр.append(f"  {МАРШ['послано']} идут в клетку сбора ({vx},{vy}) БЕЗ боя: "
                   f"прошло {МАРШ.get('прошло', 0)} с из {МАРШ['expires']}, в пути "
                   f"{МАРШ.get('в_пути', 0)}, у сбора {МАРШ.get('у_сбора', 0)}+. Удар по "
                   f"{куда} начнётся, когда соберутся"
                   + (f"; порог: врага у цели не больше {МАРШ['hold']} на одного твоего"
                      if МАРШ.get("hold") else "")
                   + ". Новый ATTACK или MOVE отменит марш")
    elif МАРШ["фаза"] == "удар":
        # Минуту после удара — и хватит: дальше о волне говорит блок «твои
        # войска», а этот только повторял бы старое.
        if _чис(st.get("gametime")) - МАРШ.get("t_удара", 0) > 60:
            return []
        if _чис(st.get("wave_n")):
            _где = (f"волна: {_чис(st.get('wave_n'))} в пути, клетка "
                    f"({_чис(st.get('wave_cx'))},{_чис(st.get('wave_cy'))})")
        else:
            _где = "приказ отдан, игра заберёт его на ближайшем такте"
        стр.append(f"  удар по {куда} начат из клетки сбора ({vx},{vy}); {_где}")
    for _с in МАРШ.get("отчёт", [])[-2:]:
        стр.append("  " + _с)
    return стр


ПОЛЕ: dict = {}            # память про мельницу и созревание, чистится между партиями
СОЗРЕВАНИЕ_С = 105         # медиана по 15 партиям base15, разброс 83-127


def созревание(st: dict) -> list[str]:
    """Поле зреет — и пока оно зреет, людей на еду ставить НЕКУДА.

    Замерено 17.09 по 15 партиям base15: мельница готова на 64-й секунде, первый
    человек встаёт на еду на 170-й, то есть поле зреет около 105 секунд (83-127).
    До этого еда не считается залежью (brised = false), и её отбрасывают ОБА -
    и наш мост, и родной ИИ игры (progresseconomicai.inc:735 делает тот же
    фильтр). В окне 1:00-3:30 модель отдавала BALANCE food 94 раза за 100 тактов
    и получала ноль человек на еде: команда была обречена, а мост отвечал «нет
    залежи» и не говорил, что дело во ВРЕМЕНИ.
    """
    try:
        мельниц = int(float(st.get("mills", 0) or 0))
        на_еде = int(float(st.get("on_food", 0) or 0))
        сейчас = float(st.get("gametime", 0) or 0)
    except (TypeError, ValueError):
        return []
    if на_еде > 0:
        ПОЛЕ["созрело"] = True
    if мельниц > 0 and "мельница" not in ПОЛЕ:
        ПОЛЕ["мельница"] = сейчас
    # Поле, посчитанное МОСТОМ тем же поиском, что делает команда: сколько
    # созревших участков еды видно вокруг мельницы. Пока его нет, приходится
    # гадать по сроку; когда есть - гадать не нужно.
    готово = st.get("food_ready")
    try:
        готово = int(float(готово)) if готово is not None else None
    except (TypeError, ValueError):
        готово = None
    if мельниц > 0 and готово is not None and готово > 0 and на_еде == 0:
        return ["## Поле СОЗРЕЛО",
                f"  у мельницы готовых участков: {готово}, а на еде НИКОГО."
                f" Ставь людей прямо сейчас: BALANCE food. Каждый такт простоя"
                f" здесь - это такт без найма, потому что ниже 500 еды не"
                f" нанимается никто."]
    if мельниц <= 0 or ПОЛЕ.get("созрело") or "мельница" not in ПОЛЕ:
        return []
    if готово is not None and готово > 0:
        return []
    ждём = int(сейчас - ПОЛЕ["мельница"])
    осталось = СОЗРЕВАНИЕ_С - ждём
    если = (f"обычно поле зреет около {СОЗРЕВАНИЕ_С} с, то есть ждать ещё примерно"
            f" {осталось} с" if осталось > 0 else
            "срок уже вышел: если людей на еде так и нет, засей поле командой SEED")
    return ["## Поле ещё зреет",
            f"  мельница стоит {ждём} с, на еде {на_еде} человек. {если}.",
            "  ПОКА ПОЛЕ НЕ СОЗРЕЛО, BALANCE food НИКОГО НЕ ПОШЛЁТ: еда не считается"
            " залежью, и мост ответит «нет залежи». Займи людей деревом, камнем и"
            " шахтами, а еду ставь, когда поле поспеет."]


def стройка_в_голод(st: dict) -> list[str]:
    """Голод - мёртвое время для найма и лучшее для стройки.

    Замер 17.09 по 15 партиям parallel_start: между готовой кузницей (68 с) и
    заказом казармы (124 с) проходит 56 секунд, и всё это время ресурсов
    хватало - золото 850 при цене 500, дерево 300, камень 120, шесть свободных
    крестьян, - а мост в 30 тактах из 44 прямо говорил «казарма по карману».
    Модель в эти такты занималась ЕДОЙ, потому что мы сделали голод громким.
    Но здания еды не тратят вовсе, а наём под порогом всё равно стоит. Цена
    промедления видна в сравнении: у врага казарма готова на 88-й секунде,
    у нас на 170-й, и дальше он растёт втрое быстрее.
    """
    try:
        еда = float(st.get("food", 0) or 0)
        казарм = int(float(st.get("ba17", 0) or 0))
        кузниц = int(float(st.get("smiths", 0) or 0))
    except (TypeError, ValueError):
        return []
    if еда >= ПОРОГ_ЕДЫ:
        return []
    можно = str(st.get("can_now") or "")
    что = ""
    if казарм == 0 and кузниц > 0 and "ba17" in можно:
        что = "КАЗАРМУ"
    elif кузниц == 0 and "smith" in можно:
        что = "КУЗНИЦУ"
    if not что:
        return []
    return ["## Голод: стройке он не мешает",
            f"  наём под порогом стоит всё равно, а СТРОЙКА ЕДЫ НЕ ТРАТИТ — здания"
            f" берут дерево, камень и золото, и на {что.lower()} у тебя есть."
            f" Ставь {что} сейчас: время голода потрачено зря, если в нём ничего"
            f" не построено. У врага казарма готова на 88-й секунде, у нас на 170-й."]


def выполнимость(st: dict, было: dict | None,
                 горизонты=(30, 60, 90)) -> list[str]:
    """Плановая выполнимость: на сколько бойцов хватит сейчас и через 30/60/90 с.

    Из economic_growth_readiness.md взята одна формула — min по ресурсам от
    (запас + H*приход) / цена. Проверено на 45 партиях (`egr_report.py`): сводный
    score пересказывает армию к 8:00 и в промпт не идёт, а вот выполнимость
    отвечает на измеренное узкое место — казарма молчит больше половины тактов.

    Считается только то, что человек видит на экране: цена бойца в казарме,
    запас в панели ресурсов, приход — изменение этого запаса. Порог еды 500
    учтён отдельно, потому что ниже него встаёт ВЕСЬ наём, а не дорожает.
    """
    if not было or not int(st.get("ba17") or 0):
        return []
    try:
        dt = float(st.get("gametime") or 0) - float(было.get("gametime") or 0)
    except (TypeError, ValueError):
        return []
    if dt <= 0:
        return []
    роли = [к.partition("=")[0] for к in str(st.get("fighters") or "").split()]
    role = "infantry17" if "infantry17" in роли else (роли[0] if роли else "")
    цена = цена_бойца(role, st) if role else {}
    if not цена:
        return []

    def чис(d, k):
        try:
            return float(d.get(k, 0) or 0)
        except (TypeError, ValueError):
            return 0.0

    приход = {р: (чис(st, р) - чис(было, р)) / dt for р in цена}
    еда_сейчас = чис(st, "food")

    def сколько(H):
        """min по ресурсам: сколько бойцов оплатит запас с приходом за H секунд."""
        мест = []
        for р, ц in цена.items():
            есть = чис(st, р) + приход[р] * H
            if р == "food":
                # Тратить можно только то, что ВЫШЕ порога: уйдя под 500, наём
                # встанет целиком, сколько бы железа и золота ни лежало.
                есть -= ПОРОГ_ЕДЫ
            мест.append(max(0.0, есть) / ц)
        return int(min(мест))

    узкое = min(цена, key=lambda р: (max(0.0, чис(st, р) - (ПОРОГ_ЕДЫ if р == "food" else 0)) / цена[р]))
    именительный = {"food": "еда", "wood": "дерево", "stone": "камень",
                    "gold": "золото", "iron": "железо", "coal": "уголь"}
    стр = ["## Хватит ли на бойцов",
           "  " + role + " стоит: "
           + ", ".join(f"{ц} {РЕСУРС_РУС.get(р, р)}" for р, ц in цена.items()),
           f"  сейчас оплачено: {сколько(0)} шт, узкое место — "
           f"{именительный.get(узкое, узкое)}",
           "  если запас будет меняться как сейчас: "
           + ", ".join(f"через {H} с — {сколько(H)}" for H in горизонты)
           + ". Считается по изменению запаса за прошлый такт, а в него входят и"
           + " твои траты: когда идёт наём, число падает — это не пророчество, а"
           + " цена нынешнего темпа"]
    падает = sorted((р for р in цена if приход[р] < -0.05),
                    key=lambda р: чис(st, р) / -приход[р])
    for р in падает[:1]:
        осталось = int(чис(st, р) / -приход[р])
        стр.append(f"  {именительный.get(р, р)} УБЫВАЕТ на {abs(приход[р]):.1f} в секунду: "
                   f"при таком расходе запас кончится через ~{осталось} с")
    if еда_сейчас < ПОРОГ_ЕДЫ:
        не_хватает = ПОРОГ_ЕДЫ - еда_сейчас
        рост = приход.get("food", 0.0)
        если = (f"при нынешнем приходе порог вернётся через ~{int(не_хватает / рост)} с"
                if рост > 0.5 else
                "еда НЕ РАСТЁТ — сам по себе наём не оживёт, нужны люди на еде или SEED")
        стр.append(f"  ЕДА {int(еда_сейчас)} НИЖЕ {ПОРОГ_ЕДЫ}: наём стоит целиком, {если}")
        # Рычаг, который модель не видит сама. Разбор base15: в 70 процентах
        # голодных тактов у неё стояли БЕЗ ДЕЛА семеро крестьян по медиане,
        # пока производство было заглушено порогом. Считать тут нечего -
        # свободные руки на еде дают прибавку сразу, и это единственная
        # команда, которая снимает порог.
        try:
            своб = int(float(st.get("idle_pea", 0) or 0))
            на_еде = int(float(st.get("on_food", 0) or 0))
        except (TypeError, ValueError):
            своб, на_еде = 0, 0
        try:
            мельниц = int(float(st.get("mills", 0) or 0))
        except (TypeError, ValueError):
            мельниц = 0
        if своб > 0 and мельниц > 0:
            стр.append(f"  У ТЕБЯ {своб} СВОБОДНЫХ КРЕСТЬЯН, а на еде {на_еде}:"
                       f" пока наём заглушен, они стоят зря."
                       f" BALANCE food {на_еде + своб} снимет порог быстрее всего")
        elif своб > 0:
            # Без мельницы BALANCE food - пустая команда: еда ищется вокруг
            # мельницы, и пока её нет, посылать людей некуда.
            стр.append(f"  У ТЕБЯ {своб} СВОБОДНЫХ КРЕСТЬЯН, но МЕЛЬНИЦЫ НЕТ:"
                       f" BALANCE food их никуда не отправит, еда растёт только"
                       f" у мельницы. Сначала мельница, потом люди на еду")
    return стр


def situation(st: dict, mp: dict, history: list[str], hints: str,
              было: dict | None = None, заказ: list | None = None,
              restart_ok: bool = False, расхождение: list[str] | None = None,
              повторы: dict | None = None, брак: list[str] | None = None,
              волны: list | None = None, вето: str = "", вмеш: str = "",
              мир: str = "", дневник: list[str] | None = None) -> str:
    gt = int(st.get("gametime", 0))
    mm, ss = divmod(gt, 60)
    done = " ".join(("+" if ok else "-") + name for name, ok, _ in stages(st))
    lines = [
        f"# Время {mm}:{ss:02d}",
        f"Цепочка до цели: {done}",
        "",
        "## Ресурсы",
        f"  еда={st.get('food')} дерево={st.get('wood')} камень={st.get('stone')} "
        f"золото={st.get('gold')} железо={st.get('iron')} уголь={st.get('coal')}",
        *_ресурсы_изменение(было, st),
        *созревание(st),
        *стройка_в_голод(st),
        *выполнимость(st, было),
        *постройки(st, было),
        *удар(st),
        *набег(st, было),
        *блок_марша(st),
        "## Моё",
        f"  крестьян={st.get('peasants')} (еда {st.get('on_food')}, дерево {st.get('on_wood')}, "
        f"камень {st.get('on_stone')}"
        + (f", шахты {st.get('on_mine')}" if "on_mine" in st else "")
        + (f", стройка {st.get('on_build')}" if "on_build" in st else "")
        + f", свободных "
        + (str(st.get("idle_pea")) if "idle_pea" in st else str(_свободных(st))) + ")",
        f"  центров={st.get('centers')} кузниц={st.get('smiths')} казарм17={st.get('ba17')} "
        f"мельниц={st.get('mills')} складов={st.get('my_stores')} домов={st.get('houses')}",
        _шахты_строкой(st),
        f"  армия: пехота={st.get('mil_inf')} стрелки={st.get('mil_shooters')} "
        f"конница={st.get('mil_cav')}; свободных бойцов={st.get('my_freewar')}, "
        + (f"ударный пул={st.get('my_agressors')} (стоят у базы, это НЕ поход)"
           if "my_agressors" in st else "все они готовы к походу"),
        f"  можно послать сейчас: "
        f"{int(st.get('my_freewar', 0) or 0) + int(st.get('my_agressors', 0) or 0)}"
        f" бойцов" + (" (свободные + ударный пул)" if "my_agressors" in st else "")
        + (f". Волной считается {WAVE_MIN} и больше: когда послать можно "
           f"{WAVE_MIN}+, а просишь меньше, мост приказ ОТВЕРГНЕТ. Пока бойцов "
           f"меньше {WAVE_MIN} — уйдёт сколько есть, если сам решишь идти"
           if WAVE_MIN else ""),
        (f"  стройка занята {st.get('build_slots_used')}/{st.get('build_slots_total')} слотов"
         if "build_slots_used" in st else
         f"  недостроено зданий: {st.get('building_now', 0)}"),
    ]
    # Что именно в закладке и каков потолок строителей. Без этой строки модель
    # видела только «недостроено N» и не знала, ЧТО строится, — 12.09 она из-за
    # этого повторяла BUILD на уже заложенное здание такт за тактом.
    _стройка = разобрать_wip(st)
    if _стройка:
        def _окотловане(имя, тройка):
            предел, строят, готово = тройка
            куски = [f"строителей влезает {предел}" if предел else "предел не посчитан"]
            if строят is not None:
                куски.append(f"строят сейчас {строят}")
            if готово is not None:
                куски.append(f"готово {готово}%")
            return f"{имя} (" + ", ".join(куски) + ")"
        # Приписку про процент даём, только если он ЕСТЬ: на старом мосту
        # поля нет, и совет сравнивать несуществующее число был бы ложью.
        _есть_процент = any(т[2] is not None for т in _стройка.values())
        lines.append("  СЕЙЧАС СТРОИТСЯ: " + ", ".join(
            _окотловане(имя, т) for имя, т in _стройка.items())
            + ". Повторный BUILD на это здание ничего не даст — заказ уже принят"
            + (". Готовность растёт тем быстрее, чем больше строителей: сравни"
               " её между тактами и увидишь, что даёт лишний человек"
               if _есть_процент else ""))
    # Какие апгрейды уже сделаны. Без этого модель заказывает один и тот же
    # раз за разом: подтверждения-то нет.
    сделано = [и for и in ("food140", "reaper", "feelds", "century", "horse",
                           "fort", "wood", "stone200", "builders")
               if str(st.get("upg_" + и, "")).lower() in ("1", "true", "да")]
    if "upg_food140" in st:                 # поля есть только на новом мосте
        lines.append("  апгрейды сделаны: " + (", ".join(сделано) or "ни одного"))
    # Что нация УМЕЕТ. Раньше список апгрейдов жил в SYSTEM общим для всех
    # наций, и это была ложь: наборы различаются. 13.09 модель заказала reaper
    # при мельнице и получила «нет такого апгрейда у нашей нации» — такт ушёл
    # на несуществующее. Теперь список приходит из игры.
    _дост = str(st.get("upg_avail", "") or "").strip()
    if _дост:
        _спис = [у for у in _дост.split(",") if у.strip()]
        # РЕЖЕМ ЗДЕСЬ, а не в игре. У нации две с лишним сотни апгрейдов, и
        # целиком этот список — около пяти килобайт в КАЖДОМ запросе при
        # бюджете такта в двадцать секунд.
        #
        # Обрезка живёт в python нарочно. 13.09 я трижды пробовал сделать её
        # в блоке .inc, и каждый раз весь тик Progress переставал
        # компилироваться: там нет способа проверить правку, кроме как поставить
        # в игру и ждать две минуты. Здесь она проверяется за секунду и не может
        # уронить игру.
        _видно, _срез, _чем = отобрать_апгрейды(_спис, st)
        lines.append(f"  апгрейды, доступные тебе сейчас "
                     f"({len(_видно)} из {len(_спис)} у нации): "
                     + ", ".join(_видно))
        if _срез:
            lines.append(f"  ...остальные {_срез} не показаны"
                         + (f": {_чем}" if _чем else " — не влезли в запрос")
                         + ". Если нужного нет в списке, скажи об этом в 'stuck'")
        lines.append("  Имя копируй отсюда БУКВА В БУКВУ. Другого игра не примет: "
                     "имена вроде 'food140' или 'reaper' не существуют.")
        # Свои апгрейды человек знает: купленная линейка в казарме закрыта, а
        # оплачиваемая показана полосой. Числа, которые они дали, видны там же —
        # в карточке бойца (atk/dpike/dsword/dbullet в строке найма выше).
        _взяты, _идут = взятые_апгрейды(st), идущие_апгрейды(st)
        if _взяты:
            lines.append(f"  уже взято ({len(_взяты)}): "
                         + ", ".join(sorted(_взяты)) +
                         ". Второй раз их не заказывают — в списке выше их нет")
        if _идут:
            lines.append(f"  оплачивается прямо сейчас: " + ", ".join(sorted(_идут))
                         + " — жди, а не повторяй заказ")
        # Имена военных апгрейдов до 15.09 выглядели как шум: модель видела
        # список и ни разу за день не отдала UPGRADE. Расшифровка стоит одной
        # строки, а числа лежат в world.md - из кода игры, как их видит человек
        # в интерфейсе.
        #
        # Условие смотрит на ПОКАЗАННЫЕ имена, а не на весь список: 15.09 оно
        # считало по полному, и расшифровка объясняла формат имён, которых в
        # видимых сорока не было ни одного.
        if any(у.count(".") >= 3 for у in _видно):
            lines.append("  Имя вида МЕСТО.ЮНИТ.ВИД.УРОВЕНЬ: вид 1 это АТАКА "
                         "юнита, вид 2 — ЗАЩИТА, уровни берутся по порядку. "
                         "Военные апгрейды заказывают в казарме, и они требуют "
                         "кузницы.")
    # Что стало с ПОСЛАННОЙ волной. До 13.09 трасса знала, сколько бойцов ушло,
    # и ничего о том, дошли ли они: семь прогонов слали по 20-30 и не убили ни
    # одного крестьянина врага, а отличить «погибли по дороге» от «стоят на
    # месте» было нечем.
    _п = st.get("wave_sent")
    if _п is not None and int(float(_п or 0)):
        lines.append(f"  в последней волне было послано: {int(float(_п))}")
    # УБЫЛЬ АРМИИ — единственный честный признак того, что наших убивают.
    #
    # Считается здесь, а не в блоке .inc: общий счёт армии человек видит в
    # интерфейсе, и он убывает при потерях — так подсказал игрок. В игре для
    # этого ничего добавлять не надо, а правка python проверяется за секунду и
    # не может уронить тик Progress (правило 8).
    #
    # Именно этого не хватало, чтобы понять, что стало с волной: поле из
    # именованной группы на тот же вопрос отвечало ложью — группа не теряет
    # своих мёртвых.
    if было:
        _б = _чис(было.get("mil_inf")) + _чис(было.get("mil_shooters"))
        _с = _чис(st.get("mil_inf")) + _чис(st.get("mil_shooters"))
        if _б and _с < _б:
            lines.append(f"  АРМИЯ УБЫЛА: было {_б}, стало {_с} — наших убивают "
                         f"прямо сейчас. Если волна ушла, тает она")
    if not int(float(st.get("centers", 0) or 0)):
        lines.append("  ратуши НЕТ: без неё не построить ничего, кроме мельницы,"
                     " и не нанять крестьян")
    _з = _запас_мест(st)
    if _з is not None:                      # на старом мосте поля нет — молчим
        lines.append(f"  жилых мест занято {st.get('my_farmused')} из "
                     f"{st.get('my_farm')}"
                     + (" — запас кончается, найм встанет" if _з < 20 else ""))
    # Волны считаем САМИ, а не по счётчику игры: 11.09.2026 выяснилось, что
    # my_agressors — это пул назначенных в агрессоры, он растёт от формирования
    # отрядов и мобилизации и не пустеет. Модель читала его как «волна идёт» и
    # за весь эпизод не отдала ни одной ATTACK: ждала результата похода,
    # которого не было.
    # Что здания ДЕЛАЮТ прямо сейчас: заказ принят, но юнит ещё в работе —
    # это не то же самое, что «заказ не прошёл». Поля появились 11.09.2026,
    # на старом мосте их нет.
    if "inprod_pea" in st:
        lines.append(f"  в производстве: крестьян {st.get('inprod_pea')}, "
                     f"пехоты {st.get('inprod_inf')}")
    if st.get("last_fail"):
        # Почему прошлая команда не прошла — словами игры, а не догадкой модели.
        # Без этой строки она сочиняет причину: за один прогон на моке успела
        # «выяснить», что в цену зданий входит еда.
        lines.append(f"  ПОСЛЕДНИЙ ОТКАЗ: {st.get('last_fail')}")
    if "on_build" in st:
        lines.append(f"  на стройках занято {st.get('on_build')} крестьян"
                     + (" (сколько послать, решаешь ты командой BUILDERS)"
                        if "idle_pea" in st else
                        " (их забрала игра, доля BALANCE их не касается)"))
    if "cost_ok" in st and str(st.get("cost_ok")).lower() in ("1", "true", "да"):
        lines.append(f"  цена крестьянина (из движка): еда {st.get('pea_food')}, "
                     f"дерево {st.get('pea_wood')}, золото {st.get('pea_gold')}")
    if "can_pea" in st:
        # Ответ самого движка: хватает ли РЕСУРСОВ на одного. Цены юнитов лежат
        # в бинарнике, и без этой строки причина отказа была неугадываема.
        _д = lambda k: str(st.get(k, "")).lower() in ("1", "true", "да")
        lines.append(f"  движок говорит: на крестьянина ресурсов "
                     f"{'ХВАТАЕТ' if _д('can_pea') else 'НЕ ХВАТАЕТ'}, "
                     f"на пехотинца {'хватает' if _д('can_inf') else 'НЕ ХВАТАЕТ'}"
                     + (", и объявлен ГОЛОД" if _д("famine") else ""))
    if волны is not None:
        if волны:
            _мм, _сс = divmod(волны[-1][0], 60)
            lines.append(f"  волны: отправлено {len(волны)}, последняя на "
                         f"{_мм}:{_сс:02d} из {волны[-1][1]} бойцов "
                         f"на {волны[-1][2]}")
        else:
            lines.append("  волны: НИ ОДНОЙ. Никто никуда не идёт, пока ты не "
                         "отдашь ATTACK")
    # ЧТО СТАЛО С УШЕДШЕЙ ВОЛНОЙ. 18 партий, 1139 бойцов отправлено, ноль убитых
    # крестьян врага — и по трассе нельзя было отличить «погибли по дороге» от
    # «дошли и не справились». wave_sent говорит, сколько УШЛО; что дальше —
    # молчание, и модель гадала («возможно, волна ещё идёт»).
    # Даём только СВОИХ и только то, что человек и так видит: свою армию на
    # карте и штатное оповещение «ваши войска атакованы». Раненый — значит его
    # бьют прямо сейчас.
    _ушли = _чис(st.get("mil_away")) if "mil_away" in st else None
    if _ушли is not None:
        _ранены, _дальше = _чис(st.get("mil_hurt")), _чис(st.get("mil_far"))
        _всего = _чис(st.get("mil_inf")) + _чис(st.get("mil_shooters"))
        _что = [f"{_всего} бойцов всего"]
        if _ушли:
            # Где именно они стоят и идут ли кучей. Человек видит это на карте
            # одним взглядом; по одному «самый дальний» отличить растянутую
            # цепочку от плотной группы нельзя, а 15.09 модель пять раз подряд
            # писала «бойцы подходят по одному» и проверить это было нечем.
            _близко, _сторона = _чис(st.get("mil_near")), str(st.get("mil_side") or "")
            _куда = f" на {_сторона}" if _сторона else ""
            if _близко and _дальше - _близко > 20:
                _что.append(f"{_ушли} УШЛИ{_куда} и РАСТЯНУЛИСЬ: от {_близко} до "
                            f"{_дальше} от базы — это не кулак, а цепочка")
            else:
                _что.append(f"{_ушли} УШЛИ{_куда} кучей (от {_близко} до {_дальше})")
        else:
            _что.append("от базы никто не ушёл — все дома")
        if _ранены:
            _что.append(f"{_ранены} РАНЕНЫ: их бьют прямо сейчас")
        lines.append("  твои войска: " + ", ".join(_что))
        # «Ушли» и «волна» — РАЗНЫЕ вещи, и путать их дорого. mil_away считает
        # всех, кто дальше 60, чем бы они там ни занимались; wave_sent — только
        # тех, кого ты послал командой ATTACK. Боец может оказаться в поле сам:
        # движок гонит его за врагом, попавшим в радиус поиска.
        _послано = _чис(st.get("wave_sent"))
        if _ушли and not _послано:
            lines.append("  но в атаку ты не посылал НИКОГО: эти ушли не по твоей "
                         "команде — скорее всего погнались за врагом сами. "
                         "Волна — только то, что отдано через ATTACK")
        if _ушли == 0 and _послано > 0:
            # «Никого дальше 60» — это ещё не «погибли». Живая партия 17.09
            # 23:05: после ATTACK 50 волна встала в 21-37 от базы, потому что
            # враг уже шёл к нам; армия росла 57 -> 72, а мост четыре такта
            # подряд говорил «считай их погибшими» — модель так и записала, и
            # критик так и разобрал. Живы они или нет, говорит СЧЁТ АРМИИ в
            # миг отправки: убыла на треть волны и больше — погибли.
            _при = _чис(ОТПРАВКА.get("армия"))
            if _при and _всего >= _при - _послано // 3:
                # Живая партия 18.09: волна из 42 выходила за 60 целую минуту
                # (8:12 — 24 от базы, 8:38 — 50, 8:55 — ушла), и «враг рядом»
                # тут было бы ложной причиной. Причин две, и различает их блок
                # «ВРАГ У ТВОЕЙ БАЗЫ» выше: он есть — дерутся дома, нет — ещё
                # только собираются.
                lines.append(f"  волна из {_послано} НЕ УШЛА дальше 60 от базы: самый "
                             f"дальний в {_дальше}, армия {_при} -> {_всего} — они "
                             f"ЖИВЫ и стоят у дома: либо ещё собираются и не вышли "
                             f"(выход занимает до минуты), либо, если выше назван "
                             f"ВРАГ У ТВОЕЙ БАЗЫ, дерутся здесь, а не в походе")
            else:
                _счёт = f"армия {_при} -> {_всего}, " if _при else ""
                lines.append(f"  ВОЛНА НЕ ВЕРНУЛАСЬ: ты посылал {_послано}, {_счёт}а у "
                             "базы сейчас нет никого дальше 60 — считай их погибшими, "
                             "а не идущими")
        # ДОТЕКАНИЕ. Мост НЕ держит паузы между волнами (--attack-every 0), и
        # второй ATTACK уйдёт отдельной группой вдогонку первой. Бойцы дойдут
        # по одному, а противник в это время усиливает базу: движок раздаёт
        # защитников зданиям по приоритету (_ai_ProgressDefenders,
        # progresswarai.inc:3351). Сказал игрок, подтверждено кодом игры.
        # Числа тут свои и проверяемые: столько ушло, столько дома.
        _дома_свободно = _чис(st.get("my_freewar"))
        if _послано and _ушли and _дома_свободно:
            lines.append(f"  ДОТЕКАНИЕ: {_послано} уже в поле, дома свободных "
                         f"{_дома_свободно}. Новый ATTACK пошлёт их ОТДЕЛЬНОЙ группой "
                         f"вдогонку — паузы между волнами мост не держит, и они "
                         f"дойдут по одному, а не кулаком. Противник в это время "
                         f"ставит защитников к своим зданиям. Либо копи новый "
                         f"кулак дома, либо посылай столько, чтобы хватило без "
                         f"поддержки, либо ATTACK target=wave — к волне, а не мимо")
    # ГИПОТЕЗА КРИТИКА — то, что он предложил после ПРОШЛОЙ партии. Это
    # гипотеза, а не знание: она названа по одной партии и может быть неверной.
    # Поэтому и подаётся как задание на проверку, с тем числом, которым он сам
    # предложил её мерить.
    if КРИТИК_ВПЕРЁД and ГИПОТЕЗА_КРИТИКА.get("гипотеза"):
        lines += ["", "## ЧТО ПРОВЕРЯЕМ В ЭТОЙ ПАРТИИ",
                  f"  После партии {ГИПОТЕЗА_КРИТИКА['партия']} разбор сказал: "
                  f"{ГИПОТЕЗА_КРИТИКА['гипотеза']}"]
        if ГИПОТЕЗА_КРИТИКА.get("как"):
            lines.append(f"  Проверяется так: {ГИПОТЕЗА_КРИТИКА['как']}")
        lines.append("  Это ГИПОТЕЗА по одной партии, а не правило игры. Сочтёшь "
                     "её неверной — скажи об этом в 'stuck' и играй по-своему")

    # ГОТОВНОСТЬ К УДАРУ. Формулу назвал игрок 16.09: армейская стоимость +
    # эффективность состава + строй + позиция + подкрепление − угроза
    # артиллерии − риск фланга. Мост считает ЧЕТЫРЕ слагаемых из семи и об
    # остальных говорит прямо: строй он не умеет задавать вовсе (команды нет),
    # риск фланга считать нечем. Единого числа НЕ выводим: сложить четыре
    # слагаемых из семи и назвать это готовностью значит дать модели точность,
    # которой нет, а модель ошибается ровно настолько, насколько врёт описание.
    _своих = (_чис(st.get("mil_inf")) + _чис(st.get("mil_shooters"))
              + _чис(st.get("mil_cav")))
    if _своих:
        # Пушки — ОТДЕЛЬНО от остальных, и только если поле правда пришло.
        # 16.09 на Windows python обогнал .inc в игре: mil_guns блок ещё не
        # писал, а _чис(None) превращал отсутствие в «пушек 0» — то есть в
        # утверждение, что пушек нет. Отсутствие поля и измеренный ноль должны
        # различаться, иначе мост врёт ровно тем способом, который мы сегодня
        # ловили трижды.
        _состав = (f"пехота {_чис(st.get('mil_inf'))}, "
                   f"стрелки {_чис(st.get('mil_shooters'))}, "
                   f"конница {_чис(st.get('mil_cav'))}")
        if "mil_guns" in st:
            _состав += f", пушек {_чис(st.get('mil_guns'))}"
        _стр = [f"  твоя сила: {_своих} бойцов ({_состав})"]
        _цена = цена_армии(st)
        if _цена:
            _стр[0] += (", цена " + ", ".join(f"{v} {РЕСУРС_РУС.get(k, k)}"
                                              for k, v in _цена.items()))
        if not (ЧЕСТНО and not карта_открыта(st)):
            _ва = поле_врага(st, mp, "army")
            if _ва is not None:
                # То же правило, что и для своих пушек: чего блок не прислал,
                # того мы не называем нулём. Пушки и башни врага появились
                # вечером 16.09, и на мосту постарше их просто нет.
                _вражьи = (f"пехота {_чис(поле_врага(st, mp, 'inf'))}, "
                           f"стрелки {_чис(поле_врага(st, mp, 'shoot'))}, "
                           f"конница {_чис(поле_врага(st, mp, 'cav'))}")
                _хвост = ""
                for _к, _сл in (("guns", "пушек"), ("tower", "башен")):
                    _зн = поле_врага(st, mp, _к)
                    if _зн is not None:
                        _хвост += f", {_сл} {_чис(_зн)}"
                _стр.append(f"  сила врага: {_ва} ({_вражьи}){_хвост}")
        # РИСК ФЛАНГА. 16.09 я записал его как «считать нечем» — игрок поправил:
        # карта открыта, мини-карта есть, и по ней видно, кто из врага стоит
        # ближе к НАШЕЙ базе, чем к своей. Это и есть угроза во фланг и в тыл,
        # особенно когда своя волна ушла.
        if not (ЧЕСТНО and not карта_открыта(st)):
            _фл = coss3_map.фланг(st)
            if _фл:
                if _фл["бойцов_рядом"]:
                    _сколько, _dx, _dy, _до_нас, _до_них = _фл["ближние"][0]
                    _стр.append(
                        f"  РИСК ФЛАНГА: {_фл['бойцов_рядом']} бойцов врага стоят "
                        f"ближе к ТВОЕЙ базе, чем к своей; ближайшие {_сколько} — "
                        f"в {_до_нас} клетках {coss3_map.compass(_dx, _dy)}, а до "
                        f"их базы им {_до_них}. Уйдёшь всей силой — встретят дома")
                else:
                    _стр.append(
                        f"  риск фланга: чужих бойцов ближе к твоей базе, чем к "
                        f"их собственной, нет (всего их видно {_фл['всего']})")
        # СТРОЙ. До 16.09 его не было вовсе и запрос честно называл это дырой.
        # Теперь есть команда FORMATION, и слагаемое считается: либо строй
        # стоит и даёт числа, либо мост говорит, чего не хватает.
        _форма = str(st.get("squad_form", "") or "")
        if _форма:
            _стр.append(
                f"  строй: {_форма}, в отряде {_чис(st.get('squad_units'))} бойцов, "
                f"прибавка на ходу +{_чис(st.get('squad_dmg'))} к урону и "
                f"+{_чис(st.get('squad_def'))} к защите, СТОЯ НА МЕСТЕ "
                f"+{_чис(st.get('squad_hdmg'))} и +{_чис(st.get('squad_hdef'))} — "
                f"строй выгоднее держать, чем бежать им")
        # Раньше здесь стояло «строя нет: нанимай officer17 и drummer17».
        # 16.09 выяснилось, что это совет сделать невозможное: оба делаются
        # только в академии, а она запрещена настройками партии. Строку убрали
        # целиком, а не смягчили: слагаемое, которого не добыть, — не подсказка,
        # а трата внимания и токенов в каждом такте.
        _стр.append("  Выбор твой: ударить ВСЕЙ силой одним кулаком; послать "
                    "часть — тогда остальные дотекут поодиночке; MOVE подводит "
                    "бойцов БЕЗ боя и разворачивает их в сторону цели, чтобы "
                    "ударить вместе и лицом к врагу")
        lines += ["", "## ГОТОВНОСТЬ К УДАРУ (слагаемые, какие мост умеет считать)"] + _стр

    # Кого вообще можно нанять в бой. Новичок открывает казарму и читает, что
    # там лежит; у бота этого не было никогда. 14.09, 12 партий: армия целиком
    # из пикинёров (infantry17 заказан 144 раза, musk17 — ноль), и каждая волна
    # гибла у базы врага, не убив ни одного крестьянина.
    # ЧТО ДЕЛАЕТСЯ ПРЯМО СЕЙЧАС. Для стройки такая строка есть давно (wip), а
    # для найма её не было: мост говорил «заказ ушёл» и умолкал. По серии
    # base14 из 348 заказов 345 были бесконечными — отличить работающий
    # конвейер от вставшего было нечем.
    _каз = str(st.get("ba_queues", "") or "").strip()
    if _каз and _каз != "none-built":
        # Очередь КАЖДОЙ казармы отдельно. Раньше в состоянии стояло только их
        # число, и 17.09 это стоило 2500 золота: вторая казарма простояла пустой
        # всю партию, потому что страж ALREADY ORDERED пропускал бесконечный
        # заказ, увидев его в первой. Ни модель, ни разбор этого не видели.
        _чит = []
        for _к in _каз.split(","):
            _ном, _, _что = _к.partition(":")
            if _что in ("", "none"):
                _чит.append(f"№{_ном} ПУСТА")
            else:
                _имя, _, _скл = _что.partition(":")
                _чит.append(f"№{_ном} {_имя} " + ("без счёта" if _скл == "inf" else f"x{_скл}"))
        lines.append("  очередь по казармам: " + ", ".join(_чит)
                     + (". ПУСТАЯ КАЗАРМА НЕ ДЕЛАЕТ НИКОГО — отдай TRAIN ещё раз,"
                        " он уйдёт во все казармы сразу"
                        if "ПУСТА" in " ".join(_чит) else ""))
    _оч = str(st.get("train_now", "") or "").strip()
    if "train_now" in st:
        if _оч:
            _чит = []
            for _кус in _оч.split(","):
                _имя, _, _скл = _кус.partition(":")
                _чит.append(f"{_имя} " + ("без счёта" if _скл == "inf" else f"x{_скл}"))
            lines.append("  в работе у зданий: " + ", ".join(_чит))
        else:
            lines.append("  в работе у зданий: НИЧЕГО не делается. Если ты "
                         "заказывал бойцов, заказ не принят — смотри еду и "
                         "строку «движок говорит»")
    _бойцы = str(st.get("fighters", "") or "").split()
    if _бойцы == ["none-found"]:
        # Молчать тут нельзя: пустая строка неотличима от «блок не встал».
        lines.append("  кого можно нанять в бой: МОСТ НЕ НАШЁЛ НИ ОДНОЙ боевой "
                     "роли у этой нации. Это похоже на поломку моста, а не на "
                     "правило игры — заказывай по прежнему опыту")
    elif _бойцы:
        # СВОЙСТВА И ЦЕНА — РАЗНЫМИ СЛОВАМИ, а не одним списком через запятую.
        # 16.09 строка уходила как «pikeman: hp90, atk8, dpike3, food25, gold3,
        # iron20», и модель прочитала боевые числа как цену: «движок требует
        # 8 atk, 6 dpike — не хватает ни одного». По форме это и была цена:
        # atk8 ничем не отличался от food25. Человек в карточке бойца видит их
        # раздельно и подписанными; отдавать свалку было нечестно.
        _ЗАЩИТА = (("dpike", "пики"), ("dsword", "сабли"), ("dbullet", "пули"))
        _разбор = []
        for _б in _бойцы:
            _роль, _, _хвост = _б.partition("=")
            _части = [ч for ч in _хвост.split(",") if ч]
            _имя = _части[0] if _части else _роль
            _поля = {}
            for _ч in _части[1:]:
                _м = re.fullmatch(r"([a-z]+)(-?\d+)", _ч)
                if _м:
                    _поля[_м.group(1)] = int(_м.group(2))
            _что = []
            if _поля.get("hp"):
                _что.append(f"{_поля['hp']} жизней")
            if _поля.get("atk"):
                _что.append(f"бьёт на {_поля['atk']}")
            # Нулевую защиту показываем словом: ноль здесь — не «неизвестно», а
            # «не держит удар вовсе», и это важно знать (у мушкетёра так).
            _щит = [f"{_поля.get(_к, 0)} от {_сл}" for _к, _сл in _ЗАЩИТА if _к in _поля]
            if _щит:
                _что.append("защита " + ", ".join(_щит))
            # Нулевую цену не показываем: в казарме у ресурса, которого юнит не
            # стоит, просто пусто.
            _цена = [f"{_поля[_р]} {РЕСУРС_РУС[_р]}" for _р in РЕСУРС_РУС
                     if _поля.get(_р)]
            _хвостик = "; ЦЕНА " + ", ".join(_цена) if _цена else ""
            _разбор.append(f"{_роль} ({_имя}): " + ", ".join(_что) + _хвостик)
        lines.append("  кого можно нанять в бой — "
                     + " | ".join(_разбор))
    # БЕЗ РАТУШИ ДОБЫЧИ НЕТ. Замер на живой игре 14.09: десять рубщиков при
    # отсутствии ратуши дали дерево 1000 -> 1000 и разошлись за двадцать секунд;
    # та же команда после ратуши дала 300 -> 580. Крестьянам некуда нести, и они
    # бросают работу. Модель каждую партию первые полторы минуты раскидывает
    # людей по ресурсам впустую.
    if _чис(st.get("centers")) <= 0:
        lines.append("  РАТУШИ НЕТ — добычи не будет: крестьяне уйдут к лесу, "
                     "порубят и разойдутся, ресурс не прибавится. Пока ратуша "
                     "не достроена, BALANCE на дерево и камень бесполезен")
    # Лес и камень НА ЗЕМЛЕ, а не в запасе. Модель сама записала урок: «15
    # человек на камне дали камень +0 — он, видимо, уже исчерпан в пределах 40».
    # Была права и проверить не могла: состояние говорило только про запас.
    # Числа — вместимость в рабочих местах, а не «сколько тонн»: в клетке леса
    # помещается 2 рубщика, в клетке камня 3.
    _мест = []
    for _к, _имя in (("wood", "дерево"), ("stone", "камень")):
        if f"{_к}_slots_near" not in st:
            continue
        _вс, _св = _чис(st.get(f"{_к}_slots_near")), _чис(st.get(f"{_к}_slots_free"))
        if _вс <= 0:
            _мест.append(f"{_имя} — РЯДОМ КОНЧИЛОСЬ, посылать некуда")
        elif _св <= 0:
            _мест.append(f"{_имя} — все {_вс} мест заняты, лишние встанут без дела")
        else:
            _мест.append(f"{_имя} — свободно {_св} мест из {_вс}")
    if _мест:
        lines.append("  на земле рядом (в пределах 40): " + "; ".join(_мест))
    # Сколько людей BALANCE может переставить ПРЯМО СЕЙЧАС. Число свободных
    # крестьян игрок видит в интерфейсе, так что форы нет; а вот связать его со
    # своей командой модель не догадывалась. 13.09 в base_open3 копия 1 четыре
    # такта подряд слала BALANCE food 12 при нуле свободных, еда падала, и
    # крестьяне умерли от голода при полном наборе рабочих на стройке.
    _своб = _чис(st.get("idle_pea")) if "idle_pea" in st else _свободных(st)
    _строит = _чис(st.get("on_build"))
    if _своб <= 0:
        lines.append(f"  BALANCE сейчас НЕ ПОДЕЙСТВУЕТ: свободных крестьян нет "
                     f"(на стройке {_строит}). Команда берёт только свободных — "
                     f"снимай со строек через BUILDERS или жди, пока достроят")
    else:
        lines.append(f"  BALANCE может переставить сейчас не больше {_своб} "
                     f"человек — столько свободных"
                     + (f"; ещё {_строит} заняты стройкой" if _строит else ""))
    # Что по карману ПРЯМО СЕЙЧАС — ответ движка (_unit_CanApplyCostByID), а не
    # догадка. Раньше модель выясняла это ценой такта: закажи, получи тишину,
    # гадай, какой ресурс виноват. Человек видит это как погашенную кнопку.
    _мочь = str(st.get("can_now", "") or "").split()
    _немочь = str(st.get("cant_now", "") or "").split()
    if _мочь or _немочь:
        lines.append("  по карману сейчас: " + (" ".join(_мочь) or "НИЧЕГО"))
        if _немочь:
            lines.append("  не по карману: " + " ".join(_немочь)
                         + " — заказывать бесполезно, такт пропадёт")
    # Залежи. Модель сама попросила это в questions10 (1:46): «есть ли залежь
    # железа в пределах 26 от ратуши и с какой стороны?». До сих пор состояние
    # говорило только сколько шахт ПОСТРОЕНО, и BUILD minegold был гаданием.
    _зал = []
    for _к, _имя in (("gold", "золото"), ("iron", "железо"), ("coal", "уголь")):
        _d = st.get(f"ore_{_к}_dist")
        if _d is None:
            continue
        _d = _чис(_d)
        _n = _чис(st.get(f"ore_{_к}_near"))
        _s = str(st.get(f"ore_{_к}_side") or "").strip()
        if _d < 0:
            _зал.append(f"{_имя} — свободных не видно")
        else:
            # Шахта встаёт ПРЯМО на залежь, поэтому дальность её не запрещает —
            # но чем дальше, тем дольше ходить и тем легче её потерять.
            _зал.append(f"{_имя} — ближайшая свободная в {_d}"
                        + (f" на {_s}" if _s else "")
                        + (f", всего свободных рядом {_n}" if _n > 1 else ""))
    if _зал:
        lines.append("  свободные залежи: " + "; ".join(_зал))
    # ЧЕСТНОСТЬ: не давать модели того, чего не видит человек.
    #
    # Число крестьян у противника мост знает точно и каждый такт — сквозь туман
    # войны, из структур игры. Человек не видит его НИКОГДА: он видит то, что
    # разведал, и считает на глаз. Нам это число нужно как мерило цели, и оно
    # остаётся в трассе и в проверке цели; в ЗАПРОС при --fair оно не идёт.
    # Расстояние до ближайшего врага — тот же случай: датчик сквозь темноту.
    en = None
    for p in range(8):
        _ист = mp if f"p{p}_peasants" in mp else st
        if st.get(f"p{p}_enemy") and f"p{p}_peasants" in _ист:
            en = _ист[f"p{p}_peasants"]
    # На ОТКРЫТОЙ карте (монгольфьер выдан всем, additional.balloon = 2) тумана
    # нет ни у кого, и человек видит и базу врага, и его войска. Тогда числа —
    # не фора, и скрывать их незачем. Признак приходит из игры полем map_open.
    открыта = карта_открыта(st)
    if ЧЕСТНО and not открыта:
        lines.append("  что у противника — не видно: разведки нет, и числа его "
                     "крестьян и зданий ты не знаешь")
    else:
        lines.append(f"  крестьян у противника: {en if en is not None else '?'}")
        # Здания врага лежали в состоянии с самого начала (p<n>_bldgs) и молчали:
        # модель знала, сколько у врага крестьян, и не знала, насколько он
        # отстроен. Игрок 16.09: на открытой карте человек видит и базу врага, и
        # его войска, и шахты — значит скрывать счёт зданий не от чего.
        def _враг(поле):
            return поле_врага(st, mp, поле)
        def _состав(пары):
            """Только то, чего у врага НЕ ноль: пустые нули — шум в каждом такте."""
            куски = []
            for _к, _п in пары:
                _в = _враг(_к)
                try:
                    _в = int(float(_в or 0))
                except (TypeError, ValueError):
                    _в = 0
                if _в:
                    куски.append(f"{_п} {_в}")
            return ", ".join(куски)
        _арм = _враг("army")
        if _арм is not None:
            _сост = _состав((("inf", "пехота"), ("shoot", "стрелки"), ("cav", "конница")))
            lines.append(f"  армия противника: {_арм}"
                         + (f" — {_сост}" if _сост else ""))
        # Здания и шахты названы теми же словами, какими модель отдаёт BUILD:
        # иначе ей придётся переводить «казарму» в ba17 самой, а это лишний
        # повод ошибиться.
        _шах = _состав((("mgold", "gold"), ("miron", "iron"), ("mcoal", "coal")))
        if _шах:
            lines.append(f"  шахты противника: {_шах}")
        _зд = _состав((("center", "center"), ("mill", "mill"), ("smith", "smith"),
                       ("ba17", "ba17"), ("ba18", "ba18"), ("stable", "stable"),
                       ("store", "store"), ("house", "house"), ("tower", "tower"),
                       ("market", "market"), ("academi", "academi")))
        if _зд:
            lines.append(f"  здания противника: {_зд}")
        elif _враг("bldgs") is not None:
            lines.append(f"  зданий у противника: {_враг('bldgs')}")
        if st.get("en_near_dist", -1) not in (-1, "-1"):
            lines.append(f"  ближайший враг в {st.get('en_near_dist')} единицах")
    body = coss3_map.render(st, mp)
    if body:
        lines += ["", body]
    if было is not None and заказ:
        lines += итог_прошлого(было, st, заказ, повторы)
    if вето:
        # Отдельным блоком, а не вместе с браком: брак — это чего мост НЕ ПОНЯЛ,
        # а здесь он понял и отказал сам. Свалить в одну кучу — значит соврать
        # про причину, а модель ошибается ровно настолько, насколько врёт
        # описание мира.
        lines += ["", "## Волну отверг МОСТ, а не игра", f"  {вето}"]
    if брак:
        lines += ["", "## Команды, которые НЕ УШЛИ В ИГРУ",
                  "  Мост их не разобрал, игра их не видела. Проверь имена полей "
                  "по примерам в начале: role и total, для ATTACK count."] + [
            f"  {б}" for б in брак]
    if вмеш:
        # МОСТ ПОДМЕНИЛ КОМАНДУ, и молчать об этом нельзя. Иначе модель отдала
        # BUILDERS 3, увидела мир, где ратуша встала втрое быстрее, и строит
        # дальнейшие рассуждения на том, чего не делала. Это ровно первое
        # правило проекта наоборот, и заметил это игрок, а не я.
        lines += ["", "## Мост вмешался в твой прошлый ответ",
                  f"  {вмеш}",
                  "  Это сделал мост, а не ты. Учитывай при оценке того, что "
                  "вышло, и решай сам, повторять ли такое дальше."]
    if расхождение:
        # Блок «Итог прошлого решения» показывает только ОТДАННЫЕ команды, и
        # ненаписанная команда в нём невидима — модель не узнаёт, что игра о
        # её намерении не услышала. Говорим об этом прямо.
        lines += ["", "## Сказано, но не сделано"] + [
            f"  В прошлом ответе ты написал про {с}, но команды {с} в "
            f"\"commands\" не было — игра её НЕ ПОЛУЧИЛА и ничего по ней не "
            f"сделала. Нужна — отдай её командой." for с in расхождение]
    if дневник:
        lines += дневник
    if history:
        lines += ["", "## Что я делал раньше"] + [
            f"  {h}" for h in history[-ОКНО_ИСТОРИИ:]] if ОКНО_ИСТОРИИ else lines
    if ЗАПРЕТ:
        lines += ["", "## ПРАВИЛА ЭТОЙ ПАРТИИ",
                  f"  Запрещено настройками и не будет построено: "
                  f"{', '.join(sorted(ЗАПРЕТ))}. Не заказывай их — такт пропадёт."]
    if КАНАЛ_ВОПРОСОВ:
        if ВОПРОС_ЗАДАН:
            lines += ["", "## ТВОЙ ВОПРОС ЧЕЛОВЕКУ",
                      f"  Уже задан в эту партию: «{ВОПРОС_ЗАДАН[:120]}». "
                      f"Второй не пройдёт — играй."]
        else:
            lines += ["", "## ТВОЙ ВОПРОС ЧЕЛОВЕКУ — ЕЩЁ НЕ ЗАДАН",
                      "  Если чего-то не видно в состоянии и не выяснить "
                      "командой — спроси сейчас,",
                      "  полем \"question\". Партия кончится, и возможность "
                      "пропадёт вместе с ней."]
    if ОТРЕЗОК:
        _м, _с = divmod(int(ОТРЕЗОК), 60)
        lines += ["", "## ЭТО УЧЕБНЫЙ ОТРЕЗОК",
                  f"  Партия оборвётся на {_м}:{_с:02d}, и начнётся следующая. "
                  f"Цель не меняется,",
                  "  но за такой отрезок её обычно не успеть — это не твоя "
                  "неудача и не повод",
                  "  бросаться в атаку раньше времени. Играй начало так же, как "
                  "в полной партии."]
    if restart_ok:
        lines += ["", "Если партия безнадёжна (базу снесли, ресурсов нет и не будет), "
                  "верни в JSON \"restart\": true и \"restart_why\": \"причина\". "
                  "Это начнёт новую партию с нуля. Без крайней нужды не проси."]
    if мир:
        # Раньше подсказок нарочно: это фон, на котором читается всё
        # остальное. Подсказки — указание, что делать; мир — что вокруг есть.
        lines += ["", мир]
    hints = отобрать_подсказки(hints, st)
    if hints:
        lines += ["", "## ПОДСКАЗКИ ЧЕЛОВЕКА (учитывай в первую очередь)", hints]
    return "\n".join(lines)


# --- Канал вопросов: модель спрашивает, человек отвечает --------------------
#
# До 13.09 модель могла только записать догадку в lesson или idea и никогда не
# получала ответа. Итог — 151 строка lessons.txt, где верное и выдуманное лежат
# вперемешку, а про камень одна и та же мысль переоткрыта двадцать раз. Причина
# не в модели: описание мира неполно (на человеческом слоте в нём нет ни карты,
# ни залежей), а сказать об этом ей нечем.
#
# Здесь петля замыкается. Один вопрос за партию уходит в файл мира, человек
# отвечает между партиями, ответ возвращается в промпт ВСЕМ последующим
# партиям. В отличие от уроков, это безопасно возвращать: пишет человек, а не
# проигравшая модель, и у каждой строки стоит метка источника.
#
# Формат файла (world.md):
#
#     - [код] шахту игра ставит только на залежь, радиус расширения 85
#     - [игрок] на карте 4 залежи золота, 4 угля, 4 железа
#     ## Вопросы
#     - вопрос (эпизод 3, 6:20): сколько залежей золота рядом с базой?
#       ответ: четыре на всю карту, ближайшая к тебе одна
#
# Метка источника обязательна и не для красоты: 13.09 знание игрока про залежи
# оказалось верным, но бесполезным, пока не выяснилось радиусом из кода, что
# мост не умеет строить дальше 26. «Со слов игрока» и «проверено по коду» — не
# одно и то же, и модель должна видеть разницу.

МЕТКИ_ИСТОЧНИКА = ("код", "игрок", "замер")


def разобрать_мир(текст: str) -> tuple[list[str], list[tuple[str, str]]]:
    """Файл мира -> (строки знания, [(вопрос, ответ)]). Ответ пустой = открытый."""
    знание: list[str] = []
    вопросы: list[tuple[str, str]] = []
    в_вопросах = False
    # Строка с отступом — ПРОДОЛЖЕНИЕ предыдущей. Ровно на этом 13.09 уже
    # обожглись с подсказками: двухстрочная подсказка теряла вторую строку, и
    # до модели доезжал обрывок без начала. Здесь то же правило, явно.
    for сырая in текст.splitlines():
        строка = сырая.strip()
        отступ = сырая[:1].isspace()
        if not строка:
            continue
        if строка.lower().startswith("## вопрос"):
            в_вопросах = True
            continue
        if строка.startswith("#"):
            в_вопросах = False              # другой заголовок закрывает раздел
            continue
        if в_вопросах:
            if строка.lower().startswith("ответ:") and вопросы:
                в, о = вопросы[-1]
                вопросы[-1] = (в, (о + " " + строка.split(":", 1)[1].strip()).strip())
            elif строка.startswith("- "):
                тело = строка[2:]
                # «вопрос (эпизод 3, 6:20): текст» — служебную шапку срезаем,
                # модели важен сам вопрос, а не когда он был задан. Резать по
                # первому двоеточию нельзя: оно внутри времени, и от вопроса
                # оставался огрызок «20): сколько...».
                тело = re.sub(r"^вопрос\s*\([^)]*\)\s*:\s*", "", тело,
                              flags=re.IGNORECASE).strip()
                if тело:
                    вопросы.append((тело, ""))
            elif отступ and вопросы:
                в, о = вопросы[-1]
                вопросы[-1] = ((в + " " + строка).strip(), о) if not о \
                    else (в, (о + " " + строка).strip())
        elif строка.startswith("- "):
            знание.append(строка[2:].strip())
        elif отступ and знание:
            знание[-1] = (знание[-1] + " " + строка).strip()
    return знание, вопросы


def мир_для_промпта(текст: str) -> str:
    """Раздел о мире целиком — в отличие от подсказок, он не отбирается по звеньям.

    Знание о мире не устаревает с прохождением цепочки: залежи остаются
    залежами и на первой минуте, и на десятой.
    """
    знание, вопросы = разобрать_мир(текст)
    # Один и тот же вопрос может лежать и в мастере (с ответом), и в рабочем
    # файле (без). Оставляем по одному, с ответом если он есть хоть где-то.
    сведённые: list[tuple[str, str]] = []
    for в, о in вопросы:
        для_него = next((i for i, (в2, _) in enumerate(сведённые)
                         if _тот_же_вопрос(в, в2)), None)
        if для_него is None:
            сведённые.append((в, о))
        elif о and not сведённые[для_него][1]:
            сведённые[для_него] = (сведённые[для_него][0], о)
    вопросы = сведённые
    # Знание тоже может задвоиться, если кто-то скопировал строку в оба файла.
    знание = list(dict.fromkeys(знание))
    строки: list[str] = [f"  {з}" for з in знание]
    строки += [f"  Ответ на твой вопрос «{в}»: {о}" for в, о in вопросы if о]
    открытые = [в for в, о in вопросы if not о]
    куски = []
    if строки:
        куски += ["## ЧТО МЫ ЗНАЕМ О МИРЕ",
                  "  [код] — проверено по коду игры, [игрок] — со слов игрока, "
                  "[замер] — измерено в партии.", *строки]
    if открытые:
        куски += ["## ТВОИ ВОПРОСЫ БЕЗ ОТВЕТА (спрашивать снова не надо)"]
        куски += [f"  {в}" for в in открытые]
    return "\n".join(куски)


def _суть_вопроса(т: str) -> set:
    """Значимые слова вопроса. Сравнение дословное не годится: «сколько залежей
    у моей ратуши» и «сколько залежей у ратуши» — один вопрос, а строки разные.
    """
    слова = re.sub(r"[\W\d_]+", " ", т.lower()).split()
    return {с for с in слова if len(с) > 3}


def _тот_же_вопрос(a: str, b: str) -> bool:
    """Два вопроса об одном? По доле общих слов, порог 0,6 — подобран так,
    чтобы перефразировку считать повтором, а соседнюю тему — нет."""
    A, B = _суть_вопроса(a), _суть_вопроса(b)
    if not A or not B:
        return False
    return len(A & B) / len(A | B) >= 0.6


def записать_вопрос(path: str, вопрос: str, номер: int, gt: int) -> str:
    """Вопрос модели — в файл мира, в раздел «## Вопросы». Возвращает записанное.

    Пустая строка назад значит «не записали», и звать это надо так, чтобы
    причина отброса печаталась: молчаливый отброс неотличим от бездействия.
    """
    вопрос = " ".join(str(вопрос or "").split())[:300]
    if len(вопрос) < 12:
        return ""
    mm, ss = divmod(int(gt), 60)
    строка = f"- вопрос (эпизод {номер}, {mm}:{ss:02d}): {вопрос}"
    try:
        прежнее = open(path, encoding="utf-8").read() if os.path.exists(path) else ""
    except OSError:
        прежнее = ""
    мастер = _мастер_мира()
    if os.path.abspath(мастер) != os.path.abspath(path):
        прежнее = _прочесть(мастер) + "\n" + прежнее
    _, прежние = разобрать_мир(прежнее)
    if any(_тот_же_вопрос(вопрос, в) for в, _ in прежние):
        return ""                           # уже спрашивала — и с ответом, и без
    try:
        with open(path, "a", encoding="utf-8") as f:
            if "## Вопросы" not in прежнее:
                if прежнее and not прежнее.endswith("\n"):
                    f.write("\n")
                f.write("\n## Вопросы\n")
            f.write(строка + "\n")
    except OSError:
        return ""
    return вопрос


def записать_урок(data: dict, path: str, номер: int, gt: int,
                  не_ранее: int = 60) -> str:
    """Наблюдение модели — в отдельный файл, НЕ в промпт.

    Возвращать это обратно в подсказки нельзя: модель, проигравшая партию,
    впишет туда неверный вывод, следующая прочтёт его как истину, и мы получим
    машину закрепления ошибок. По TRAINING_PLAN такие гипотезы проверяются
    отдельно на фиксированных сидах и принимаются только если бьют чемпиона.
    Здесь мы их лишь собираем — материал для той проверки.
    """
    урок = str(data.get("lesson", "") or "").strip()
    if not урок or len(урок) < 12 or урок.lower() in ("none", "null", "-"):
        return ""
    if gt < не_ранее:
        # На первых секундах результатов ещё нет, и в lesson попадают планы
        # («строю центр, потом мельницу»), а не выводы. Планы нам не нужны:
        # файл читается как материал для проверки гипотез.
        return ""
    mm, ss = divmod(gt, 60)
    строка = f"эпизод {номер}, {mm}:{ss:02d} — {урок[:200]}"
    # Сравниваем БЕЗ ЧИСЕЛ: «камень узкое место, 60% на камень» и то же самое
    # с 70% — один и тот же урок. В файле на 11.09.2026 таких повторов о камне
    # набралось больше двадцати, и журнал рос, не прибавляя знания.
    def суть(т: str) -> str:
        return re.sub(r"\d+", "#", т.lower())[:90]

    try:
        прежние = open(path, encoding="utf-8").read() if os.path.exists(path) else ""
        if урок[:200] in прежние:
            return ""                       # то же самое, второй раз не пишем
        к = суть(урок)
        if any(суть(стр.split("—", 1)[-1].strip()) == к
               for стр in прежние.splitlines() if стр.strip()):
            return ""                       # та же мысль, другие числа
        with open(path, "a", encoding="utf-8") as f:
            f.write(строка + "\n")
    except OSError:
        return ""
    return урок[:200]


def рассказ(data: dict) -> list[str]:
    """Три строки объяснения от модели — их видно в окне поверх игры.

    Ключи латиницей нарочно: русские имена полей модели путают чаще, а текст
    внутри всё равно требуется по-русски.
    """
    строки = []
    for ключ, подпись in (("ok", "идёт"), ("stuck", "не идёт"), ("cause", "почему")):
        v = str(data.get(ключ, "") or "").strip()
        if v and v.lower() not in ("none", "null", "-"):
            строки.append(f"        {подпись}: {v[:110]}")
    return строки


# Как модель может назвать поля команды. Разные модели зовут их по-разному, а
# 11.09.2026 выяснилось, чем это кончается: haiku-4.5 писала
# {"cmd":"BALANCE","resource":"stone","value":60} — совершенно верное решение,
# парой 60/40 — а to_commands требовала "role", не находила и выбрасывала
# команду МОЛЧА. В игру не уходило ничего, в логе не появлялось ничего, и по
# логу это выглядело так, будто модель про камень даже не подумала. Синонимы
# дешевле ещё одного абзаца в промпте и работают на любой модели.
СИНОНИМ_РОЛИ = ("role", "resource", "res", "unit", "building", "target",
                "name", "what", "upgrade")
СИНОНИМ_ЧИСЛА = ("total", "count", "value", "amount", "qty", "num", "n",
                 "percent", "share")


def нормализовать(item: dict) -> tuple[str, str, int]:
    """Одна команда модели -> (КОМАНДА, роль, число), как бы она её ни назвала."""
    c = str(item.get("cmd", item.get("command", ""))).upper().strip()
    роль = ""
    for k in СИНОНИМ_РОЛИ:
        v = item.get(k)
        if isinstance(v, str) and v.strip():
            роль = v.strip()
            break
    число = 0
    for k in СИНОНИМ_ЧИСЛА:
        if k in item:
            try:
                число = int(float(item[k]))
                break
            except (TypeError, ValueError):
                continue
    return c, роль, число


def _клетка_из(item):
    """cx/cy из ответа модели. Принимаем и пару полей, и список [x, y]:
    модель пишет то так, то так, а браковать за форму — терять такт."""
    c = item.get("cell", item.get("cxcy"))
    if isinstance(c, (list, tuple)) and len(c) == 2:
        пара = c
    else:
        пара = (item.get("cx"), item.get("cy"))
    try:
        cx, cy = int(пара[0]), int(пара[1])
    except (TypeError, ValueError):
        return None
    if 0 <= cx <= 15 and 0 <= cy <= 15:
        return (cx, cy)
    return None

def to_commands(data: dict, доступные: set[str] | None = None
                ) -> tuple[list, int, str, list[str], str, int, str]:
    """JSON модели -> команды моста. Что не разобралось — возвращаем строками.

    Раньше непонятное отбрасывалось молча, и потерянная команда была неотличима
    от ненаписанной: ни в игре, ни в логе, ни в следующем запросе. Теперь брак
    называется вслух — и в консоли, и в промпте следующего такта.
    """
    cmds, attack, брак = [], 0, []
    цель_атаки = "base"
    движение, цель_движения = 0, "home"
    # Клетка цели: (-1, -1) означает «модель её не называла».
    клетка = (-1, -1)
    # КОНТРАКТ МАРША (18.09, по документу игрока о манёврах): клетка сбора,
    # порог входа в бой, срок. Всё это пишет МОДЕЛЬ в своей команде, мост
    # только исполняет — иначе решение уходило бы от модели к мосту.
    контракт: dict = {}
    _все = data.get("commands") or []
    _предел = ПОЛИТИКА["команд_за_такт"]
    if len(_все) > _предел:
        # Молчаливый отброс неотличим от бездействия: до 16.09 седьмая команда
        # исчезала без слова, и модель считала, что отдала её.
        брак.append(f"команд в ответе {len(_все)}, мост читает первые "
                    f"{_предел} — не ушли: "
                    + ", ".join(str(i.get("cmd", "?")) for i in _все[_предел:]))
    for item in _все[:_предел]:
        if not isinstance(item, dict):
            брак.append(f"{item!r}: команда должна быть объектом JSON")
            continue
        c, role, total = нормализовать(item)
        поля = ", ".join(sorted(k for k in item if k != "cmd"))
        try:
            if role and role in ЗАПРЕТ:
                брак.append(f"{c} {role}: запрещено настройками этой партии")
                continue
            if c == "BUILD":
                if role not in BUILDABLE:
                    брак.append(f"BUILD {role or '?'}: такую постройку мост не умеет"
                                f" (поля: {поля}). Роли: {', '.join(sorted(BUILDABLE))}")
                elif total <= 0:
                    брак.append(f"BUILD {role}: нужно ИТОГО зданий числом > 0"
                                f" в поле total (поля: {поля})")
                else:
                    cmds.append(build(role, total))
            elif c == "TRAIN":
                if role not in ROLE:
                    брак.append(f"TRAIN {role or '?'}: неизвестный юнит"
                                f" (поля: {поля})")
                elif total == 0:
                    брак.append(f"TRAIN {role}: число 0 — это ничего не значит;"
                                f" отрицательное = бесконечный заказ (поля: {поля})")
                else:
                    # Отрицательное = бесконечное производство, см. train().
                    cmds.append(train(role, max(total, INFINITE)))
            elif c == "UPGRADE":
                # Сверяем с тем, что игра назвала доступным ЭТОЙ нации, а не со
                # статическим списком: тот достался от компьютерного слота, где
                # апгрейды заказывались по движковым константам. На человеческом
                # слоте имена другие (eurmil.1), и ни одно имя из старого списка
                # не могло совпасть никогда — 13.09 это стоило 21 такта.
                if доступные and role not in доступные:
                    брак.append(
                        f"UPGRADE {role or '?'}: у твоей нации такого нет. "
                        f"Доступно: {', '.join(sorted(доступные))}")
                elif not role:
                    брак.append(f"UPGRADE: нужно имя в поле role (поля: {поля})")
                else:
                    cmds.append(upgrade(role))
            elif c == "MOVE":
                # То же движение, что у ATTACK, но без режима атаки: бойцы идут
                # и не ищут врага по дороге. Человек двигает войска кликом и не
                # обязан вести их в бой; у бота такой возможности не было вовсе.
                if total > 0:
                    движение = max(движение, total)
                    цель = str(item.get("target", item.get("where", ""))).strip().lower()
                    if цель in ПОЛИТИКА["цели_MOVE"]:
                        цель_движения = цель
                        if цель == "cell":
                            кл = _клетка_из(item)
                            if кл is None:
                                цель_движения = "home"
                                брак.append(
                                    f"MOVE target=cell: нужна клетка сетки, "
                                    f"поля cx и cy от 0 до 15 (поля: {поля}). "
                                    f"Иду на home")
                            else:
                                клетка = кл
                    elif цель:
                        брак.append(f"MOVE target={цель}: не знаю такой цели; "
                                    f"можно home, peasants, base, army, cell")
                else:
                    брак.append(f"MOVE: нужно число бойцов > 0 в поле count"
                                f" (поля: {поля})")
            elif c == "ATTACK":
                if total > 0:
                    attack = max(attack, total)
                    цель = str(item.get("target", item.get("where", ""))).strip().lower()
                    if цель in ПОЛИТИКА["цели_ATTACK"]:
                        цель_атаки = цель
                        if цель == "cell":
                            кл = _клетка_из(item)
                            if кл is None:
                                цель_атаки = "peasants"
                                брак.append(
                                    f"ATTACK target=cell: нужна клетка сетки, "
                                    f"поля cx и cy от 0 до 15 (поля: {поля}). "
                                    f"Иду на peasants")
                            else:
                                клетка = кл
                        # Контракт марша. Каждое поле — решение модели, и
                        # каждое непринятое поле называется вслух.
                        via = item.get("via")
                        if via is not None:
                            кл_via = _клетка_из(via) if isinstance(via, dict) else None
                            if кл_via is None:
                                брак.append(f"ATTACK via: нужна клетка сбора вида "
                                            f'{{"cx":x,"cy":y}} от 0 до 15 (поля: '
                                            f"{поля}). Иду без сбора, прямо из дома")
                            else:
                                контракт["via"] = кл_via
                        порог = item.get("hold_if_outnumbered")
                        if порог is not None:
                            try:
                                контракт["hold"] = float(порог)
                                if контракт["hold"] <= 0:
                                    raise ValueError
                            except (TypeError, ValueError):
                                контракт.pop("hold", None)
                                брак.append(f"ATTACK hold_if_outnumbered={порог}: "
                                            f"нужно число больше нуля, например 1.3")
                        срок = item.get("expires")
                        if срок is not None:
                            try:
                                контракт["expires"] = int(float(срок))
                                if контракт["expires"] <= 0:
                                    raise ValueError
                            except (TypeError, ValueError):
                                контракт.pop("expires", None)
                                брак.append(f"ATTACK expires={срок}: нужно число "
                                            f"секунд больше нуля")
                        if item.get("retreat_below") is not None:
                            # Честно: отозвать бойцов из боя мост пока не умеет —
                            # MOVE берёт только свободных. Поле принято в трассу,
                            # но не исполняется, и модель должна это знать.
                            контракт["retreat"] = item.get("retreat_below")
                            брак.append("ATTACK retreat_below: принято, но НЕ "
                                        "ИСПОЛНЯЕТСЯ — отзывать бойцов из боя мост "
                                        "пока не умеет; отход возможен только "
                                        "свободными через MOVE home")
                    elif цель:
                        брак.append(f"ATTACK target={цель}: не знаю такой цели; "
                                    f"можно peasants, base, army, cell, wave")
                else:
                    брак.append(f"ATTACK: нужно число бойцов > 0 в поле count"
                                f" (поля: {поля})")
            elif c == "FORMATION":
                # ОТКЛЮЧЕНА 16.09. Строй в нынешнем виде собирается вокруг
                # офицера, а офицер и барабанщик делаются ТОЛЬКО в академии
                # (country.script:3047,3051 — требование csid+'aca'), и она
                # запрещена настройками партии (--ban academi). То есть команда
                # не могла сработать ни разу.
                #
                # Отброс не молчаливый (правило 1): говорим причину. Из промпта
                # команда убрана, но если модель вспомнит её по памяти — она
                # услышит, почему нет, а не получит тишину.
                брак.append(
                    "FORMATION: строй сейчас недоступен. Он собирается вокруг "
                    "офицера, а офицер и барабанщик делаются только в академии, "
                    "и академия запрещена настройками этой партии")
            elif c == "SEED":
                # Поля сеют вокруг мельницы, числа не нужно. Еда не залежь: без
                # посева BALANCE food некуда слать людей, и запас только падает.
                cmds.append(seed())
            elif c == "BUILDERS":
                if total > 0:
                    cmds.append(builders(total))
                else:
                    брак.append(f"BUILDERS {total}: нужно число > 0 — сколько "
                                f"крестьян максимум на одну стройку")
            elif c == "BALANCE":
                if role not in RESOURCE:
                    брак.append(f"BALANCE {role or '?'}: ресурс не опознан"
                                f" (поля: {поля}). Только: "
                                f"{', '.join(RESOURCE)}")
                else:
                    cmds.append(balance(role, total))
            else:
                брак.append(f"{c or '?'}: нет такой команды (поля: {поля})")
        except ValueError as e:
            брак.append(f"{c} {role}: {e}")
    # Атака важнее движения: если модель отдала обе, идём в бой, а про
    # проглоченный MOVE говорим вслух - молчаливый отброс неотличим от отказа.
    if attack and движение:
        брак.append("MOVE и ATTACK в одном ответе: выполнен ATTACK, "
                    "движение пропущено — файл приказа один")
        движение = 0
    return (cmds, attack, str(data.get("why", ""))[:200], брак, цель_атаки,
            движение, цель_движения, клетка, контракт)


MAX_TOKENS = 1200         # с запасом: обрезанный ответ теряет весь такт
LAST_TOKENS = 0           # токенов в последнем ответе: отличить болтливость от очереди
LAST_PROVIDER = ""        # кто обслужил: у OpenRouter это решает всё
# Провайдеры, которые не обслуживают наш регион. Отказ у них постоянный, так что
# запоминаем на сессию и просим OpenRouter больше туда не бросать.
BANNED: set[str] = set()
ЗАПРЕТ: set[str] = set()   # роли, запрещённые настройками партии (--ban)
ONLY: list[str] = []      # если задан — маршрут только через этих, без запасных
AUTOBAN = True            # выключается --no-provider-ban, чтобы проверить руками
REPLAY: list[dict] = []   # заранее записанные ответы вместо вызова модели
_REPLAY_I = 0
_REPLAY_LOCK = threading.Lock()


def загрузить_реплей(путь: str) -> int:
    """Ответы модели из файла: по JSON на строку, либо несколько подряд.

    Зачем: ключ живёт на игровой машине, а петлю надо проверять на маке. С
    реплеем `llm_policy.py` против `mock_game.py` прогоняется целиком и без
    сети — видно, доезжают ли до модели новые блоки запроса, живут ли счётчики
    между тактами, отбрасывается ли урок. Ответы из настоящего лога достаёт
    `log_review.py --replay-out`, и тогда это прогон по исторической партии:
    мост обязан ругаться там, где в тот раз промолчал.
    """
    текст = open(путь, encoding="utf-8").read()
    ответы = []
    for строка in текст.splitlines():
        строка = строка.strip()
        if not строка or строка.startswith("#"):
            continue
        try:
            ответы.append(json.loads(строка))
        except ValueError:
            ответы.extend(json_objects(строка))
    if not ответы:                          # не построчный файл — разберём целиком
        ответы = json_objects(текст)
    REPLAY.extend(ответы)
    return len(ответы)


def следующий_ответ() -> dict:
    global _REPLAY_I
    with _REPLAY_LOCK:
        if _REPLAY_I >= len(REPLAY):
            raise RuntimeError(f"ответы для --replay кончились ({len(REPLAY)} шт.)")
        _REPLAY_I += 1
        return REPLAY[_REPLAY_I - 1]


def json_objects(text: str) -> list[dict]:
    """Разобранные ответы модели, по порядку.

    Пробуем от КАЖДОЙ «{», а не считаем баланс скобок с начала: модель бросает
    недописанный объект и начинает заново, и одна незакрытая скобка в начале
    иначе проглатывает весь остальной текст.
    """
    dec = json.JSONDecoder()
    out = []
    for i, ch in enumerate(text):
        if ch != "{":
            continue
        try:
            obj, _ = dec.raw_decode(text, i)
        except ValueError:
            continue                       # огрызок — идём к следующей скобке
        if isinstance(obj, dict) and ("commands" in obj or "why" in obj):
            out.append(obj)                # внутренние {"cmd":...} сюда не попадут
    return out


# --- СХЕМА ОТВЕТА (нативный structured output) ---------------------------
#
# До 16.09 мост ПРОСИЛ вернуть JSON словами и разбирал что придёт: ловил
# огрызки, синонимы полей ('count' вместо 'total', 'building' вместо 'role')
# и куски текста вокруг скобок. Сколько такого было, видно в отчёте: строка
# «команд отвергнуто» и блок «Команды, которые НЕ УШЛИ В ИГРУ».
#
# Схема описывает РОВНО то, что мост и так разбирает, и ничего сверх: имена
# полей канонические, число у BUILD/TRAIN/BALANCE/BUILDERS это total, у
# ATTACK/MOVE — count, у UPGRADE имя лежит в role. Разбор остаётся прежним:
# схема сужает вход, а не заменяет проверку. Провайдер, который схемы не
# знает, ответит отказом — тогда мост снимает её, говорит об этом вслух и
# доигрывает как раньше.
_КОМАНДА_СХЕМА = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "cmd": {"type": "string",
                # FORMATION убрана из схемы 16.09 вместе с описанием: см.
                # комментарий у "команды" выше.
                "enum": ["BUILD", "TRAIN", "BALANCE", "BUILDERS",
                         "SEED", "UPGRADE", "ATTACK", "MOVE"]},
        "role": {"type": ["string", "null"],
                 "description": "роль здания/юнита/ресурса; для UPGRADE — имя апгрейда"},
        "total": {"type": ["integer", "null"],
                  "description": "желаемый ИТОГ для BUILD/TRAIN/BALANCE/BUILDERS; -1 — без счёта"},
        "count": {"type": ["integer", "null"],
                  "description": "сколько бойцов для ATTACK и MOVE"},
        "target": {"type": ["string", "null"],
                   "enum": ["peasants", "base", "army", "home", "cell", "wave", None]},
    },
    "required": ["cmd", "role", "total", "count", "target"],
}

СХЕМА_ОТВЕТА = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "why": {"type": "string", "description": "что делаешь сейчас и зачем, одно предложение"},
        "ok": {"type": "string", "description": "что получается; пусто, если сказать нечего"},
        "stuck": {"type": "string", "description": "что НЕ получается; пусто, если всё идёт"},
        "cause": {"type": "string", "description": "почему не получается"},
        "lesson": {"type": "string", "description": "вывод из СЛУЧИВШЕГОСЯ; пусто, если ничего не произошло"},
        "idea": {"type": "string", "description": "гипотеза об устройстве игры; пусто, если нет"},
        "question": {"type": "string", "description": "один вопрос человеку; пусто, если нет"},
        "commands": {"type": "array", "items": _КОМАНДА_СХЕМА},
    },
    "required": ["why", "ok", "stuck", "cause", "lesson", "idea",
                 "question", "commands"],
}

СХЕМОЙ = False         # --schema включает; отказ провайдера снимает обратно


def ask(client, model: str, prompt: str, think: bool = False,
        retry: int = 1, max_tokens: int = 0) -> dict:
    if REPLAY:                              # --replay: модель не зовём вовсе
        return следующий_ответ()
    kw = dict(
        model=model,
        messages=[{"role": "system", "content": SYSTEM},
                  {"role": "user", "content": prompt}],
        temperature=0.4,
        max_tokens=max_tokens or MAX_TOKENS,
    )
    if СХЕМОЙ:
        kw["response_format"] = {
            "type": "json_schema",
            "json_schema": {"name": "coss3_move", "strict": True,
                            "schema": СХЕМА_ОТВЕТА},
        }
    extra: dict = {}
    if ONLY:
        extra["provider"] = {"order": list(ONLY), "allow_fallbacks": False}
    elif BANNED:
        extra["provider"] = {"ignore": sorted(BANNED)}
    # nemotron-3.5 по умолчанию рассуждает вслух и съедает лимит, не дойдя до
    # JSON. В такт это не влезает, поэтому рассуждения гасим. Модель, которая
    # такого ключа не знает, ответит 400 — тогда повторяем без него.
    if not think:
        extra["chat_template_kwargs"] = {"enable_thinking": False}
        # То же самое на языке OpenRouter. Ключ выше понимают NIM и vLLM, а
        # OpenRouter — нет, и рассуждающая модель через него съедает лимит,
        # не дойдя до JSON. Замер 11.09.2026 на deepseek-v4.1-flash, один и
        # тот же запрос: без этого поля 75 с и ответ обрезан на 1200 токенах,
        # с ним — 1,8 с и 84 токена. Провайдер, который поля не знает, ответит
        # 400, и весь extra_body снимается ниже.
        extra["reasoning"] = {"enabled": False}
    if extra:
        kw["extra_body"] = extra
    try:
        r = client.chat.completions.create(**kw)
    except Exception as e:
        msg = str(e)
        # Регион не поддерживается — отказ навсегда. Запоминаем провайдера и
        # сразу пробуем ещё раз, попросив OpenRouter его обойти.
        if AUTOBAN and not ONLY and "unsupported_country_region_territory" in msg:
            имя = re.search(r"'provider_name':\s*'([^']+)'", msg)
            if имя and имя.group(1) not in BANNED:
                BANNED.add(имя.group(1))
                print(f"        {имя.group(1)} не обслуживает наш регион — "
                      f"исключаю его из маршрутизации")
                return ask(client, model, prompt, think, retry)
        if "404" in msg or "not found" in msg.lower():
            # Пресет — не модель, и совет про каталог NVIDIA тут вреден: он
            # уводит от настоящей причины. 12.09 на этом потеряли круг: мост
            # подменил ответ сервера догадкой. Показываем, что сказал сервер.
            if model.startswith("@preset/"):
                raise RuntimeError(
                    f"пресет {model} не найден. Что проверить, по порядку:\n"
                    f"        1) пресет создан и СОХРАНЁН на openrouter.ai/settings/presets;\n"
                    f"        2) Slug совпадает буква в букву: "
                    f"{model.split('/', 1)[1]!r} (он не равен названию);\n"
                    f"        3) ключ из nim_key.txt принадлежит ТОМУ ЖЕ аккаунту, "
                    f"где лежит пресет;\n"
                    f"        4) в пресете выбрана хотя бы одна модель.\n"
                    f"        Ответ сервера: {msg[:300]}") from e
            raise RuntimeError(
                f"модель {model} не отвечает — её убрали из каталога?\n"
                f"        сверьтесь с openrouter.ai/models и задайте другую: "
                f"--model <id> или COSS3_MODEL\n"
                f"        Ответ сервера: {msg[:300]}") from e
        # Схему понимают не все провайдеры. Снимаем её НАВСЕГДА для этого
        # прогона и говорим вслух: молчаливый откат неотличим от того, что
        # схема работает, и в отчёте потом не понять, что именно проверялось.
        if "response_format" in kw and any(
                w in msg.lower() for w in
                ("response_format", "json_schema", "structured output",
                 "schema", "json mode")):
            globals()["СХЕМОЙ"] = False
            kw.pop("response_format")
            print("        провайдер не принял СХЕМУ ОТВЕТА — снимаю её до конца "
                  "прогона, дальше как раньше: просьбой вернуть JSON")
            return_r = client.chat.completions.create(**kw)
            r = return_r
        else:
            # Откат делаем ТОЛЬКО на отказ разобрать запрос. На таймауте и обрыве
            # повторять нельзя: вторая попытка удвоит и без того съеденный такт.
            отказ = any(w in msg.lower() for w in
                        ("400", "422", "extra", "not permitted", "unexpected",
                         "unrecognized", "invalid"))
            if "extra_body" not in kw or not отказ:
                raise
            kw.pop("extra_body")            # ключ рассуждений понимают не все
            r = client.chat.completions.create(**kw)
    global LAST_TOKENS, LAST_PROVIDER
    LAST_TOKENS = getattr(getattr(r, "usage", None), "completion_tokens", 0) or 0
    LAST_PROVIDER = str(getattr(r, "provider", "") or "")
    ch = r.choices[0]
    text = ch.message.content or ""
    objs = json_objects(text)
    if objs:
        rich = [o for o in objs if o.get("commands")]
        return (rich or objs)[-1]          # последний непустой: он и есть ответ
    fin = getattr(ch, "finish_reason", "") or "?"
    if retry > 0:                          # мусор бывает разовым — переспросим
        return ask(client, model, prompt, think, retry - 1)
    if fin == "length":
        raise ValueError(
            f"ответ обрезан на {MAX_TOKENS} токенах, до JSON модель не дошла. "
            f"Хвост: ...{text[-160:]}")
    # Показываем ответ ЦЕЛИКОМ (до 2000 символов). 14.09 здесь стояло 300, и
    # четыре подряд неудачи критика выглядели как «ответ обрезан провайдером»,
    # хотя обрезал их сам этот print. Чинить по обрезанной улике нельзя.
    raise ValueError(f"нет разбираемого JSON (finish_reason={fin}), "
                     f"длина {len(text)}: {text[:2000]}")


def одна_партия(a, client, br: Bridge, plind: int,
                номер_эпизода: int = 1) -> str:
    """Ведёт одну партию до конца. Возвращает исход:
    «цель» — крестьянин убит, «горизонт» — время вышло,
    «обрыв» — состояние перестало обновляться.
    """
    # ВАЖНО: сначала проглотить то, что лежит в файле, и только потом ждать
    # новую запись. После NEW в файле ещё состояние ПРОШЛОЙ партии — с её
    # игровым временем. Первый запрос уходил на нём, next_call назначался в
    # будущее прошлой партии, и цикл молчал полторы минуты.
    br.read_state()
    # После NEW игра ГЕНЕРИРУЕТ карту, и первого состояния приходится ждать
    # дольше обычного такта. 13.09 на живой игре переход между эпизодами занял
    # больше 31 с, а здесь стояли жёсткие 30 — и исправная загрузка была
    # объявлена обрывом, с диагностикой про «игра свёрнута или на паузе».
    # Ждём столько же, сколько ждёт сам запуск партии, и говорим, чего ждём:
    # молчащее ожидание неотличимо от зависания.
    первое_ожидание = float(a.new_timeout) if (a.new or номер_эпизода > 1) else 30.0
    st = None
    _крайний = time.time() + первое_ожидание
    while st is None:
        _осталось = _крайний - time.time()
        if _осталось <= 0:
            break
        try:
            st = br.wait_state(timeout=min(15.0, max(1.0, _осталось)))
        except TimeoutError:
            if _крайний - time.time() > 0:
                print(f"жду первое состояние новой партии: прошло "
                      f"{int(первое_ожидание - (_крайний - time.time()))} с из "
                      f"{int(первое_ожидание)} (после NEW игра генерирует карту)",
                      flush=True)
    if st is None:
        # Партия могла кончиться ДО того, как мы к ней подключились: так бывает
        # в контейнере, где политика встаёт после игры. Спрашиваем игру, но
        # только про свежие файлы — замороженное состояние прошлой партии лежит
        # рядом и назвало бы её исход вместо нынешнего.
        исход = br.outcome(свежесть=30)
        if исход:
            return конец_партии(a, br, исход, br.raw.get("gametime", 0))
        if первое_ожидание > 30:
            print(f"новая партия не подала состояния за {int(первое_ожидание)} с "
                  f"после NEW. Если карта всё ещё грузится — поднимите "
                  f"--new-timeout")
        stalled(br.save_dir, plind, no_mode=a.no_mode)
        return "обрыв"
    # НА КАКОЙ СЕКУНДЕ мы подключились. Это первое, что решает, сравним ли
    # прогон с другими. 12.09 партию заводили руками: сначала игра и бой, потом
    # отдельной командой политика — и бот не существовал первые полторы минуты.
    # По трассе это выглядело как «бот полторы минуты ничего не строил», то есть
    # инструмент показывал артефакт запуска как поведение модели.
    старт_gt = int(st.get("gametime", 0) or 0)
    if старт_gt > ПОЗДНО:
        мм, сс = divmod(старт_gt, 60)
        print(f"\n{'!' * 60}\n"
              f"ПОДКЛЮЧИЛИСЬ К ИДУЩЕЙ ПАРТИИ: она уже на {мм}:{сс:02d}.\n"
              f"Всё это время бот не играл, а игра шла. С прогонами, начатыми\n"
              f"с нуля, этот НЕ СРАВНИМ: разница будет не про идею, а про то,\n"
              f"сколько партия прожила без бота.\n"
              f"Начинать партию и политику надо одной командой: `--new` здесь\n"
              f"или COSS3_EXPERIMENT в контейнере.\n"
              f"{'!' * 60}")
        if a.max_start and старт_gt > a.max_start:
            print(f"--max-start {a.max_start}: не играю на такой партии")
            return "поздно"
    первый = not globals().get("_ШАПКА")
    globals()["_ШАПКА"] = True
    print(f"слот P{plind}, модель {a.model}, решение раз в {a.every} игровых секунд")
    if первый:                               # это одно и то же каждый эпизод
        _h = load_hints(a.hints)
        _в_промпте = отобрать_подсказки(_h, st)
        print(f"подсказки из {a.hints}, читаются перед каждым решением")
        print(f"  файл {len(_h)} симв., в промпт идёт {len(_в_промпте)} "
              f"(~{len(_в_промпте) // 3} токенов): # и пройденные звенья отброшены")
        if отброшенные_метки:
            print(f"  ОТБРОШЕНЫ ПО ЗВЕНЬЯМ: {', '.join(sorted(отброшенные_метки))} — "
                  f"эти строки в промпт НЕ пойдут.\n"
                  f"  Осторожно с [экономика]: звено проходится при peasants>=15, "
                  f"а партия начинается с 18,\n"
                  f"  то есть такая подсказка не дойдёт до модели ни разу. "
                  f"Снимите метку, если она нужна всегда")
        _плохие = неизвестные_метки(_h)
        if _плохие:
            print(f"  ВНИМАНИЕ: метки не из звеньев — {', '.join(sorted(set(_плохие)))}."
                  f"\n  Такие строки видны всегда. Звенья: {', '.join(ЗВЕНЬЯ)}")
        if len(_в_промпте) > 2500:
            print("  великовато. Пометьте строки звеном — [кузница], [казарма],\n"
                  "  [армия], [волна], [экономика] — они исчезнут, когда звено пройдено.\n"
                  "  Устойчивые правила держите в SYSTEM или в policy.py")
    if первый and a.world:
        # Канал вопросов включён — сказать об этом вслух и показать, что уже
        # накоплено. Молчащий канал неотличим от выключенного, а цена ошибки
        # здесь высокая: модель потратит вопрос, а человек его не увидит.
        try:
            _сыр = open(a.world, encoding="utf-8").read()
        except OSError:
            _сыр = ""
            print(f"КАНАЛ ВОПРОСОВ: файла {a.world} ещё нет — будет создан "
                  f"первым же вопросом модели")
        _зн, _воп = разобрать_мир(_сыр)
        _отв = [1 for _, о in _воп if о]
        if _сыр:
            print(f"мир из {a.world}: {len(_зн)} строк знания, "
                  f"{len(_отв)} отвеченных вопросов, "
                  f"{len(_воп) - len(_отв)} открытых — всё идёт в промпт целиком")
        print(f"  модель может задать {a.questions} вопрос(а) за партию; "
              f"ответы писать строкой «  ответ: ...» под вопросом")
        if _зн and not any(m in " ".join(_зн) for m in ("[код]", "[игрок]", "[замер]")):
            print("  ВНИМАНИЕ: ни у одной строки нет метки источника "
                  "([код]/[игрок]/[замер]) — модель не отличит проверенное от слов")
    print()

    if a.max_commands != ПОЛИТИКА["команд_за_такт"]:
        _старое = ЧИСЛИТЕЛЬНОЕ[ПОЛИТИКА["команд_за_такт"]]
        _новое = ЧИСЛИТЕЛЬНОЕ.get(a.max_commands, str(a.max_commands))
        ПОЛИТИКА["команд_за_такт"] = a.max_commands
        globals()["SYSTEM"] = SYSTEM.replace(
            f"Не больше {_старое} команд.", f"Не больше {_новое} команд.")
        print(f"предел команд за такт: {a.max_commands} (умолчание 7). "
              f"Шестёрка до 16.09 пришла из первого коммита человеческого слота "
              f"и ничем не обоснована; в 33 тактах из 153 модель упиралась в неё")
    globals()["КРИТИК_ВПЕРЁД"] = bool(getattr(a, "critic_forward", False))
    if getattr(a, "critic_forward", False):
        print("гипотеза критика ВОЗВРАЩАЕТСЯ в следующую партию как задание на "
              "проверку (--critic-forward)")
    globals()["СХЕМОЙ"] = bool(a.schema)
    if a.schema:
        print("ответ по СХЕМЕ (нативный structured output): поля и команды "
              "описаны json-схемой, а не просьбой вернуть JSON.")
        print("  провайдер без схемы — мост скажет и доиграет по-старому "
              "(--no-schema — выключить заранее)")
    else:
        print("схема ответа не просится (умолчание): JSON просим словами, как "
              "играли base9-base11. Включить: --schema")
    globals()["ЧЕСТНО"] = bool(a.fair)
    if a.fair:
        print("честная игра: числа противника в запрос не идут, ПОКА карта "
              "закрыта. Открыта (монгольфьер всем, --balloon 2) — идут: там их "
              "видит и человек")
    else:
        print("ВНИМАНИЕ: --unfair. Мост подсказывает модели то, чего человек не "
              "видит. Такой прогон с честными сравнивать нельзя")
    globals()["КАНАЛ_ВОПРОСОВ"] = bool(a.world)
    globals()["ВОПРОС_ЗАДАН"] = ""       # счёт на партию, не на прогон
    globals()["ОТРЕЗОК"] = max(0, int(a.stop_at))
    if ОТРЕЗОК:
        _м, _с = divmod(ОТРЕЗОК, 60)
        print(f"учебный отрезок: партия обрывается на {_м}:{_с:02d} и начинается "
              f"новая (цель прежняя, горизонт {a.horizon} не отменён)")
    globals()["WAVE_MIN"] = max(0, int(a.wave_min))
    globals()["ОКНО_ИСТОРИИ"] = max(0, int(a.history))
    if a.history != 5:
        print(f"окно истории: {a.history} прошлых ходов "
              f"(по умолчанию 5; 0 — не показывать; больше числа тактов = вся партия)")
    # Размер запроса — не мелочь: бюджет такта 20 секунд, и он тратится на
    # ожидание ответа. Замер 13.09: SYSTEM 16 159 символов (~5 400 токенов) и
    # уходит КАЖДЫЙ такт, обстановка при окне 5 — около 630 токенов, при полной
    # истории партии — около 2 570. То есть голова втрое тяжелее хвоста, и
    # спорить про размер истории, не зная этого, бессмысленно.
    # Разделы дописываем ДО замера. Раньше и человеческий раздел, и канал
    # вопросов приклеивались ниже, и строка называла размер, которого в запросе
    # не будет: 16 159 символов она показывала и с ними, и без них.
    if a.human and SYSTEM_HUMAN not in SYSTEM:
        globals()["SYSTEM"] = SYSTEM + SYSTEM_HUMAN
    if a.world and SYSTEM_QUESTION not in SYSTEM:
        globals()["SYSTEM"] = SYSTEM + SYSTEM_QUESTION
    print(f"SYSTEM: {len(SYSTEM)} симв. (~{len(SYSTEM)//3} токенов), "
          f"уходит в каждом запросе"
          + (" (+раздел человека)" if a.human else "")
          + (" (+канал вопросов)" if a.world else ""))
    globals()["ЧЕЛОВЕК"] = bool(a.human)
    if WAVE_MIN:
        print(f"минимальный размер волны: {WAVE_MIN}. Мост НЕ держит волну, когда "
              f"бойцов меньше;\n  отвергается заниженный запрос при полной армии "
              f"(--wave-min 0 — выключить)")
    else:
        print("порог волны выключен (--wave-min 0): уйдёт любое число бойцов")
    if a.human:
        # На человеческом слоте выключать нечего: ProgressAI там не запускается
        # вовсе (progress.inc зовёт его только для bai или человека с советником).
        print("человеческий слот: нативного ИИ нет по построению, MODE не шлём")
        print("проверь в игре: свой слот ЧЕЛОВЕК, советник ВЫКЛЮЧЕН")
    elif not a.no_mode and br.send([mode(True, own_war=not a.native_war)]):
        # Не ждём wait_consumed: игра забирает файл на своём тике и без нас, а
        # ожидание стоило целого тика до первого решения.
        print("нативный билд-ордер выключен, ведёт модель")
        print("нативная атака " + ("ОСТАВЛЕНА: волны шлёт движок"
                                   if a.native_war else
                                   "выключена: волны идут только по команде ATTACK"))

    history: list[str] = []
    вопросов_задано = 0                  # один за партию: человек — узкое место
    дневник = Дневник() if a.memo else None
    ТРАССА_ПАРТИИ.clear()
    ВЕХА_УБИЙСТВО.clear()
    УРОКИ_ПАРТИИ.clear()
    УДАР.clear()
    ОТПРАВКА.clear()
    МАРШ.clear()
    ПОЛЕ.clear()
    # Критик живёт в main, а дневник — здесь; отдаём его наружу, чтобы разбор
    # видел ту же партию, а не собирал её заново из трассы.
    globals()["ПОСЛЕДНИЙ_ДНЕВНИК"] = дневник
    прошлый_мир = load_world(a.world)    # чтобы заметить ответ, данный на ходу
    next_call = 0
    base_enemy = None
    pending = None                       # (поток, коробка) с решением в работе
    ведёт_раш = a.fallback               # эталон раша, только если попросили
    волна_была = False                   # уходил ли хоть кто-то в атаку
    волны: list = []                     # (игровая секунда, сколько бойцов)
    чужая_волна: list = []               # сказали ли уже про волну прошлой партии
    # Первое состояние новой партии приходит с полем ПРОШЛОЙ: эпизод сменился,
    # а парсер br_hwave в игре — нет.
    снять_чужую_волну(st, волны, чужая_волна)
    сбоев_подряд = 0
    next_fb = 0
    next_alive = 0
    next_attack = 0                      # не гнать волны чаще, чем они доходят
    сказано_про_403 = False
    было_st: dict | None = None          # состояние на миг прошлого решения
    прошлый_заказ: list = []             # что тогда заказали, для проверки
    расхождение: list[str] = []          # названо в тексте, но не отдано командой
    брак: list[str] = []                 # что мост не разобрал в прошлом ответе
    вето_волны = ""                      # волну отверг сам мост, а не игра
    вмешательство = ""                   # мост подменил команду — сказать модели
    повторы: dict = {}                   # сколько тактов подряд заказ не проходит
    прошлые_подсказки = ""               # чтобы заметить правку на ходу
    if ведёт_раш:
        print("до первого ответа модели строит эталон раша — игра не простаивает")
    t0, gt0 = time.time(), int(st.get("gametime", 0)) if st else 0
    паузы: list[float] = []              # реальные секунды между записями состояния
    прошлое_чтение = time.time()

    def темп_игры() -> None:
        """Как часто игра писала состояние. Цикл забирает готовый ответ только
        после свежей записи, поэтому её темп — нижняя граница запаздывания."""
        if len(паузы) > 2:
            п = sorted(паузы)
            print(f"игра писала состояние: медиана {п[len(п)//2]:.1f} с, "
                  f"худшая пауза {п[-1]:.1f} с, записей {len(п)}")

    # Первый вызов уходит сразу, на уже прочитанном состоянии: ожидание свежего
    # стоило ещё одного тика ИИ, то есть 2-5 секунд до первого решения.
    if st:
        gt_н = int(st.get("gametime", 0))
        next_call = gt_н + a.every
        прошлые_подсказки = load_hints(a.hints)
        коробка: dict = {"gt": gt_н, "t": time.time()}
        поток = threading.Thread(
            target=think_worker,
            args=(коробка, client, a.model,
                  situation(st, br.read_map() or {}, [], прошлые_подсказки,
                            None, [], a.allow_restart, мир=load_world(a.world)),
                  a.think, a.tries, a.spare),
            daemon=True)
        поток.start()
        pending = (поток, коробка)
        print(f"первый запрос ушёл на {gt_н} игровой секунде")
    slow_after = a.every / 1.38          # 1,38× — замер из HANDOFF, уточним по факту
    while True:
        try:
            st = br.wait_state(timeout=30)
            снять_чужую_волну(st, волны, чужая_волна)
        except TimeoutError:
            # Состояние встало. Это НЕ повод гадать: у игры надо спросить.
            # Пульс интерфейса переживает паузу конца партии, а последняя
            # строка состояния успевает назвать исход в большинстве случаев.
            исход = br.outcome()
            if исход:
                return конец_партии(a, br, исход, br.raw.get("gametime", 0))
            # d здесь не существует: каталог знает только мост. Из-за этого
            # диагностика конца партии падала NameError поверх TimeoutError.
            stalled(br.save_dir, plind, no_mode=a.no_mode)
            return "обрыв"
        _т = time.time()
        паузы.append(_т - прошлое_чтение)
        прошлое_чтение = _т
        gt = int(st.get("gametime", 0))
        # Исход приходит той же строкой состояния, что и всё остальное. Ждать
        # тридцатисекундного обрыва, чтобы узнать о поражении, незачем.
        if st.get("victory") in ("win", "lose"):
            return конец_партии(a, br, str(st["victory"]), gt)
        mp = br.read_map()
        # Марш по контракту модели живёт МЕЖДУ её решениями: такт 20 игровых
        # секунд плюс ответ модели, а сбор и удар надо вести каждый такт.
        шаг_марша(st, br, gt, волны, дневник)
        if int(st.get("my_agressors", 0) or 0) > 0:
            волна_была = True
        for p in range(8):
            # Человеческий блок кладёт крестьян врага прямо в состояние: файла
            # карты он не пишет, вся картина собирается одним проходом.
            _ист = mp if f"p{p}_peasants" in mp else st
            if st.get(f"p{p}_enemy") and f"p{p}_peasants" in _ист:
                en = int(_ист[f"p{p}_peasants"])
                # Сравниваем с ПРОШЛЫМ значением, а не с начальным.
                #
                # 13.09: прежняя проверка держала base_enemy = первое
                # увиденное число (18) и требовала упасть НИЖЕ него. Враг при
                # этом растёт до 55, и чтобы мост заметил ОДНОГО убитого,
                # пришлось бы убить тридцать семь. Разбор семи прогонов: в пяти
                # из них крестьяне врага падали после наших волн — 54->51,
                # 58->55, 54->47->44, 56->52, 56->53 — и каждый раз мост
                # отрапортовал «цель не взята».
                #
                # То есть бот брал цель, а инструмент этого не видел. Хуже
                # молчания: он говорил обратное.
                # ПОБЕДА: у противника не осталось крестьян. Это и есть цель
                # эпизода с 17.09. Движок засчитывает выбывание, когда у игрока
                # нет ни ратуши, ни ЗАНЯТЫХ ЖИЛЫХ МЕСТ (progress.inc:130), а
                # занимают их люди — значит ноль крестьян это та же черта,
                # только видимая нам числом в состоянии.
                if en == 0 and волна_была:
                    mm, ss = divmod(gt, 60)
                    print()
                    темп_игры()
                    print(f"ПОБЕДА на {mm}:{ss:02d}: у противника НОЛЬ крестьян")
                    отметить_конец(a, st, gt, "победа")
                    return "победа"
                if base_enemy is None:
                    base_enemy = en
                elif en < base_enemy:
                    mm, ss = divmod(gt, 60)
                    if not волна_была:
                        # 11.09.2026: партия без единого бойца и без единой
                        # ATTACK отрапортовала «цель достигнута». Крестьяне у
                        # врага убывают и сами по себе, так что падение счётчика
                        # без нашей волны — не результат, а совпадение.
                        print(f"\n{mm}:{ss:02d}  у врага стало меньше крестьян "
                              f"({base_enemy} -> {en}), НО МЫ НИКОГО НЕ ПОСЫЛАЛИ "
                              f"— это не наша заслуга, партия продолжается")
                        base_enemy = en
                        continue
                    # ВЕХА, А НЕ КОНЕЦ. С 17.09 цель эпизода — ВЫИГРАТЬ партию,
                    # то есть довести крестьян врага до нуля. Убитый крестьянин
                    # показывает, что волна дошла и способна убивать, — партия
                    # после этого ПРОДОЛЖАЕТСЯ. До 17.09 мост обрывал её здесь,
                    # и по 43 волнам base14 нельзя было сказать ничего о том,
                    # что бывает дальше: данных за пределом первой убыли не было.
                    if not ВЕХА_УБИЙСТВО:
                        ВЕХА_УБИЙСТВО.append(gt)
                        print(f"\n{mm}:{ss:02d}  ВЕХА: волна дошла и убила "
                              f"крестьянина ({base_enemy} -> {en}). Это не конец: "
                              f"партия идёт до нуля крестьян у врага")
                    base_enemy = en
                else:
                    # Враг вырос — запоминаем новое число. Без этого сравнение
                    # навсегда остаётся привязанным к старту.
                    base_enemy = en
        el = time.time() - t0
        if el > 60 and gt > gt0:
            slow_after = a.every * el / (gt - gt0)

        # Модель думает в фоне. Пока она думает, цикл продолжает читать
        # состояние и следить за целью — иначе задержка тира ослепляет нас
        # на минуты, а она гуляет от 3 до 240 с и не лечится выбором модели.
        if pending is None and gt >= next_call:
            next_call = gt + a.every
            box: dict = {"gt": gt, "t": time.time()}
            подсказки = load_hints(a.hints)
            if подсказки != прошлые_подсказки:
                if прошлые_подсказки:
                    print(f"        подсказки изменились ({len(подсказки)} симв.) — "
                          f"учтены с этого решения")
                прошлые_подсказки = подсказки
            мир_текст = load_world(a.world)
            if a.world and мир_текст != прошлый_мир:
                if прошлый_мир:
                    print(f"        мир изменился ({len(мир_текст)} симв.) — "
                          f"учтён с этого решения")
                прошлый_мир = мир_текст
            prompt = situation(st, mp, history, подсказки,
                               было_st, прошлый_заказ, a.allow_restart,
                               расхождение, повторы, брак, волны, вето_волны,
                               вмешательство, мир=мир_текст,
                               дневник=дневник.строки() if дневник else None)
            # Кладём запрос в коробку: ответ приходит асинхронно, и к моменту
            # записи трассы контекст такта уже сменился. Без этого в трассе
            # осталось бы решение без обстановки, из которой оно выросло.
            box["prompt"] = prompt
            if a.dump_prompt:
                try:
                    # дописываем, а не перезаписываем: при --replay нужен весь
                    # ряд запросов, чтобы видеть, как блоки меняются по тактам.
                    # Файл обнуляется один раз при запуске, в main().
                    with open(a.dump_prompt, "a", encoding="utf-8") as f:
                        f.write(f"\n\n# решение на {gt} игровой секунде\n\n")
                        f.write("### SYSTEM\n" + SYSTEM + "\n\n### ЗАПРОС\n" + prompt)
                except OSError:
                    pass                    # диагностика не должна ронять партию
            th = threading.Thread(target=think_worker,
                                  args=(box, client, a.model, prompt, a.think,
                                        a.tries, a.spare),
                                  daemon=True)
            th.start()
            pending = (th, box)

        # Пока модель молчит, игра не должна стоять: держим цели эталона раша.
        # Команды декларативные, так что перехват модели ничего не ломает.
        if ведёт_раш and gt >= next_fb:
            next_fb = gt + 10
            фб = rush_plan(st, a.wave, minimal=True)
            if фб and br.send(фб):
                br.wait_consumed(timeout=15)
            # Раш молчалив, и без этой строки лог выглядит мёртвым, хотя
            # партия идёт. Раз в минуту показываем, что мы живы.
            if gt >= next_alive:
                next_alive = gt + 60
                mm, ss = divmod(gt, 60)
                цепь = " ".join(("+" if ok else "-") + n for n, ok, _ in stages(st))
                кто = "раш" if фб else "раш (целей нет)"
                print(f"{mm}:{ss:02d}  [{кто}] {цепь}")

        if pending is None or pending[0].is_alive():
            continue                        # решение ещё готовится — не ждём
        _, box = pending
        pending = None
        wait = time.time() - box["t"]
        if "err" in box:
            if REPLAY and _REPLAY_I >= len(REPLAY):
                # Реплей кончился — эпизод окончен. По горизонту это не поймать:
                # у мока игровое время своё и с нуля не начинается.
                print()
                темп_игры()
                print(f"ответы для --replay кончились ({len(REPLAY)}) — эпизод окончен")
                return "реплей"
            сбоев_подряд += 1
            print(f"модель не ответила за {wait:.0f} с:")
            for стр in box.get("log", []):
                print(f"        {стр}")
            текст = str(box["err"])
            if "402" in текст or "insufficient" in текст.lower():
                print("        ДЕНЬГИ КОНЧИЛИСЬ на счету провайдера (402). Ни один\n"
                      "        вызов не пройдёт, партия доиграется вслепую.\n"
                      "        Пополнить: openrouter.ai/credits, проверить остаток:\n"
                      "        python llm_policy.py --credits")
            if ("403" in текст or "401" in текст) and not сказано_про_403:
                сказано_про_403 = True
                if "rate-limited" in текст or "429" in текст:
                    print("        провайдер держит лимит на эту модель. Свой ключ\n"
                          "        провайдера даёт собственные лимиты:\n"
                          "        openrouter.ai/settings/integrations")
                elif "unsupported_country" in текст:
                    print("        провайдер не обслуживает регион — исключён,\n"
                          "        следующие запросы пойдут мимо него")
                else:
                    print("        403/401 — проверьте баланс openrouter.ai/credits\n"
                          "        и настройки openrouter.ai/settings/privacy")
            if сбоев_подряд >= 2 and not ведёт_раш and a.fallback:
                ведёт_раш = True
                print("        два сбоя подряд — за пульт эталон раша, партия идёт")
            if сбоев_подряд == 5:
                print("        пять сбоёв подряд: модель фактически недоступна,\n"
                      "        дальше играет раш. Прервать — Ctrl+C")
            continue
        сбоев_подряд = 0
        подхват = ведёт_раш
        ведёт_раш = False
        # Имена апгрейдов берём из состояния: список зависит от нации и
        # приходит в поле upg_avail как «eurmil.1=food+140,...».
        _дост = {x.split("=", 1)[0].strip()
                 for x in str(st.get("upg_avail", "") or "").split(",")
                 if x.strip()}
        (cmds, attack, why, брак, цель_атаки,
         движение, цель_движения, клетка, контракт) = to_commands(box["data"], _дост)
        # Заниженная волна. Считаем ЗДЕСЬ, а не у отправки ниже: трасса такта
        # пишется раньше отправки, и вето, посчитанное позже, в неё не попало бы
        # — а именно по трассе потом разбирают партию.
        #
        # Порога накопления НЕТ нарочно: мост не держит волну, когда бойцов мало
        # (вето в этом проекте уже съедало волны — 11.09 так пропали все 15
        # команд ATTACK). Отвергаем ровно один случай: свободных хватает на
        # полную волну, а просят горстку. 12.09 это и убило партию — 14 волн по
        # 4-5 бойцов при 23-28 в строю гибли поодиночке.
        вето_волны = ""
        вмешательство = ""
        if attack and a.wave_min:
            _св = int(st.get("my_freewar", 0) or 0)
            _аг = int(st.get("my_agressors", 0) or 0)
            if attack < a.wave_min and _св + _аг >= a.wave_min:
                вето_волны = (
                    f"ATTACK {attack} на {цель_атаки}: НЕ ОТПРАВЛЕН МОСТОМ. "
                    f"Просишь {attack} бойцов, а послать можно {_св + _аг} "
                    f"(свободных {_св}, пул {_аг}). Меньше {a.wave_min} за раз "
                    f"не отправится: {attack} бойцов у вражеской базы — это одна "
                    f"проигранная стычка, а не волна. Собери всех и проси не "
                    f"меньше {a.wave_min}")
        # Пока ратуши нет — потолок строителей ставит МОСТ, а не модель.
        # Проверяется идея игрока от 13.09: партия начинается БЕЗ ратуши
        # (centers=0, замерено по трассе), а бот ставил её тремя строителями из
        # восемнадцати, хотя в котлован влезает двенадцать (wip='center/12').
        # Всё это время остальные рубили дерево, которое некуда сдавать.
        #
        # Почему потолок, а не приказ строить: BUILDERS действует на КАЖДУЮ
        # НОВУЮ стройку, поднимать его после закладки бесполезно. Значит поднять
        # надо ДО того, как модель закажет ратушу, — то есть с первого такта.
        принуждение = ""
        # ПРИЦЕЛ. Цель партии - крестьяне врага, а base и army ведут волну к
        # ЗДАНИЮ: block_hcmd.inc:970, `if (hatrg <> 'peasants') and (haeb)`.
        # Модель это знает - 17.09 промпту добавили прямую фразу, - и всё равно
        # шлёт подкрепления к постройке: доля приказов по крестьянам выросла с 6
        # процентов лишь до 9. Здесь мост правит цель и говорит об этом вслух,
        # чтобы модель видела подмену, а не гадала.
        if getattr(a, "aim_peasants", False) and attack and цель_атаки in ("base", "army"):
            было_цель = цель_атаки
            цель_атаки = "peasants"
            вмешательство = принуждение = (
                f"ATTACK {attack} -> {было_цель} ПЕРЕВЕДЁН МОСТОМ на peasants: "
                f"{было_цель} ведёт бойцов к ЗДАНИЮ, а победа считается по "
                f"крестьянам врага. Отключается ключом --aim-peasants")
        if a.builders_first and int(st.get("centers", 0) or 0) == 0:
            было = next((c for c in cmds if c.cmd == "BUILDERS"), None)
            if not было or было.a1 != a.builders_first:
                cmds = [c for c in cmds if c.cmd != "BUILDERS"]
                # ПЕРВОЙ в списке, а не последней: блок команд исполняет их по
                # порядку, и потолок, поставленный после BUILD, применился бы
                # только к следующей стройке — то есть ровно не к той ратуше,
                # ради которой всё и затевалось.
                cmds.insert(0, builders(a.builders_first))
                вмешательство = принуждение = (
                    f"BUILDERS {a.builders_first} ПОСТАВЛЕН МОСТОМ вместо "
                    f"{('BUILDERS ' + str(было.a1)) if было else 'ничего'}: "
                    f"ратуши ещё нет (centers=0), и до неё потолок строителей "
                    f"держит мост. Отключается ключом --builders-first 0")

        # Что РЕАЛЬНО уйдёт в игру. Не по JSON модели: команду с негодной ролью
        # to_commands выбрасывает молча, и для проверок это тоже «не отдано».
        # Вето мостом сюда НЕ входит: команда в ответе была, и упрёк «написала
        # про ATTACK, а команды нет» стал бы ложью. Про вето говорит свой блок.
        отдано_слова = {c.cmd for c in cmds} | ({"ATTACK"} if attack else set())
        mm, ss = divmod(box["gt"], 60)
        n = box.get("tries", 1)
        помета = f"   [с {n}-й попытки]" if n > 1 else ""
        if box.get("model") and box["model"] != a.model:
            помета += f" [запасная: {box['model'].split('/')[-1]}]"
        print(f"{mm}:{ss:02d}  {why}{помета}")
        if подхват:
            print("        модель забирает пульт у эталона раша")
        for строка in рассказ(box["data"]):
            print(строка)
        if a.lessons:
            _лж = притязание_без_команды(
                str(box["data"].get("lesson", "") or ""), отдано_слова)
            if _лж:
                # Урок про действие, которого не было, — не материал для
                # проверки гипотез, а ложь, которую следующий читатель примет
                # за факт. В журнал не пишем, но показываем, что отбросили.
                print(f"        УРОК ОТБРОШЕН: пишет «{_лж[0]}», а команды "
                      f"{_лж[1]} в этом ответе не было")
            else:
                _у = записать_урок(box["data"], a.lessons, номер_эпизода, gt,
                                   a.lessons_after)
                if _у:
                    print(f"        УРОК -> {a.lessons}: {_у}")
        if a.world:
            _в = " ".join(str(box["data"].get("question", "") or "").split())
            if _в and _в.lower() not in ("none", "null", "-"):
                if len(_в) < 12:
                    print(f"        ВОПРОС ОТБРОШЕН: слишком короткий — «{_в}»")
                elif вопросов_задано >= a.questions:
                    print(f"        ВОПРОС ОТБРОШЕН: за партию их {a.questions}, "
                          f"а этот уже {вопросов_задано + 1}-й — «{_в[:70]}»")
                else:
                    _зап = записать_вопрос(a.world, _в, номер_эпизода, gt)
                    if _зап:
                        вопросов_задано += 1
                        globals()["ВОПРОС_ЗАДАН"] = _зап
                        print(f"        ВОПРОС -> {a.world}: {_зап}")
                    else:
                        print(f"        ВОПРОС ОТБРОШЕН: такой уже задан и ждёт "
                              f"ответа — «{_в[:70]}»")
        # Модель может попросить новую партию. Порог в 120 игровых секунд —
        # чтобы «плохое начало» не превращалось в бесконечный перезапуск.
        if a.allow_restart and box["data"].get("restart") and gt >= 120:
            print(f"        модель просит новую партию: "
                  f"{str(box['data'].get('restart_why', ''))[:100]}")
            return "рестарт"
        if wait > slow_after:
            печ = max(0, int(gt - box["gt"]))
            думала = (box.get("ready", 0) - box["t"]) if box.get("ready") else 0
            лежало = wait - думала if думала else 0
            # 11.09.2026: на игровой машине --check давал 1,5-2 с, а эта строка
            # показывала 48 — потому что мерила не работу модели, а время до
            # момента, когда цикл забрал готовый ответ. Между тем цикл сидит в
            # wait_state и ждёт, пока игра запишет новое состояние. Теперь
            # видно, кто именно виноват.
            кто_и_сколько = ""
            if box.get("provider") or box.get("tokens"):
                кто_и_сколько = (f", {box.get('tokens', 0)} токенов"
                                 + (f" через {box['provider']}" if box.get("provider") else ""))
            откуда = (f" (модель {думала:.0f} с, ждал забора {лежало:.0f} с"
                      f"{кто_и_сколько})" if думала else "")
            print(f"        решение готовилось {wait:.0f} с при бюджете такта "
                  f"{slow_after:.0f} с{откуда} — применяется на {печ} "
                  f"игровых секунд позже")
        for c in cmds:
            print(f"        {c.cmd} {c.a1} -> {c.a2}" + (f" {c.upg}" if c.upg else ""))
        if attack:
            print(f"        ATTACK {attack} -> {цель_атаки}")
        if движение:
            print(f"        MOVE {движение} -> {цель_движения}")
        if вето_волны:
            print(f"        ВЕТО МОСТА: {вето_волны}")
        if принуждение:
            print(f"        МОСТ ВМЕШАЛСЯ: {принуждение}")
        for _б in брак:
            print(f"        НЕ УШЛО В ИГРУ: {_б}")
        # Сжатая строка такта для критика: ресурсы, люди, армия, команды.
        # Это то, чего ему не хватало: по дневнику не видно ни золота, ни
        # свободных крестьян, а он именно по ним и должен судить.
        try:
            _ц = lambda k: st.get(k, "?")
            _кмд = " ".join(f"{c.cmd}:{c.a1}={c.a2}" for c in cmds) or "—"
            if attack:
                _кмд += f" ATTACK:{attack}->{цель_атаки}"
            _мм, _сс = divmod(int(float(st.get("gametime", 0) or 0)), 60)
            # Крестьяне врага — наша мера цели; ключ зависит от номера слота.
            # ТОЛЬКО чужие слоты: имена вида p<номер>_<что>. Хвост "_inf"
            # ловит и СВОЁ mil_inf, и строка критика показала бы нашу пехоту
            # как вражескую — поймано на моке 16.09.
            _взято_апгр = len(взятые_апгрейды(st))
            _вражьи = {k: v for k, v in st.items() if _ПОЛЕ_ВРАГА.match(k)}
            _вражкр = next((v for k, v in _вражьи.items()
                            if k.endswith("_peasants")), "?")
            _вражарм = next((v for k, v in _вражьи.items()
                             if k.endswith("_army")), "?")
            _вражшахт = next((v for k, v in _вражьи.items()
                              if k.endswith("_mines")), "?")
            def _вражпо(*хвосты):
                "п12/с8/к4 — состав врага, только ненулевое; пусто, если нечего сказать"
                _ч = []
                for _х, _б in хвосты:
                    _з = next((v for k, v in _вражьи.items() if k.endswith(_х)), 0)
                    try:
                        _з = int(float(_з or 0))
                    except (TypeError, ValueError):
                        _з = 0
                    if _з:
                        _ч.append(f"{_б}{_з}")
                return "(" + "/".join(_ч) + ")" if _ч else ""
            _вражсост = _вражпо(("_inf", "п"), ("_shoot", "с"), ("_cav", "к"))
            _вражшсост = _вражпо(("_mgold", "з"), ("_miron", "ж"), ("_mcoal", "у"))
            _хвост = ""
            _с = str(st.get("wip", "") or "")
            if _с:
                _хвост += f" строится={_с}"
            _н = str(st.get("cant_now", "") or "").strip()
            if _н:
                _хвост += f" НЕ ПО КАРМАНУ: {_н}"
            _о = " ".join(str(st.get("last_fail", "") or "").split())
            if _о:
                _хвост += f" | отказ: {_о[:90]}"
            ТРАССА_ПАРТИИ.append(
                f"{_мм}:{_сс:02d} еда={_ц('food')} дер={_ц('wood')} кам={_ц('stone')} "
                f"зол={_ц('gold')} жел={_ц('iron')} уг={_ц('coal')} | "
                f"крест={_ц('peasants')} своб={_ц('idle_pea')} "
                f"еда/дер/кам/шахта/стройка="
                f"{_ц('on_food')}/{_ц('on_wood')}/{_ц('on_stone')}/"
                f"{_ц('on_mine')}/{_ц('on_build')} "
                f"(в шахтах з{_ц('on_gold')}/ж{_ц('on_iron')}/у{_ц('on_coal')} "
                f"мест з{_ц('cap_gold')}/ж{_ц('cap_iron')}/у{_ц('cap_coal')}) | "
                f"мест={_ц('my_farmused')}/{_ц('my_farm')} | "
                f"ратуш={_ц('centers')} мельн={_ц('mills')} "
                f"кузн={_ц('smiths')} казарм={_ц('ba17')}"
                # Цена СЛЕДУЮЩЕЙ казармы — тот самый расход, который критик
                # 16.09 принял за нехватку добычи: вторая стоит впятеро дороже.
                + (f"(следующая {цена_построек(st).get('ba17', {}).get('gold', 0)} зол)"
                   if цена_построек(st).get("ba17", {}).get("gold") else "")
                + f" склад={_ц('my_stores')} "
                f"шахты з{_ц('mines_gold')}/ж{_ц('mines_iron')}/у{_ц('mines_coal')} | "
                f"пехота={_ц('mil_inf')} стрелки={_ц('mil_shooters')} "
                f"свободбойц={_ц('my_freewar')} волна={_ц('wave_sent')} "
                f"ушли={_ц('mil_away')} ранены={_ц('mil_hurt')} "
                f"от={_ц('mil_near')}до={_ц('mil_far')} сторона={_ц('mil_side')} | "
                f"апгр_взято={_взято_апгр} "
                f"крестьян_врага={_вражкр} армия_врага={_вражарм}"
                f"{_вражсост} шахты_врага={_вражшахт}{_вражшсост} "
                f"досюда={_ц('en_near_dist')} "
                # Враг у НАШЕЙ базы — иначе критик припишет набег походу.
                f"враг_у_базы={coss3_map.у_базы(st).get('бойцов', 0)} "
                f"марш={МАРШ.get('фаза', '-')} | "
                f"мест_на_земле дер={_ц('wood_slots_free')}/{_ц('wood_slots_near')} "
                f"кам={_ц('stone_slots_free')}/{_ц('stone_slots_near')} | "
                f"{_кмд}{_хвост}")
            _у = " ".join(str(box["data"].get("lesson", "") or "").split())
            if _у:
                УРОКИ_ПАРТИИ.append(f"{_мм}:{_сс:02d} {_у}")
        except Exception:
            pass                        # разбор не должен ронять партию
        if a.botlog:
            # По строке на такт: решение, отданные команды, брак и результат.
            # Лог партии писан для человека, этот — чтобы считать статистику по
            # серии и показывать на защите, что именно делал бот.
            try:
                with open(a.botlog, "a", encoding="utf-8") as _f:
                    _д = box["data"]
                    # Трасса пишется ДЛЯ ОБУЧЕНИЯ, а не для отчёта, поэтому в
                    # ней должно лежать всё, из чего решение выросло: снимок
                    # мира, итог прошлого хода, рассуждение модели целиком и её
                    # гипотезы. Раньше сюда шло только why, и по такой строке
                    # нельзя ни воспроизвести решение, ни оценить его.
                    _снимок = {k: st.get(k) for k in (
                        "gametime", "food", "wood", "stone", "gold", "iron", "coal",
                        "peasants", "idle_pea", "on_food", "on_wood", "on_stone",
                        "on_mine", "on_build", "centers", "mills", "smiths", "ba17",
                        "my_stores", "mines_iron", "mines_gold", "mines_coal",
                        "mil_inf", "mil_shooters", "my_freewar", "my_farm",
                        "my_farmused", "building_now", "wip", "last_fail",
                        # Судьба волны: без неё по трассе снова нельзя отличить
                        # «погибли по дороге» от «дошли и не справились».
                        "wave_sent", "mil_away", "mil_hurt", "mil_far",
                        # Кто в какой шахте и сколько там мест: без этого
                        # BALANCE gold нечем проверить задним числом.
                        "on_gold", "on_iron", "on_coal",
                        "cap_gold", "cap_iron", "cap_coal",
                        "work_gold", "work_iron", "work_coal",
                        "mil_near", "mil_side",
                        "can_now", "cant_now", "fighters", "build_cost",
                        "wood_slots_near", "wood_slots_free",
                        "stone_slots_near", "stone_slots_free",
                        "ore_gold_dist", "ore_gold_near", "ore_gold_side",
                        "ore_iron_dist", "ore_iron_near", "ore_iron_side",
                        "ore_coal_dist", "ore_coal_near", "ore_coal_side",
                        "map_open", "upg_done", "upg_doing", "train_now", "ba_queues", "food_ready",
                        # Сами сетки в трассу не кладём: 32 строки на такт это
                        # мегабайты за серию. Кладём метки — по ним видно, была
                        # ли карта в запросе и где стояла наша база.
                        "grid_n", "my_cx", "my_cy",
                        # Слагаемые готовности к удару. Без них по трассе
                        # нельзя ответить на главный вопрос: с чем модель
                        # посылала волну и был ли строй — а значит нельзя и
                        # сравнить идею с базой.
                        "mil_guns", "my_officers", "my_drummers",
                        "squads", "squad_units", "squad_form",
                        "squad_dmg", "squad_def", "squad_hdmg", "squad_hdef",
                        "can_pea", "can_inf", "famine", "en_near_dist",
                        # Где стоит свой кулак и своя волна: без этого по трассе
                        # не видно, что армия стояла врозь, когда пришёл враг.
                        "my_army_cx", "my_army_cy", "my_army_n",
                        "wave_cx", "wave_cy", "wave_n")
                        if st.get(k) is not None}
                    # Враг у НАШЕЙ базы считается в python по сетке; в трассу
                    # кладём число, иначе набеги по серии не посчитать задним
                    # числом — а 17.09 именно так и потерялись 36 крестьян.
                    _снимок["en_at_base"] = coss3_map.у_базы(st).get("бойцов", 0)
                    # Всё, что состояние знает о чужих слотах: их имена вида
                    # p<номер>_<что>. Перечислять хвосты руками уже нельзя —
                    # 16.09 полей врага стало двадцать, и список бы отстал.
                    _снимок.update({k: v for k, v in st.items()
                                    if _ПОЛЕ_ВРАГА.match(k)})
                    # Что из апгрейдов модель ВИДЕЛА. Целиком `upg_avail` в
                    # трассу не кладём — двести двадцать имён в каждом такте,
                    # это сотни килобайт на партию. А без показанного списка
                    # разбор слеп: 15.09 по трассе серии `upgrades` нельзя было
                    # понять, что военных имён в запросе не было вовсе, и
                    # пришлось читать состояние из живого контейнера.
                    _уа = [у for у in str(st.get("upg_avail", "") or "").split(",")
                           if у.strip()]
                    if _уа:
                        _снимок["upg_shown"] = ",".join(
                            отобрать_апгрейды(_уа, st)[0])
                    _f.write(json.dumps({
                        "gt": box["gt"], "why": why,
                        "ok": str(_д.get("ok", "") or ""),
                        "stuck": str(_д.get("stuck", "") or ""),
                        "cause": str(_д.get("cause", "") or ""),
                        "lesson": str(_д.get("lesson", "") or ""),
                        "idea": str(_д.get("idea", "") or ""),
                        # Вопрос в трассе нужен, даже если мост его отбросил:
                        # по серии видно, о чём модель спрашивает раз за разом,
                        # и это само по себе показывает дыру в описании мира.
                        "question": str(_д.get("question", "") or ""),
                        # Марш по контракту модели: фаза, клетка сбора, порог,
                        # что мост сделал. Без этого по трассе не отличить
                        # «собрались и ударили» от «истёк срок».
                        "march": ({k: v for k, v in МАРШ.items() if k != "отчёт"}
                                  if МАРШ else None),
                        # Чем проверялась эта партия. Без этой строки по трассе
                        # нельзя отделить партии, где гипотеза критика была в
                        # запросе, от партий без неё — а значит нельзя и
                        # измерить, помогает ли она.
                        "critic_hyp": (ГИПОТЕЗА_КРИТИКА.get("гипотеза", "")
                                       if КРИТИК_ВПЕРЁД else ""),
                        # Когда волна впервые дошла и убила: веха отделена от
                        # победы 17.09, и по серии её надо считать отдельно.
                        "веха_убийства": (ВЕХА_УБИЙСТВО[0] if ВЕХА_УБИЙСТВО else None),
                        "state": _снимок,
                        "outcome_prev": _раздел(box.get("prompt", ""),
                                                "## Итог прошлого решения"),
                        "cmds": [{"cmd": c.cmd, "a1": c.a1, "a2": c.a2, "upg": c.upg}
                                 for c in cmds],
                        "attack": attack, "target": цель_атаки,
                        "rejected": брак,
                        # Что просила модель, видно в "attack"; ушло ли это в
                        # игру — только здесь. Без поля разбор трассы считал
                        # заниженную волну ушедшей.
                        "veto": вето_волны,
                        # Что мост поставил вместо модели. Без этого поля в
                        # трассе решение выглядело бы решением модели, и разбор
                        # приписал бы ей чужой ход.
                        "forced": принуждение,
                        "model": box.get("model", a.model),
                        "tokens": box.get("tokens", 0),
                        "provider": box.get("provider", ""),
                        "think_s": round((box.get("ready", 0) - box["t"]), 1)
                                   if box.get("ready") else None,
                    }, ensure_ascii=False) + "\n")
            except OSError:
                pass                        # лог не должен ронять партию
        расхождение = названо_но_не_отдано(
            " ".join(str(box["data"].get(k, "") or "")
                     for k in ("why", "ok", "stuck", "cause", "lesson")),
            отдано_слова)
        for _с in расхождение:
            print(f"        сказано, но не сделано: написала про {_с}, "
                  f"команды {_с} в ответе нет")
        history.append(f"{mm}:{ss:02d} {why}")

        if дневник is not None:
            дневник.такт(st, брак)
        for _c in cmds:
            if _c.cmd == "BALANCE" and _c.a1 == RESOURCE["food"]:
                _кр = int(st.get("peasants", 0) or 0)
                if _c.a2 > _кр:
                    print(f"        BALANCE food {_c.a2} — это ЧИСЛО людей, а "
                          f"крестьян всего {_кр}: на еду уйдут все")
        было_st = st
        прошлый_заказ = [(str(i.get("cmd", "")).upper(), str(i.get("role", "")),
                          int(i.get("count", i.get("total", 0)) or 0)
                          if str(i.get("cmd", "")).upper() == "ATTACK"
                          else int(i.get("total", i.get("count", 0)) or 0))
                         for i in (box["data"].get("commands") or [])[:6]
                         if str(i.get("cmd", "")).upper()
                         in ("BUILD", "TRAIN", "ATTACK", "BALANCE", "UPGRADE")]
        if вето_волны:
            # «Итог прошлого решения» судит только то, что ушло в игру. Оставь
            # здесь отвергнутую волну — и на следующем такте модель прочтёт
            # «НИКТО НЕ ПОШЁЛ, приказ отвергается целиком, если бойцов меньше
            # запрошенного», то есть ложную причину: бойцов-то хватало, отказал
            # мост. Про вето говорит свой блок, здесь волны быть не должно.
            прошлый_заказ = [т for т in прошлый_заказ if т[0] != "ATTACK"]
        if cmds and br.send(cmds):
            br.wait_consumed(timeout=15)
        # MOVE уходит ДО атаки и отдельно от неё: главный случай — движение без
        # боя вовсе, и прятать его внутрь веток ATTACK значило бы потерять.
        # Файл приказа один, поэтому обе команды разом не отдать: to_commands
        # это ловит и говорит вслух.
        if движение:
            св = int(st.get("my_freewar", 0) or 0)
            if св <= 0:
                print(f"        MOVE {движение} не отправлен: свободных бойцов нет "
                      f"— идущие в походе своего приказа не бросают")
            elif not br.attack(движение, цель_движения, mode="move",
                               cx=клетка[0], cy=клетка[1]):
                print(f"        MOVE {движение} не отправлен: прошлый приказ ещё "
                      f"не забран игрой")
            else:
                print(f"        MOVE {движение} -> {цель_движения} (без боя)")
        # Новый приказ модели отменяет идущий марш: решение её, и последнее
        # слово тоже. Отчёт марша при этом уходит из запроса.
        if (attack or движение) and МАРШ:
            МАРШ.clear()
        # ATTACK target=wave: К ВОЛНЕ, а не мимо неё. Клетку волны блок пишет
        # только когда кто-то идёт с приказом (wave_n > 0); иначе идти некуда.
        if attack and not вето_волны and цель_атаки == "wave":
            if _чис(st.get("wave_n")) > 0:
                клетка = (_чис(st.get("wave_cx")), _чис(st.get("wave_cy")))
                цель_атаки = "cell"
                print(f"        ATTACK {attack} -> wave: к волне в клетку "
                      f"({клетка[0]},{клетка[1]})")
            else:
                print(f"        ATTACK {attack} -> wave не отправлен: волны в поле нет, "
                      f"идти не к кому")
                вмешательство = (вмешательство + "; " if вмешательство else "") + (
                    f"ATTACK {attack} -> wave НЕ ОТПРАВЛЕН: в поле нет ни одной твоей "
                    f"волны, идти не к кому. Дай цель peasants, base или cell")
                attack = 0
        # МАРШ: ATTACK с клеткой сбора. Бойцы уходят MOVE в клетку via, дальше
        # мост ведёт марш по контракту (шаг_марша) и бьёт, когда соберутся.
        if attack and not вето_волны and контракт.get("via"):
            св = int(st.get("my_freewar", 0) or 0)
            vx, vy = контракт["via"]
            if st.get("peacemode"):
                print(f"        ATTACK {attack} (марш) не отправлен: перемирие")
            elif св <= 0:
                print(f"        ATTACK {attack} (марш) не отправлен: свободных бойцов нет")
            elif not br.attack(min(attack, св), "cell", mode="move", cx=vx, cy=vy):
                print("        ATTACK (марш) не отправлен: прошлый приказ ещё не забран игрой")
            else:
                n = min(attack, св)
                if n < attack:
                    print(f"        ATTACK {attack} урезан до {n}: столько сейчас свободно")
                начать_марш(gt, n, цель_атаки, клетка, контракт, st)
                волна_была = True
                print(f"        марш: {n} бойцов идут БЕЗ боя в клетку сбора ({vx},{vy}); "
                      f"удар по {цель_атаки}"
                      + (f" ({клетка[0]},{клетка[1]})" if цель_атаки == "cell" else "")
                      + f" — когда соберутся, срок {МАРШ['expires']} с"
                      + (f", порог {МАРШ['hold']}" if МАРШ.get("hold") else ""))
            attack = 0
        if attack and not вето_волны:
            св = int(st.get("my_freewar", 0) or 0)
            аг = int(st.get("my_agressors", 0) or 0)
            if st.get("peacemode"):
                print(f"        ATTACK {attack} не отправлен: перемирие")
            elif a.human and attack > св + аг and св + аг > 0:
                # На ЧЕЛОВЕЧЕСКОМ слоте правила «всё или ничего» нет: block_hcmd
                # набирает волну до запрошенного числа и шлёт сколько набрал.
                # Прежнее вето было списано с компьютерного слота и просто
                # теряло волны: состояние устаревает на время ответа модели
                # (в прогоне 12.09 до 38 с), число свободных за это время
                # меняется, и приказ отменялся целиком. Урезаем и шлём.
                урезано = св + аг
                print(f"        ATTACK {attack} урезан до {урезано}: столько сейчас "
                      f"свободно (свободных {св}, в пуле {аг})")
                attack = урезано
                if not br.attack(attack, цель_атаки,
                                 cx=клетка[0], cy=клетка[1]):
                    print("        ATTACK не отправлен: прошлый приказ ещё не забран игрой")
                else:
                    next_attack = gt + a.attack_every
                    волны.append((gt, attack, цель_атаки))
                    ОТПРАВКА.update(gt=gt, послано=attack, армия=_чис(st.get("mil_inf"))
                                    + _чис(st.get("mil_shooters")))
                    if дневник is not None:
                        дневник.волна(gt, attack, цель_атаки, st)
                    волна_была = True
                    print(f"        волна {len(волны)}: {attack} бойцов ушли на {цель_атаки}")
            elif not a.native_war and attack > св + аг:
                # Раньше здесь стояло вето «агрессоров больше нуля — не слать».
                # Оно било мимо: my_agressors — это ПУЛ бойцов, назначенных в
                # агрессоры, а не идущая волна, и он не пустеет. За серию
                # 11.09.2026 все 15 команд ATTACK были отвергнуты этим правилом.
                # Причину (заказ переформировывал идущую армию) вылечили в
                # block_war.inc: волна набирается СНАЧАЛА из свободных бойцов.
                # Осталась честная проверка: приказ отвергается целиком, если
                # свободных меньше запрошенного.
                print(f"        ATTACK {attack} не отправлен: бойцов всего "
                      f"{св + аг} (свободных {св}, в пуле {аг}) — "
                      + ("собирать некого" if ЧЕЛОВЕК else
                         "игра отвергнет приказ целиком"))
            elif a.native_war and аг > 0:
                print(f"        ATTACK {attack} не отправлен: волна из {аг} уже в пути, "
                      f"повторный приказ переформирует её (нативная атака включена)")
            elif gt < next_attack:
                print(f"        ATTACK {attack} не отправлен: прошлая волна ушла "
                       f"{gt - (next_attack - a.attack_every)} игровых секунд назад, "
                       f"жду до {next_attack}")
            elif not br.attack(attack, цель_атаки,
                               cx=клетка[0], cy=клетка[1]):
                print(f"        ATTACK {attack} не отправлен: прошлый приказ "
                      f"ещё не забран игрой")
            else:
                next_attack = gt + a.attack_every
                волны.append((gt, attack, цель_атаки))
                ОТПРАВКА.update(gt=gt, послано=attack, армия=_чис(st.get("mil_inf"))
                                + _чис(st.get("mil_shooters")))
                волна_была = True
                print(f"        волна {len(волны)}: {attack} бойцов ушли на "
                      f"{цель_атаки}")

        # Горизонт считаем ОТ НАЧАЛА ЭПИЗОДА, а не по абсолютному времени: в
        # игре после NEW часы идут с нуля и разницы нет, а у мока своё время,
        # и абсолютный горизонт обрывал прогон на первом же такте.
        if a.stop_at and gt - gt0 >= a.stop_at:
            # Учебный отрезок: партия обрывается задолго до горизонта, чтобы за
            # то же время сыграть больше партий. Цель при этом НЕ меняется —
            # меняется только длина куска, который мы смотрим.
            print()
            темп_игры()
            _м, _с = divmod(int(a.stop_at), 60)
            print(f"учебный отрезок {_м}:{_с:02d} пройден — начинаю новую партию")
            отметить_конец(a, st, gt, "отрезок")
            return "отрезок"
        if gt - gt0 >= a.horizon:
            print()
            темп_игры()
            print(f"горизонт {a.horizon} исчерпан, цель не достигнута")
            отметить_конец(a, st, gt, "горизонт")
            return "горизонт"


def поля_из_текста(текст: str) -> dict:
    """Четыре поля критика из текста, даже если JSON битый.

    Модель отвечает коротко и по схеме, но иногда ставит лишнее вокруг скобок
    или кавычку внутри строки — и json.loads отказывается. Сам ответ при этом
    полезен, а второй вызов стоит денег и времени.
    """
    из = {}
    for ключ in ("причина", "узкое_место", "гипотеза", "как_проверить"):
        м = re.search(rf'"{ключ}"\s*:\s*"(.*?)"\s*[,}}\n]', текст, re.S)
        if not м:
            м = re.search(rf'"{ключ}"\s*:\s*"([^"]*)', текст, re.S)
        if м:
            з = " ".join(м.group(1).split())
            if з:
                из[ключ] = з
    return из


def разбор_партии(a, client, номер: int, итог: str, дневник) -> str:
    """Критик: один вызов после партии. Возвращает записанное или пусто.

    Зачем отдельной ролью, а не полем в такте: в бою модель занята ходом, и
    выводы у неё получаются про последний такт. Здесь она видит партию целиком
    и не платит за это задержкой — партия уже кончилась.
    """
    if not a.critic:
        return ""
    строки = дневник.строки() if дневник else []
    if not строки and not ТРАССА_ПАРТИИ:
        print("        разбор не делаю: ни дневника, ни трассы (нужен --memo)")
        return ""
    # 15.09: критику давали ТОЛЬКО дневник, и он пять раз из девяти написал «не
    # видно из данных», а в остальных случаях достроил недостающее сам —
    # предлагал строить лесопилку и каменоломню, которых в игре нет. Теперь он
    # получает то же, что видим мы: такты с ресурсами и людьми, и уроки, которые
    # модель писала по ходу партии.
    части = [f"# Партия {номер}, исход: {итог}"]
    if строки:
        части += ["", "## Дневник партии", *строки]
    if ТРАССА_ПАРТИИ:
        части += ["", "## Такты партии (ресурсы, люди, здания, команды)",
                  *ТРАССА_ПАРТИИ]
    if УРОКИ_ПАРТИИ:
        части += ["", "## Что модель заметила по ходу партии", *УРОКИ_ПАРТИИ]
    запрос = "\n".join(части)
    ответ = {}
    try:
        прежний = SYSTEM
        globals()["SYSTEM"] = SYSTEM_CRITIC + уже_проверено()
        try:
            ответ = ask(client, a.model, запрос, a.think, retry=1,
                        max_tokens=3000)
        finally:
            globals()["SYSTEM"] = прежний
    except Exception as e:
        # JSON не собрался — но разбор это не такт, терять его жалко. Ответ
        # критика короткий (замер 14.09: 417 символов), и поля из него
        # вытаскиваются построчно даже когда скобки битые: лишний текст вокруг,
        # кавычка внутри строки, оборванный хвост.
        сырое = str(e)
        ответ = поля_из_текста(сырое)
        if ответ:
            print("        JSON критика битый — разобрал по полям")
        else:
            print(f"        разбор не удался: {сырое[:400]}")
            return ""
    if not ответ:
        print("        разбор пуст: модель не вернула разбираемого JSON")
        return ""
    ГИПОТЕЗА_КРИТИКА.clear()
    ГИПОТЕЗА_КРИТИКА.update(
        {"гипотеза": str(ответ.get("гипотеза", "") or "").strip(),
         "как": str(ответ.get("как_проверить", "") or "").strip(),
         "партия": номер})
    куски = [f"## Партия {номер}: {итог}"]
    for ключ, подпись in (("причина", "Причина"), ("узкое_место", "Узкое место"),
                          ("гипотеза", "Гипотеза"), ("как_проверить", "Как проверить")):
        з = str(ответ.get(ключ, "") or "").strip()
        if з:
            куски.append(f"* **{подпись}:** {з}")
    if len(куски) == 1:
        print("        разбор пуст: модель не заполнила поля")
        return ""
    текст = "\n".join(куски)
    print("\n".join("        " + с for с in текст.splitlines()))
    try:
        with open(a.critic, "a", encoding="utf-8") as f:
            f.write(текст + "\n\n")
    except OSError as e:
        print(f"        разбор не записан ({e})")
    return текст


def показать_счёт(explicit: str = "") -> int:
    """Остаток на счету OpenRouter. Своя ручка, не через OpenAI-клиент.

    Без этого 402 виден только как строка ошибки внутри сбоя вызова, а в бою
    это выглядит как «модель молчит»: 11.09.2026 половина замера ушла в 402,
    и по счётчику сбоёв было не отличить деньги от лимита провайдера.
    """
    import urllib.request
    key, src = load_key(explicit)
    if not key:
        print("нет ключа")
        return 1
    if "openrouter" not in BASE_URL:
        print(f"счёт умеет показывать только OpenRouter, а адрес {BASE_URL}")
        return 1
    req = urllib.request.Request(BASE_URL.rsplit("/v1", 1)[0] + "/v1/credits",
                                 headers={"Authorization": f"Bearer {key}"})
    try:
        d = json.load(urllib.request.urlopen(req, timeout=20))["data"]
    except Exception as e:
        print(f"счёт не отдался: {str(e)[:120]}")
        return 1
    куплено = float(d.get("total_credits", 0))
    потрачено = float(d.get("total_usage", 0))
    print(f"ключ из {src}\nкуплено ${куплено:.2f}, потрачено ${потрачено:.2f}, "
          f"ОСТАТОК ${куплено - потрачено:.2f}")
    if куплено - потрачено < 1:
        print("  меньше доллара — дорогая модель начнёт отвечать 402 уже сейчас:\n"
              "  запрос отвергается, если возможная цена ответа больше остатка")
    return 0


def предпросмотр_подсказок(a) -> int:
    """Что из подсказок реально уйдёт в модель — по звеньям цепочки.

    Между файлом и моделью стоит фильтр: строки с # отбрасываются, а строка с
    меткой звена исчезает, когда звено пройдено. Поэтому «файл изменился» и
    «модель это увидела» — не одно и то же, и вот это их и разводит.
    """
    сырое = load_hints(a.hints)
    print(f"файл {a.hints}: {len(сырое)} символов, {len(сырое.splitlines())} строк\n")
    d = os.path.expandvars(a.dir)
    plind = a.plind if a.plind is not None else find_ai_plind(d, human=a.human)
    живое = None
    if plind is not None:
        живое = Bridge(d, plind).read_state()
    if живое:
        показ = [("сейчас в партии", живое)]
    else:
        print("живой партии нет — показываю для типовых состояний\n")
        показ = [
            ("голый старт", {"peasants": 5, "smiths": 0, "ba17": 0}),
            ("кузница есть", {"peasants": 20, "smiths": 1, "ba17": 0}),
            ("казарма есть", {"peasants": 20, "smiths": 1, "ba17": 1}),
            ("армия и волна", {"peasants": 20, "smiths": 1, "ba17": 1,
                               "mil_inf": 5, "my_armies": 1}),
        ]
    for имя, st in показ:
        текст = отобрать_подсказки(сырое, st)
        цепь = " ".join(("+" if ok else "-") + n for n, ok, _ in stages(st))
        print(f"=== {имя}: {цепь}")
        print(f"    {len(текст)} симв., ~{len(текст) // 3} токенов")
        for стр in текст.splitlines():
            print(f"    | {стр}")
        print()
    отброшено = [l.strip() for l in сырое.splitlines() if l.strip().startswith("#")]
    if отброшено:
        print(f"строк с # отброшено: {len(отброшено)} — в модель они не идут")
    плохие = неизвестные_метки(сырое)
    if плохие:
        print(f"\nВНИМАНИЕ: метки не из списка звеньев: {', '.join(sorted(set(плохие)))}")
        print(f"  звенья только эти: {', '.join(ЗВЕНЬЯ)}")
        print("  строка с чужой меткой видна ВСЕГДА и не исчезнет по ходу партии")
    # Подсказка, помеченная звеном, которое пройдено уже на старте, не дойдёт
    # до модели НИ РАЗУ. Это записано в шапке hints_human.txt с 12.09, и на
    # этом успели споткнуться дважды — поэтому предпросмотр обязан сказать сам,
    # а не полагаться на то, что кто-то помнит.
    НИКОГДА = {"экономика": "звено проходится при peasants>=15, "
                            "а партия начинается с 18"}
    беда = []
    for строка in load_hints(a.hints).splitlines():
        м = re.match(r"\s*\[([^\]]+)\]", строка)
        if м and м.group(1).strip().lower() in НИКОГДА:
            беда.append((м.group(1).strip().lower(), строка.strip()[:70]))
    if беда:
        print()
        print("!" * 60)
        print("ЭТИ СТРОКИ НЕ ДОЙДУТ ДО МОДЕЛИ НИ РАЗУ:")
        for метка, текст in беда:
            print(f"  [{метка}] {текст}")
            print(f"      {НИКОГДА[метка]}")
        print("Снимите метку, если строка нужна всегда.")
        print("!" * 60)
    return 0


def поднять_окно(log: str) -> None:
    """Запускает overlay.ps1 отдельным процессом. Он читает наш лог, так что
    переживает и смену эпизода, и перезапуск скрипта."""
    здесь = os.path.dirname(os.path.abspath(__file__))
    скрипт = os.path.join(здесь, "overlay.ps1")
    if os.name != "nt":
        print(f"окно поверх игры — только Windows; здесь запустите вручную:\n"
              f"        powershell -ExecutionPolicy Bypass -File {скрипт}")
        return
    if not os.path.exists(скрипт):
        print(f"не нашёл {скрипт} — окно не поднял")
        return
    if not log:
        print("окно нечего показывать: --log пустой")
        return
    try:
        subprocess.Popen(
            ["powershell", "-ExecutionPolicy", "Bypass", "-File", скрипт,
             "-Log", os.path.abspath(log), "-ClickThrough"],
            creationflags=getattr(subprocess, "CREATE_NEW_CONSOLE", 0))
        print("окно поверх игры поднято (клики сквозь него уходят в игру)")
    except Exception as e:
        print(f"окно не поднялось ({e}) — запустите overlay.ps1 руками")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", default=os.path.expandvars(os.path.expanduser("~/coss3-io")))
    ap.add_argument("--plind", type=int, default=None)
    ap.add_argument("--model", default=(os.environ.get("COSS3_MODEL")
                                    or os.environ.get("NIM_MODEL")
                                    or DEFAULT_MODEL))
    ap.add_argument("--every", type=int, default=15,
                    help="решение раз в N игровых секунд")
    ap.add_argument("--hints", default="hints.txt",
                    help="файл ИЛИ ссылка http(s) — чтобы править с другой машины")
    ap.add_argument("--lessons-after", type=int, default=60,
                    metavar="сек",
                    help="не записывать уроки раньше этой игровой секунды: до неё это планы")
    ap.add_argument("--ban", default="",
                    metavar="роль,роль",
                    help="роли, запрещённые настройками партии: --ban market,academi")
    ap.add_argument("--lessons", default="lessons.txt",
                    metavar="файл",
                    help="куда складывать наблюдения модели; в промпт они НЕ возвращаются")
    ap.add_argument("--world", default="",
                    metavar="файл",
                    help="файл знаний о мире: уходит в промпт ЦЕЛИКОМ, и туда же "
                         "модель пишет свой вопрос человеку. Пусто — канал выключен")
    ap.add_argument("--max-commands", type=int, default=7, metavar="N",
                    help="сколько команд мост читает за такт (умолчание 7, до 16.09 было 6). "
                         "Меняет и текст промпта: обещать одно, а резать по "
                         "другому нельзя")
    ap.add_argument("--critic-forward", dest="critic_forward",
                    action="store_true",
                    help="возвращать гипотезу критика в СЛЕДУЮЩУЮ партию как "
                         "задание на проверку. Без флага разбор остаётся файлом "
                         "для человека, как было до 17.09")
    ap.add_argument("--schema", dest="schema", action="store_true",
                    help="нативный structured output: форма ответа задаётся "
                         "json-схемой, а не просьбой. Провайдер без схемы — "
                         "мост скажет и доиграет по-старому")
    ap.add_argument("--no-schema", dest="schema", action="store_false",
                    help="не просить нативный structured output. Схему снимают, "
                         "когда провайдер её не держит или когда надо сравнить "
                         "с прежним поведением: доля разобранного брака видна "
                         "в отчёте")
    ap.add_argument("--unfair", dest="fair", action="store_false",
                    help="разрешить мосту подсказывать то, чего человек не "
                         "видит: числа противника сквозь туман войны. По "
                         "умолчанию запрещено — правило игрока от 13.09. На "
                         "открытой карте (--balloon 2) запрет ничего не "
                         "меняет: там эти числа видит и человек")
    ap.set_defaults(fair=True, schema=False)
    ap.add_argument("--critic", default="", metavar="файл",
                    help="разбор партии ПОСЛЕ её конца: один вызов модели на "
                         "дневник партии, ответ дописывается в файл. Нужен "
                         "--memo: разбирать нечего, если дневник не вёлся")
    ap.add_argument("--memo", action="store_true",
                    help="дневник партии в запросе: вехи построек, неудачи без "
                         "повторов, исходы волн. Человек помнит структуру, а не "
                         "протокол; полная история ходов замером 13.09 вредна")
    ap.add_argument("--questions", type=int, default=1,
                    metavar="N",
                    help="сколько вопросов модель может задать за партию (по "
                         "умолчанию один: отвечает человек, и он узкое место)")
    ap.add_argument("--dump-prompt", default="",
                    metavar="файл",
                    help="писать туда промпт последнего решения целиком — видно, что ушло")
    ap.add_argument("--hints-preview", action="store_true",
                    help="показать, что из подсказок уйдёт в модель, и выйти")
    ap.add_argument("--overlay", action="store_true",
                    help="поднять окно поверх игры самому (только Windows)")
    ap.add_argument("--botlog", default="coss3_bot.jsonl",
                    metavar="файл",
                    help="лог ДЕЙСТВИЙ бота по строке JSON на такт: что решил, что "
                         "ушло в игру, что игра ответила. Человеку читать лог партии, "
                         "машине — этот")
    ap.add_argument("--log", default="coss3_llm.log",
                    help="куда дублировать вывод; его показывает overlay.ps1")
    ap.add_argument("--horizon", type=int, default=900)
    ap.add_argument("--stop-at", type=int, default=0, metavar="сек",
                    help="оборвать партию на этой игровой секунде и начать "
                         "следующую. Цель НЕ меняется — это учебный отрезок: "
                         "за то же время больше партий, а значит больше вопросов")
    ap.add_argument("--episodes", type=int, default=1,
                    help="сколько партий отыграть подряд, начиная каждую заново")
    ap.add_argument("--new", action="store_true",
                    help="начать новую партию сразу при запуске, не подхватывать текущую")
    ap.add_argument("--allow-restart", action="store_true",
                    help="разрешить модели просить новую партию полем restart")
    ap.add_argument("--no-mode", action="store_true", help="не выключать нативный ИИ")
    ap.add_argument("--human", action="store_true",
                    help="играем ЧЕЛОВЕЧЕСКИМ слотом: нативного ИИ там нет вовсе, "
                         "команду MODE слать некому, приказы исполняет наш блок в "
                         "progress.inc (правила хакатона)")
    ap.add_argument("--native-war", action="store_true",
                    help="оставить нативную атаку. По умолчанию она выключена и "
                         "волны водит модель: за серию 11.09.2026 все 15 её команд "
                         "ATTACK были отвергнуты, потому что движок держал волну сам")
    ap.add_argument("--key", default="", help="ключ строкой; обычно не нужен")
    ap.add_argument("--compare", nargs="?", const="", default=None,
                    metavar="id,id",
                    help="замерить несколько моделей и выбрать; без списка — свой набор")
    ap.add_argument("--provider-only", default="",
                    metavar="имя,имя",
                    help="слать ТОЛЬКО через этих провайдеров, без запасных")
    ap.add_argument("--no-provider-ban", action="store_true",
                    help="не исключать провайдера автоматически при отказе по региону")
    ap.add_argument("--provider-ignore", default="",
                    metavar="имя,имя",
                    help="не маршрутизировать через этих провайдеров OpenRouter")
    ap.add_argument("--models", nargs="?", const="", default=None,
                    metavar="часть-имени",
                    help="найти модель в каталоге провайдера и выйти")
    ap.add_argument("--check", action="store_true",
                    help="проверить ключ, модель и задержку — и выйти")
    ap.add_argument("--credits", action="store_true",
                    help="остаток на счету провайдера (OpenRouter) — и выйти")
    ap.add_argument("--timeout", type=float, default=60.0,
                    help="сек на вызов; вырожденный ответ не слепит цикл дольше")
    ap.add_argument("--probes", type=int, default=3,
                    help="сколько пробных вызовов делает --check")
    ap.add_argument("--fallback", action="store_true",
                    help="подстраховывать эталоном раша, пока модель молчит")
    ap.add_argument("--no-fallback", action="store_true",
                    help=argparse.SUPPRESS)  # оставлен, чтобы старые команды не падали
    ap.add_argument("--attack-every", type=int, default=0,
                    help="минимум игровых секунд между волнами; 0 — без ограничения. "
                         "Ограничение стояло 30 с, пока волны водил движок и мешали "
                         "друг другу. Теперь цель выбирает модель, и пауза только "
                         "съедала её приказы: за эпизод 11.09.2026 так пропало пять волн")
    ap.add_argument("--wave", type=int, default=5,
                    help="размер волны у подстраховки")
    ap.add_argument("--max-start", type=int, default=0, metavar="СЕК",
                    help="не играть, если партия уже старше СЕК игровых секунд: "
                         "прогон с поздним подключением не сравним с другими. "
                         "0 — только предупредить")
    ap.add_argument("--history", type=int, default=5, metavar="N",
                    help="сколько своих прошлых ходов показывать модели. "
                         "Переписки нет: каждый такт — отдельный вызов, и всю "
                         "память собирает мост. Пять стояли с самого начала и "
                         "никем не проверялись. 0 — не показывать вовсе")
    ap.add_argument("--hints-extra", action="append", default=[], metavar="ФАЙЛ",
                    help="дописать к подсказкам содержимое файла. Так идея "
                         "проверяется КАК ЗНАНИЕ модели, а не как подмена её "
                         "команды мостом. ФАЙЛОМ, а не строкой: многословный "
                         "текст не проходит через COSS3_EXTRA_FLAGS — там "
                         "подстановка с разбиением по пробелам. Можно повторять.")
    ap.add_argument("--hint-add", action="append", default=[], metavar="СТРОКА",
                    help="то же одной строкой. Годится из командной строки "
                         "руками; для идей в контейнере берите --hints-extra.")
    ap.add_argument("--aim-peasants", action="store_true",
                    help="мост переводит ATTACK с base/army на peasants и говорит "
                         "об этом вслух. Зачем: цель партии - крестьяне врага, а "
                         "base и army одинаково ведут волну к ЗДАНИЮ "
                         "(block_hcmd.inc:970). За 47 партий base14 модель отдала "
                         "1652 приказа по базе против 112 по крестьянам, и правда, "
                         "сказанная в промпте 17.09, долю не сдвинула: 9 процентов "
                         "против 6. Слова не работают - проверяем принуждением")
    ap.add_argument("--builders-first", type=int, default=0, metavar="N",
                    help="пока ратуши нет, потолок строителей держит МОСТ: N "
                         "крестьян на стройку (игра всё равно урежет по "
                         "геометрии котлована). 0 — не вмешиваться")
    ap.add_argument("--new-timeout", type=float, default=600.0,
                    help="сколько секунд ждать, пока поднимется новая партия "
                         "(DoNewGame генерирует карту; в контейнере это долго). "
                         "Прежние 240 с стоили прогона critic_forward 17.09: "
                         "карта не поднялась, серия встала на втором эпизоде. "
                         "Замер 17.09 на маке: первая карта поднималась 255 с")
    ap.add_argument("--wave-min", type=int, default=20,
                    help="минимальный размер волны. Мост НЕ держит волну, когда "
                         "бойцов меньше порога: сколько есть, столько и уйдёт. "
                         "Отвергается только ЗАНИЖЕННЫЙ запрос — когда свободных "
                         "хватает на полную волну, а просят горстку. 12.09.2026 "
                         "модель слала по 4-5 бойцов каждые 20 с при 23-28 в "
                         "строю: четырнадцать волн, ~64 бойца, ноль убитых у "
                         "врага, наша пехота качалась 23->17->13->17->23. "
                         "0 — проверку выключить")
    ap.add_argument("--spare", default="",
                    metavar="id",
                    help="запасная модель, если основная упёрлась в лимит")
    ap.add_argument("--tries", type=int, default=3,
                    help="попыток на решение при 500/таймауте (вызов в фоне, повтор бесплатен)")
    ap.add_argument("--replay", default="", metavar="файл",
                    help="играть заранее записанными ответами вместо модели: "
                         "проверка петли без ключа и без игры (см. log_review.py --replay-out)")
    ap.add_argument("--think", action="store_true",
                    help="разрешить модели рассуждать вслух: умнее, но в такт не лезет")
    a = ap.parse_args()

    # Дописки к подсказкам собираем СРАЗУ после разбора ключей. Раньше это
    # делалось внутри одной партии, и --hints-preview показывал подсказки БЕЗ
    # них: то есть проверить идею глазами до прогона было нельзя.
    ДОПИСКИ[:] = [str(x) for x in a.hint_add]
    подготовить_мир(a.world)
    for файл in a.hints_extra:
        путь = файл if os.path.isabs(файл) else os.path.join(
            os.path.dirname(os.path.abspath(__file__)), файл)
        try:
            with open(путь, encoding="utf-8") as f:
                ДОПИСКИ.append(f.read().rstrip("\n"))
            print(f"подсказки дополнены из {файл}")
        except OSError as e:
            # Молчать нельзя: прогон пошёл бы под именем идеи, но БЕЗ неё, и
            # результат выглядел бы законным.
            raise SystemExit(f"--hints-extra {файл}: не прочитан ({e}).\n"
                             f"  Идея без своей подсказки — это не идея, "
                             f"а испорченный опыт. Не начинаю.")
    if ДОПИСКИ:
        print(f"дописок к подсказкам: {len(ДОПИСКИ)}")
        for x in ДОПИСКИ:
            for строка in str(x).splitlines():
                if строка.strip() and not строка.lstrip().startswith("#"):
                    print(f"  + {строка.strip()[:100]}")

    # Диагностическим командам лог не нужен, а раньше они его затирали:
    # `--check` во время боя стирал запись партии.
    диагностика = bool(a.check or a.credits or a.hints_preview
                       or a.models is not None or a.compare is not None)
    if a.log and not диагностика:
        try:
            _sys.stdout = Tee(_sys.stdout, a.log)
        except OSError as e:
            print(f"лог не открылся ({e}) — работаем без него")

    if a.dump_prompt:
        try:
            open(a.dump_prompt, "w", encoding="utf-8").close()
        except OSError:
            pass                            # диагностика не должна ронять запуск

    if a.credits:
        return показать_счёт(a.key)

    if a.hints_preview:
        return предпросмотр_подсказок(a)

    if a.overlay:
        поднять_окно(a.log)

    client = None
    if a.replay:
        n = загрузить_реплей(a.replay)
        print(f"РЕПЛЕЙ: {n} ответов из {a.replay}, модель не зовём")
        if a.lessons == ap.get_default("lessons"):
            a.lessons = "replay_lessons.txt"   # не пачкать настоящий журнал
            print(f"  уроки пишутся в {a.lessons}")

    if not a.replay:                        # реплею ни ключ, ни клиент не нужны
        key, src = load_key(a.key)
        if not key:
            print("нет ключа. Любой из трёх способов, по порядку поиска:\n"
                  "        setx OPENROUTER_API_KEY sk-or-v1-...  (Windows, один раз)\n"
                  f"        положить ключ в {os.path.join(os.path.dirname(os.path.abspath(__file__)), 'nim_key.txt')}\n"
                  "        передать --key sk-or-v1-...\n"
                  "        сам ключ берётся на openrouter.ai/keys")
            return 1
        print(f"ключ из {src}")
        try:
            from openai import OpenAI
        except ImportError:
            print("нужен клиент: pip install openai")
            return 1
        client = OpenAI(base_url=BASE_URL, api_key=key,
                        timeout=a.timeout, max_retries=0)
    BANNED.update(x.strip() for x in a.provider_ignore.split(",") if x.strip())
    ONLY.extend(x.strip() for x in a.provider_only.split(",") if x.strip())
    ЗАПРЕТ.update(x.strip() for x in a.ban.split(",") if x.strip())
    # Казарма XVIII века недостижима БЕЗ АКАДЕМИИ: в восемнадцатый век
    # переводит её исследование, а академия запрещена ПРАВИЛОМ ХАКАТОНА.
    # Пока это не было сказано вслух, критик предлагал «построить вторую
    # казарму ba18» в 21 разборе из 62 - три сессии подряд, - а модель не
    # пробовала ни разу: в состоянии ba18 нет ни в can_now, ни в ценах.
    # Ровно та же история, что со строем 16.09: совет, невыполнимый по
    # правилу, стоит дороже отсутствия совета.
    if "academi" in ЗАПРЕТ:
        ЗАПРЕТ.add("ba18")
    if ЗАПРЕТ:
        неизвестные = ЗАПРЕТ - set(BUILDABLE) - set(ROLE)
        if неизвестные:
            print(f"--ban: неизвестные роли {', '.join(sorted(неизвестные))} — опечатка?")
        print(f"запрещено настройками партии: {', '.join(sorted(ЗАПРЕТ))}")
    globals()["AUTOBAN"] = not a.no_provider_ban
    if ONLY:
        print(f"маршрут только через: {', '.join(ONLY)} (запасных нет)")
    if a.compare is not None:
        models = [m.strip() for m in a.compare.split(",") if m.strip()] or CANDIDATES
        print(f"адрес {BASE_URL}, вызовов на модель {a.probes}\n")
        return compare(client, models, a.think, a.probes, a.every)
    if a.models is not None:
        return list_models(client, a.models)
    if a.check:
        print(f"адрес {BASE_URL}")
        return check(client, a.model, a.think, a.probes, a.every)

    d = os.path.expandvars(a.dir)
    plind = a.plind if a.plind is not None else find_ai_plind(d, human=a.human)
    if plind is None:
        diagnose(d, human=a.human)
        return 1
    br = Bridge(d, plind)
    ep = Episode(br, a.horizon, quiet=45.0, dry=False, speed=0,
                 model=False, policy="none")
    итоги = []
    for номер in range(1, a.episodes + 1):
        if a.new or номер > 1:
            print(f"\n=== эпизод {номер} из {a.episodes}: начинаю новую партию ===")
            if not ep.start(0, 0):
                print("новую партию начать не удалось")
                return 1
            # Три секунды хватало на компьютерном слоте при готовой карте. У
            # новой партии их не хватает вовсе: DoNewGame ГЕНЕРИРУЕТ карту, а в
            # контейнере это делает программный растеризатор. Ждём столько,
            # сколько нужно, и говорим, чего ждём, — молчащее ожидание
            # неотличимо от зависания.
            n, ждём_до = None, time.time() + a.new_timeout
            while time.time() < ждём_до:
                n = find_ai_plind(d, fresh=30, human=a.human)
                if n is not None:
                    break
                time.sleep(2.0)
                if int(ждём_до - time.time()) % 30 < 2:
                    print(f"     жду новую партию, осталось "
                          f"{int(ждём_до - time.time())} с", flush=True)
            if n is None:
                print(f"новая партия не поднялась за {a.new_timeout} с")
                diagnose(d, human=a.human)
                return 1
            if n != plind:
                print(f"слот сменился: P{plind} -> P{n}")
            plind = n
            br = Bridge(d, plind)
            ep.br = br
        итог = одна_партия(a, client, br, plind, номер)
        # ПУСТАЯ ПАРТИЯ — не партия. 17.09 на серии base14 кончились деньги у
        # провайдера (402), модель замолчала, движок засчитал поражение за
        # бездействие, и следующие эпизоды посыпались по нулю тактов: копия 4
        # отдала восемь «поражений» подряд, из них семь без единого хода. В
        # отчёте это выглядело как игра и портило сравнение серий.
        ходов = len(ТРАССА_ПАРТИИ)
        if not ходов:
            итог = "пусто"
        итоги.append(итог)
        print(f"эпизод {номер}: {итог}" + ("" if ходов else
              " — НИ ОДНОГО ХОДА МОДЕЛИ, эта партия в счёт не идёт"))
        разбор_партии(a, client, номер, итог, ПОСЛЕДНИЙ_ДНЕВНИК)
        if a.world:
            # Между партиями это единственный момент, когда человек может
            # ответить. Показываем открытые вопросы прямо здесь, иначе они
            # останутся лежать в файле незамеченными.
            try:
                _зн, _воп = разобрать_мир(open(a.world, encoding="utf-8").read())
            except OSError:
                _зн, _воп = [], []
            _откр = [в for в, о in _воп if not о]
            if _откр:
                print(f"  ВОПРОСЫ БЕЗ ОТВЕТА ({len(_откр)}) — ответить в {a.world}, "
                      f"строкой «  ответ: ...» под вопросом:")
                for _в in _откр:
                    print(f"    • {_в}")
        if итог == "рестарт" and номер >= a.episodes:
            print("модель просила новую партию, но эпизоды кончились")
        if итог == "обрыв" and номер < a.episodes:
            print("состояние встало — следующий эпизод не начинаю")
            break
        if итог == "пусто" and номер < a.episodes:
            # Молчащая модель не станет разговорчивее в следующей партии, а
            # каждая такая партия — мусор в серии. Останавливаемся и говорим,
            # где смотреть причину.
            print("модель не сделала ни одного хода — следующий эпизод не "
                  "начинаю. Причина в policy.log: чаще всего это 402 "
                  "(кончились деньги у провайдера) или лимит на длину запроса")
            break
    if len(итоги) > 1:
        сыграно = [x for x in итоги if x != "пусто"]
        пустых = len(итоги) - len(сыграно)
        победы = sum(1 for x in сыграно if x == "победа")
        вехи = sum(1 for x in сыграно if x == "цель")
        print(f"\nитого: ПОБЕД {победы} из {len(сыграно)} СЫГРАННЫХ эпизодов; "
              f"веха «убит крестьянин врага» взята в {вехи} — {', '.join(итоги)}")
        if пустых:
            print(f"  пустых партий (модель не ходила): {пустых} — они НЕ "
                  f"считаются ни в целях, ни в поражениях")
        # Поражения считаем отдельно от обрывов. До 13.09 они были неразличимы:
        # и то и другое выглядело как «состояние встало», и серия из десяти
        # проигранных партий читалась как десять сломанных прогонов.
        разбор = [(и, sum(1 for x in итоги if x == и))
                  for и in ("цель", "победа", "поражение", "обрыв", "рестарт",
                            "отрезок")]
        print("          " + ", ".join(f"{и}: {n}" for и, n in разбор if n))
    # Код выхода: 0 — партия ВЫИГРАНА (новая цель с 17.09), 2 — нет. Прежняя
    # цель (убит крестьянин врага) осталась вехой и считается отдельно.
    return 0 if "победа" in итоги else 2


if __name__ == "__main__":
    raise SystemExit(main())
